window.KNOWLEDGE_DATA["math-sp"] = {"subject":"math","semester":"sp","stage":"special","label":"专题与压轴","chapters":[{"id":"math-sp-c2","name":"全等与辅助线模型","unit":"专题·全等模型","points":[{"id":"math-sp-p05","name":"倍长中线模型","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["三角形中出现中线 AD 或中点 D，且需要求中线取值范围","已知中点，且待证结论把分散的两边与第三边联系在一起（如 a＋b＞c 或线段倍半关系）","中点处引出两条垂直线段（如 DE⊥DF），要求证两边之和大于第三边"],"steps":["① 锁定中点 D 和经过中点的关键线段（中线 AD 或线段 ED）","② 延长该线段一倍至新点（如延长 ED 到 G 使 DG＝ED），连接另一端点构 8 字型","③ 利用对顶角和中点，用 SAS 证出 8 字全等，把分散的边转移到同一个三角形中","④ 在新构成的三角形中用三边关系、勾股定理或中垂线性质完成证明与计算"],"variants":["基础考法：已知三角形两边求中线取值范围，直接倍长中线用三边关系（最后别忘除以 2）","进阶变式：倍长类比中线（不经过顶点的过中点线段，如 DE），配合垂直平分线转化三条线段","压轴综合：倍长中线构造平行四边形或结合直角三角形斜边中线、旋转全等综合证明"],"parentGuide":{"ask":"看到题目里有“中线”或“中点”，却凑不出全等三角形，第一反应做什么辅助线？","key":"必须答出：倍长中线（或倍长过中点的线段），把中线延长一倍再连线，构造“8 字型”SAS 全等把分散的边搬到一起。"},"examples":[{"title":"变式母题拆解 · 过中点垂直线段的倍长转化","q":"在 △ABC 中，D 是 BC 边的中点，点 E 在 AB 上，点 F 在 AC 上，且 DE⊥DF，求证：BE＋CF＞EF。","eye":"① 题眼是“D 为中点＋DE⊥DF＋三条分散线段的不等关系”，标准倍长过中点线段模型。","method":"② 延长 ED 至 G 使 DG＝ED，连 CG、FG：先用 8 字全等把 BE 搬到 CG，再用 DF 垂直平分 EG 把 EF 搬到 FG。","steps":"③ 规范步骤：延长 ED 至 G 使 DG＝ED，连 CG、FG。由 BD＝CD、∠BDE＝∠CDG、ED＝GD 得 △BDE≌△CDG（SAS），故 CG＝BE。因 DF⊥EG 且 DG＝ED，故 DF 垂直平分 EG，得 FG＝EF。在 △CFG 中 CF＋CG＞FG，即 BE＋CF＞EF。"}]},"card":{"concept":["遇到三角形中线（或中点），把中线延长一倍（如延长 AD 到 E 使 DE＝AD），连接 BE，立刻构造“8 字型全等” △ADC≌△EDB！","作用：把分散的两边 AC、AB 和 2 倍中线 2AD 集中到同一个三角形 △ABE 中！"],"formula":["中线取值范围公式：|AB－AC|/2 ＜ AD ＜ (AB＋AC)/2。"],"pitfall":["别忘了倍长的是 2AD，最后求 AD 范围要除以 2！"],"example":{"q":"如图，△ABC 中 AB＝8，AC＝6，AD 是中线，求 AD 的取值范围。","a":"倍长 AD 到 E 使 DE＝AD，BE＝AC＝6；在 △ABE 中 8－6＜2AD＜8＋6，得 1＜AD＜7。","img":"./assets/knowledge/math/sp/p05-dblmed.svg"}},"qids":["kp-math-sp-p05-01","kp-math-sp-p05-02","kp-math-sp-p05-03","kp-math-sp-p05-04","kp-math-sp-p05-05","kp-math-sp-p05-06","kp-math-sp-p05-07","kp-math-sp-p05-08","kp-math-sp-p05-09"],"refs":[]},{"id":"math-sp-p06","name":"截长补短模型","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["几何证明结论出现“长线段＝短线段₁＋短线段₂”（或两短边之差）","条件中含有角平分线，或者两个内角存在 2 倍角关系（如 ∠B＝2∠C）","平行四边形/梯形中出现中点与角平分线，要证腰等于上下底之和"],"steps":["① 选定路线：截长（在长边上截一段等于某短边）或补短（延长某短边补上另一短边）","② 若有角平分线，优先用“截长”把角平分线作为公共边构造对称 SAS 全等","③ 证完第一对全等后，把剩余角通过外角或平行倒角证出等腰三角形","④ 用“等角对等边”收口，拼合出完整线段和差关系"],"variants":["基础考法：角平分线＋2 倍角模型，直接截长一次 SAS 加等腰收尾","进阶变式：梯形或平行线间中点＋角平分线，延长角平分线构 8 字全等（天然补短）","压轴综合：四边形对角互补＋角平分线，截长补短与旋转 90°/60° 结合证明线段和差"],"parentGuide":{"ask":"题目让你证一条长边等于两条短边相加（比如 AC＝AB＋BD），常用的两招辅助线叫什么？","key":"必须答出：截长补短；截长是在长边上截一段等于一条短边再证剩下相等，补短是延长短边拼成一条长边再证全等或等腰。"},"examples":[{"title":"变式母题拆解 · 平行线＋中点＋角平分线的补短妙招","q":"在四边形 ABCD 中，AD∥BC，点 E 是 CD 的中点，AE 平分 ∠BAD，求证：AB＝AD＋BC。","eye":"① 题眼集齐“结论 AB＝AD＋BC”“AD∥BC”“中点 E”“角平分线 AE”，延长 AE 交 BC 延长线一箭双雕。","method":"② 延长 AE 交 BC 的延长线于 F，借助平行与中点证 8 字全等补出 CF＝AD，再用平行＋角平分线出等腰 AB＝BF。","steps":"③ 规范步骤：延长 AE 交 BC 延长线于 F。因 AD∥BC，得 ∠D＝∠ECF，∠DAE＝∠F。又 DE＝CE，故 △ADE≌△FCE（AAS），得 AD＝CF。因 AE 平分 ∠BAD，得 ∠BAE＝∠DAE＝∠F，故 AB＝BF＝BC＋CF＝AD＋BC。"}]},"card":{"concept":["要证明“一条长线段等于两条短线段之和”（如 AC＝AB＋BD），常用截长补短法：","截长：在长边 AC 上截取 AE＝AB，再证剩余段 EC＝BD；","补短：延长短边 AB 到 F 使 BF＝BD，再证 AF＝AC。"],"formula":["常见触发条件：题目中出现“角平分线＋a＋b＝c”或“2 倍角关系”！"],"pitfall":["截长后先证第一对全等（常用 SAS），再借助等腰或角关系证剩余两段相等。"],"example":{"q":"如图，AD 平分 ∠BAC，∠B＝2∠C，AB＝5，BD＝3，用截长法求 AC。","a":"在 AC 上截 AE＝AB＝5，由 SAS 得 △ABD≌△AED ⇒ DE＝BD＝3，∠AED＝∠B＝2∠C ⇒ ∠EDC＝∠C ⇒ EC＝DE＝3，故 AC＝5＋3＝8。","img":"./assets/knowledge/math/sp/p06-cut.svg"}},"qids":["kp-math-sp-p06-01","kp-math-sp-p06-02","kp-math-sp-p06-03","kp-math-sp-p06-04","kp-math-sp-p06-05","kp-math-sp-p06-06","kp-math-sp-p06-07","kp-math-sp-p06-08","kp-math-sp-p06-09"],"refs":[]},{"id":"math-sp-p07","name":"手拉手旋转全等模型","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["图形中出现两个共顶点的等边三角形、等腰直角三角形或正方形","需要证明两条斜交线段（拉手线）相等、垂直或夹 60° 角","动点旋转过程中图形位置不断变化，但两条连线的夹角始终不变"],"steps":["① 找旋转中心：锁定两个正多边形或等腰三角形共享的那个顶点 O","② 找对应拉手：把“左手连左手、右手连右手”组成的两个三角形框出来","③ 证夹角相等：两相等顶角同加或同减公共角，立刻得 SAS 全等","④ 用 8 字倒角定夹角：由全等对应角加一组对顶角，推出拉手线夹角等于顶角（60° 或 90°）"],"variants":["基础考法：共顶点双等边三角形或双等腰直角三角形，直接证拉手全等与夹角","进阶变式：共顶点双正方形旋转，拉手线相等且垂直，进一步证共顶点到交点连线平分夹角","压轴综合：手拉手相似（顶角相等但腰不成等长而等比），再联动隐圆或瓜豆求最值"],"parentGuide":{"ask":"两个共顶点的等边三角形或者正方形连成“手拉手”，哪两个核心结论几乎每题都考？","key":"必须答出：① 对应拉手线相等（SAS 全等）；② 两条拉手线的夹角等于原来的顶角（等边是 60°，正方形/等腰直角是 90°）。"},"examples":[{"title":"变式母题拆解 · 共顶点双正方形手拉手全等与垂直","q":"正方形 OABC 与正方形 ODEF 共顶点 O（均按顺时针方向排列顶点），连接 AD、CF 交于点 P，判断 AD 与 CF 的数量关系与位置关系并证明。","eye":"① 共顶点 O 的两个正方形天然给出 OA＝OC、OD＝OF 且 ∠AOC＝∠DOF＝90°，标准手拉手。","method":"② 两直角同加 ∠COD 得 ∠AOD＝∠COF，SAS 证 △AOD≌△COF，再用 8 字模型把 90° 倒到交点 P。","steps":"③ 规范步骤：因 ∠AOC＝∠DOF＝90°，同加 ∠COD 得 ∠AOD＝∠COF。又 OA＝OC、OD＝OF，故 △AOD≌△COF（SAS），得 AD＝CF 且 ∠OAD＝∠OCF。设 AD 交 OC 于 G，在 △OAG 与 △PCG 中由对顶角与 ∠OAG＝∠PCG 得 ∠APC＝∠AOC＝90°，故 AD＝CF 且 AD⊥CF。"}]},"card":{"concept":["两个共顶点的等边三角形 / 等腰直角三角形 / 正方形，对应边相连必有 SAS 全等。","核心三大结论：① 拉手线相等（AE＝BD）；② 拉手线夹角等于顶角（60° 或 90°）；③ 共顶点与交点连线平分该夹角！"],"formula":["口诀：共顶点是旋转中心，左手拉左手、右手拉右手，必全等！"],"pitfall":["求拉手线交点处的钝角还是锐角要看清题目要求。"],"example":{"q":"如图，△ABC 与 △CDE 均是等边三角形，A、C、D 共线，AE 与 BD 交于 P，求 AE 与 BD 的数量关系与夹角。","a":"△ACE≌△BCD（SAS），AE＝BD，锐角夹角为 60°。","img":"./assets/knowledge/math/sp/p07-hand.svg"}},"qids":["kp-math-sp-p07-01","kp-math-sp-p07-02","kp-math-sp-p07-03","kp-math-sp-p07-04","kp-math-sp-p07-05","kp-math-sp-p07-06","kp-math-sp-p07-07","kp-math-sp-p07-08","kp-math-sp-p07-09"],"refs":[]},{"id":"math-sp-p08","name":"一线三等角（一线三直角）模型","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["一条直线上依次出现三个直角（或三个相等的角，如三个 60°、三个 45°）","平面直角坐标系中出现等腰直角三角形或正方形，求未知顶点坐标","矩形、梯形边上出现动点构成直角折线，要求证全等或求线段长"],"steps":["① 识别或补全那条“一线”：在坐标系中常过直角顶点作 x 轴或 y 轴垂线/平行线","② 互余（或平角）倒角：由中间等角推出两侧三角形对应锐角相等","③ 判全等或相似：若有相等斜边（等腰直角/正方形）则 AAS 全等；若无等边则 AA 相似","④ 按象限正负还原坐标，或用对应边成比例列方程求解"],"variants":["基础考法：同侧/异侧一线三直角全等，直接求底边线段和或差","进阶变式：坐标系中已知等腰直角三角形两顶点，构造一线三直角秒求第三顶点坐标","压轴综合：抛物线/反比例函数背景下的正方形或等腰直角三角形存在性，用一线三直角列坐标方程"],"parentGuide":{"ask":"如果在坐标系里遇到一个斜放着的等腰直角三角形，怎么快速把第三个点坐标算出来？","key":"必须答出：过直角顶点作坐标轴的垂线（或平行线），构造“一线三直角”全等三角形，把横纵坐标长度互相转化。"},"examples":[{"title":"变式母题拆解 · 坐标系斜放等腰直角三角形秒求坐标","q":"在平面直角坐标系中，A(0, 2)、B(4, 0)，以 AB 为直角边在第一象限内作等腰 Rt△ABC（∠ABC＝90°，AB＝BC），求点 C 的坐标。","eye":"① 题眼是“坐标系＋斜放等腰直角三角形”，靠勾股硬算极麻烦，构造一线三直角一步到位。","method":"② 过点 C 作 CD⊥x 轴于 D，在 x 轴上立刻凑齐 ∠AOB＝∠ABC＝∠BDC＝90°，用 AAS 证全等。","steps":"③ 规范步骤：过 C 作 CD⊥x 轴于 D。由 ∠ABO＋∠CBD＝90° 及 ∠ABO＋∠BAO＝90° 得 ∠BAO＝∠CBD，又 ∠AOB＝∠BDC＝90°、AB＝BC，故 △AOB≌△BDC（AAS）。得 BD＝OA＝2，CD＝OB＝4，所以 OD＝4＋2＝6，点 C 坐标为 (6, 4)。"}]},"card":{"concept":["一条直线上依次出现三个相等的角（最常见是三个 90° 直角：∠B＝∠ACE＝∠D＝90°），通过互余倒角必得 ∠A＝∠ECD，从而两三角形相似；若再有一组对应边相等（如 AC＝CE），则必全等（AAS）！"],"formula":["一线三直角＋等腰直角（AC＝CE）⇒ △ABC≌△CDE ⇒ BD＝AB＋DE（或 |AB－DE|）。"],"pitfall":["在坐标系里考等腰直角三角形顶点坐标，过直角顶点作坐标轴平行线构造一线三直角，秒出坐标！"],"example":{"q":"如图，B、C、D 共线，∠B＝∠ACE＝∠D＝90°，AC＝CE，AB＝4，DE＝3，求 BD。","a":"△ABC≌△CDE（AAS），BC＝DE＝3，CD＝AB＝4，故 BD＝3＋4＝7。","img":"./assets/knowledge/math/sp/p08-3rt.svg"}},"qids":["kp-math-sp-p08-01","kp-math-sp-p08-02","kp-math-sp-p08-03","kp-math-sp-p08-04","kp-math-sp-p08-05","kp-math-sp-p08-06","kp-math-sp-p08-07","kp-math-sp-p08-08","kp-math-sp-p08-09"],"refs":[]},{"id":"math-sp-p09","name":"半角模型（90° 夹 45° / 120° 夹 60°）","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["正方形（90° 角）内部夹着一个 45° 角，且两边交于正方形的两条对边","等腰直角三角形斜边上两点与直角顶点连线夹 45° 角（如 ∠DAE＝45°）","顶角 120° 的等腰三角形或含 60° 菱形内部夹着一个 60° 角"],"steps":["① 认准旋转角：90° 夹 45° 绕顶点旋转 90°；120° 夹 60° 绕顶点旋转 120°","② 旋转拼角：把一侧的小三角形绕大角顶点旋转至等边重合，把分散的两个半角拼成完整半角","③ 证 SAS 全等：利用公共边与拼出的等角证核心全等，立得 EF＝BE＋DF（截长补短）","④ 结合勾股定理：把 EF＝BE＋DF 代入 Rt△CEF 的 CE²＋CF²＝EF² 列方程秒求边长或面积"],"variants":["基础考法：正方形内 45° 半角，求线段长、△CEF 周长（恒等于 2 倍边长）或面积","进阶变式：点 E、F 移到正方形边的延长线上，旋转后结论由 EF＝BE＋DF 变为 EF＝|BE－DF|","压轴综合：等腰直角三角形斜边 45° 半角，旋转 90° 拼出新直角三角形导出 BD²＋CE²＝DE²"],"parentGuide":{"ask":"正方形里夹着一个 45° 半角模型，哪两个秒杀结论背下来做选择填空能省 5 分钟？","key":"必须答出：① 斜线段 EF＝BE＋DF；② 右下角小三角形 △CEF 的周长恒等于正方形边长的 2 倍（2AB）。"},"examples":[{"title":"变式母题拆解 · 半角模型联动勾股定理求面积","q":"正方形 ABCD 的边长为 4，点 E 在 BC 上，点 F 在 CD 上，且 ∠EAF＝45°，若 BE＝1，求 △CEF 的面积。","eye":"① 看到“正方形＋∠EAF＝45°”，立刻调取半角核心结论 EF＝BE＋DF，把未知全塞进 Rt△CEF。","method":"② 旋转 △ABE 使 AB 与 AD 重合证得 EF＝BE＋DF；设 DF＝x，用勾股定理 CE²＋CF²＝EF² 解 x。","steps":"③ 规范步骤：将 △ABE 绕 A 逆时针旋转 90° 得 △ADG，可证 △AEF≌△AGF（SAS），故 EF＝GF＝BE＋DF。设 DF＝x，则 EF＝1＋x，CE＝4－1＝3，CF＝4－x。在 Rt△CEF 中 3²＋(4－x)²＝(1＋x)²，解得 10x＝24，x＝2.4。故 CF＝1.6，S△CEF＝1/2×3×1.6＝2.4。"}]},"card":{"concept":["正方形 ABCD 中，点 E 在 BC、F 在 CD 上且 ∠EAF＝45°：把 △ABE 绕点 A 逆时针旋转 90° 使 AB 与 AD 重合，把分散的两个半角拼成一个完整的 45° 角，立得 SAS 全等！"],"formula":["四大秒杀结论：① EF＝BE＋DF；② △CEF 周长＝2AB；③ 点 A 到 EF 的距离＝AB；④ S△AEF＝1/2·EF·AB。"],"pitfall":["算 △CEF 面积时，结合勾股定理 CE²＋CF²＝EF²，把 EF＝BE＋DF 代入立得方程！"],"example":{"q":"如图，正方形 ABCD 边长 6，∠EAF＝45°，BE＝2，求 DF。","a":"设 DF＝x，则 CF＝6－x，CE＝4，EF＝2＋x；4²＋(6－x)²＝(2＋x)² ⇒ 16＋36－12x＝4＋4x ⇒ 16x＝48 ⇒ x＝3。","img":"./assets/knowledge/math/sp/p09-half.svg"}},"qids":["kp-math-sp-p09-01","kp-math-sp-p09-02","kp-math-sp-p09-03","kp-math-sp-p09-04","kp-math-sp-p09-05","kp-math-sp-p09-06","kp-math-sp-p09-07","kp-math-sp-p09-08","kp-math-sp-p09-09"],"refs":[]}]},{"id":"math-sp-c3","name":"相似与圆综合压轴","unit":"专题·相似与圆","points":[{"id":"math-sp-p10","name":"相似综合（母子型、射影与一线三等角）","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题目出现公共角加一组等角（母子型），或要证乘积式 AC²＝AD·AB","直角三角形斜边上作高，立刻触发“一图三相似”与射影定理","矩形、梯形或平行四边形边上出现直角折线，构成一线三等角相似"],"steps":["① 找模型定相似：优先扫视 A 字型、8 字型、母子型和一线三等角，标出两对相等的角","② 严格对齐顶点顺序写相似（如 △ABE∽△ECF），绝不凭感觉盲写比例","③ 把要求的线段和已知线段挑出来列比例式，交叉相乘化乘积式解方程","④ 涉及面积比或周长比时，先确认是相似比 k 还是相似比的平方 k²"],"variants":["基础考法：直角三角形射影定理或单一母子型直接求边长","进阶变式：矩形边上动点触发一线三直角相似，建立两动线段之间的函数关系","压轴综合：相似结合圆周角、切线或反比例函数面积 k 值，连环转化比例线段"],"parentGuide":{"ask":"如果一个题目要你证明乘积式 AC²＝AD·AB，脑子里第一步应该把它变成什么？","key":"必须答出：改成比例式 AC/AB＝AD/AC，然后找包含这些边的母子型相似三角形（△ACD∽△ABC）用 AA 证明。"},"examples":[{"title":"变式母题拆解 · 矩形中的一线三直角相似","q":"在矩形 ABCD 中，AB＝4，BC＝6，点 E 在边 BC 上且 BE＝2，过点 E 作 EF⊥AE 交 CD 于点 F，求 CF 的长。","eye":"① 矩形提供 ∠B＝∠C＝90°，EF⊥AE 提供中间直角 ∠AEF＝90°，BC 边上立刻构成一线三直角相似。","method":"② 由互余倒角证 △ABE∽△ECF，注意对齐对应直角边 AB 对 EC、BE 对 CF 列比例。","steps":"③ 规范步骤：因为 ∠B＝∠C＝∠AEF＝90°，所以 ∠BAE＋∠AEB＝90°，∠FEC＋∠AEB＝90°，得 ∠BAE＝∠FEC，故 △ABE∽△ECF（AA）。因此 AB/EC＝BE/CF。又 EC＝BC－BE＝6－2＝4，代入得 4/4＝2/CF，解得 CF＝2。"}]},"card":{"concept":["母子型相似：公共角＋一组等角 ⇒ 公共边²＝短段×长段（AC²＝AD·AB）。","直角三角形斜边作高：一图三相似（△ACD∽△CBD∽△ABC），导出射影定理三式。"],"formula":["CD²＝AD·BD；AC²＝AD·AB；BC²＝BD·AB；AC·BC＝AB·CD。"],"pitfall":["写乘积式前先对齐相似三角形的对应字母顺序，防止比例写倒！"],"example":{"q":"如图，Rt△ABC 中 ∠C＝90°，CD⊥AB，AD＝4，BD＝9，求 CD、AC、BC。","a":"CD＝√(4×9)＝6；AC＝√(4×13)＝2√13；BC＝√(9×13)＝3√13。","img":"./assets/knowledge/math/sp/p10-sim.svg"}},"qids":["kp-math-sp-p10-01","kp-math-sp-p10-02","kp-math-sp-p10-03","kp-math-sp-p10-04","kp-math-sp-p10-05","kp-math-sp-p10-06","kp-math-sp-p10-07","kp-math-sp-p10-08","kp-math-sp-p10-09"],"refs":[]},{"id":"math-sp-p11","name":"圆与切线、相似及三角函数综合","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["中考倒数第 2/3 题出现“圆＋切线＋直径＋求半径或三角函数值”","已知角平分线或平行线与圆结合，第一问证切线、第二问求线段或 sin/tan 值","所求锐角三角函数所在的角不在直角三角形里，需要利用同弧圆周角转移"],"steps":["① 辅助线条件反射：见切点连半径得 90°，见直径连弦得 90°，见弦心距作垂径","② 证切线分两类：点在圆上“连半径证垂直”（常用等腰半径＋平行或互余倒角）；点未知“作垂线证等半径”","③ 算半径两大通法：设半径 r 列直角三角形勾股方程，或找母子型/A 字型相似列比例","④ 求三角函数先转角：把原角用同弧圆周角或平行线转进已知边长的直角三角形中"],"variants":["基础考法：直径＋切线＋单一直角三角形勾股求半径","进阶变式：角平分线＋等腰半径证平行进而证切线，配合垂径定理构造矩形求线段","压轴综合：圆切线＋相似求线段乘积＋转移圆周角求 tan/sin 值"],"parentGuide":{"ask":"圆的大题里，只要看到“直径”和“切点”，不看后面问题，手里第一笔先画哪两条辅助线？","key":"必须答出：见切点连半径（得垂直 90°），见直径连圆周点（得直径所对圆周角 90°）。"},"examples":[{"title":"变式母题拆解 · 角平分线证切线与垂径矩形求边","q":"AB 是 ⊙O 的直径，AB＝10，点 C、D 在 ⊙O 上，AD 平分 ∠BAC，过 D 作 DE⊥AC 交 AC 延长线于 E。（1）求证 DE 是 ⊙O 切线；（2）若 AC＝6，求 DE 的长。","eye":"① 看到“点 D 在圆上＋角平分线＋垂线 DE”，标准“等腰半径＋角平分线 ⇒ 平行 ⇒ 垂直切线”链路。","method":"② 连 OD 证 OD∥AE 得 OD⊥DE；第（2）问过 O 作 OF⊥AC 构造矩形 OFED，用垂径定理秒算 OF＝DE。","steps":"③ 规范步骤：（1）连 OD，因 OA＝OD 且 AD 平分 ∠BAC，得 ∠ODA＝∠OAD＝∠EAD，故 OD∥AE，又 DE⊥AE，得 OD⊥DE，故 DE 为切线；（2）过 O 作 OF⊥AC 于 F，由垂径定理 AF＝3，在 Rt△AOF 中 OA＝5，得 OF＝√(5²－3²)＝4。因 ∠OFE＝∠FED＝∠ODE＝90°，四边形 OFED 为矩形，故 DE＝OF＝4。"}]},"card":{"concept":["中考倒数第 2/3 题高频大题：圆＋直径（90°）＋切线（90°）＋等腰半径（OA＝OB）⇒ 倒角证平行或相似，再结合勾股定理/三角函数求半径或线段。"],"formula":["经典三连：① 见切点连半径得 90°；② 见直径连弦得 90°；③ 设半径 r 列勾股方程或相似比例！"],"pitfall":["求 tan/sin 值时，若原角不在直角三角形里，用同弧圆周角或平行内错角把它转移到直角三角形里！"],"example":{"q":"如图，BC 是 ⊙O 直径，PA 切 ⊙O 于 A 交 BC 延长线于 P，PC＝2，PA＝4，求 ⊙O 半径 r。","a":"OA⊥PA，在 Rt△OAP 中 r²＋4²＝(r＋2)² ⇒ 4r＝12 ⇒ r＝3。","img":"./assets/knowledge/math/sp/p11-circsim.svg"}},"qids":["kp-math-sp-p11-01","kp-math-sp-p11-02","kp-math-sp-p11-03","kp-math-sp-p11-04","kp-math-sp-p11-05","kp-math-sp-p11-06","kp-math-sp-p11-07","kp-math-sp-p11-08","kp-math-sp-p11-09"],"refs":[]},{"id":"math-sp-p12","name":"隐圆模型（定点定长、定弦定角、四点共圆）","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题目通篇没有画圆，但动点到某定点的距离始终不变（定点定长，如折叠、旋转）","定线段 AB 对动点 P 的张角恒为 90°（或恒为 60°、45° 等定角，定弦定角）","四边形对角互补（尤其是两个对角都是 90°），或同侧两个相等张角（四点共圆）"],"steps":["① 识别隐圆类型，立刻锁死两个参数：圆心 O 在哪、半径 r 多大","② 特别牢记：定弦 AB 对 90° 定角时，圆心是 AB 中点，半径是 AB/2（绝非 AB）","③ 画出隐圆草图（注意判断动点走的是整圆还是部分圆弧，别漏边界）","④ 求最值直接接“一箭穿心”：定点到圆心距离 d 减半径得最小、加半径得最大"],"variants":["基础考法：单个动点满足 OA＝OB＝OP 或 ∠APB＝90°，直接识别隐圆求距离","进阶变式：正方形/等边三角形内双动点全等导角出 ∠APB＝90°（或 120°），隐圆＋一箭穿心求最值","压轴综合：定弦对非 90° 定角（如 60° 或 45°），先用圆心角是圆周角 2 倍定圆心与半径再求最值"],"parentGuide":{"ask":"题目没画圆，但说线段 AB 长度固定、动点 P 始终满足 ∠APB＝90°，点 P 在哪条线上跑？圆心和半径是谁？","key":"必须答出：点 P 在以 AB 为直径的圆上；圆心是 AB 的中点，半径是 AB 长度的一半。"},"examples":[{"title":"变式母题拆解 · 双动点全等导 90° 隐圆求最值","q":"正方形 ABCD 的边长为 4，E、F 分别是 BC、CD 边上的动点，且始终满足 BE＝CF，AE 与 BF 交于点 P，求 CP 的最小值。","eye":"① 看到双动点满足 BE＝CF 且求交点 P 到定点 C 的最短距离，先证全等倒角挖出隐藏的定角 90°。","method":"② 证 △ABE≌△BCF 得 AE⊥BF（即 ∠APB＝90°），锁定 P 在以 AB 为直径的圆上，再一箭穿心。","steps":"③ 规范步骤：由 AB＝BC、∠B＝∠C＝90°、BE＝CF 得 △ABE≌△BCF（SAS），故 ∠BAE＝∠CBF，从而 ∠APB＝90°。取 AB 中点 O，则 P 在以 O 为圆心、r＝2 为半径的圆上。在 Rt△OBC 中 OC＝√(2²＋4²)＝2√5，故 CP 最小值为 OC－r＝2√5－2。"}]},"card":{"concept":["题目不画圆，但动点轨迹其实是圆，识别三大隐圆信号：","① 定点定长：OA＝OB＝OC（或 OP＝定值）⇒ 在以 O 为圆心的圆上；","② 定弦定角：AB 定长且 ∠APB＝90° ⇒ 点 P 在以 AB 为直径的圆上；","③ 四点共圆：对角互补，或同侧张角相等（如 ∠ACB＝∠ADB＝90°）。"],"formula":["找到隐圆后，动点到定点 Q 的最值立刻用“一箭穿心”：最小值＝|OQ－r|，最大值＝OQ＋r！"],"pitfall":["∠APB＝90° 时圆心是 AB 的中点 O，半径是 AB/2，别错把 AB 当半径！"],"example":{"q":"如图，Rt△ABC 边 AB＝6 固定，动点 P 满足 ∠APB＝90°，求 P 到 AB 中点 O 的距离。","a":"P 在以 AB 为直径的圆上，OP 恒等于半径 3。","img":"./assets/knowledge/math/sp/p12-hidden.svg"}},"qids":["kp-math-sp-p12-01","kp-math-sp-p12-02","kp-math-sp-p12-03","kp-math-sp-p12-04","kp-math-sp-p12-05","kp-math-sp-p12-06","kp-math-sp-p12-07","kp-math-sp-p12-08","kp-math-sp-p12-09"],"refs":[]},{"id":"math-sp-p13","name":"动点轨迹与瓜豆原理入门","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题目中有一个“主动点 P”（在直线或圆上运动）和一个“从动点 M/Q”（由 P 派生）","从动点与主动点满足定点拉绳：长度成定比（如中点 k＝1/2）且夹角为定角（如 0°、60°、90°）","要求从动点 M 的运动路径长，或从动点 M 到某定点的最短/最长距离"],"steps":["① 分清角色：找准“定点 A”“主动点 P（及轨迹）”“从动点 M”三个角色","② 定缩放比 k 与旋转角 α：看 AM/AP＝k 和 ∠PAM＝α","③ 构造从动轨迹：把主动轨迹的圆心（或直线上的特殊点）按同样的 k、α 变换一次，即得从动圆心 O' 或从动直线","④ 用从动轨迹秒求最值或路径长：圆轨迹接一箭穿心，直线轨迹接垂线段最短"],"variants":["基础考法：中点瓜豆（M 为 AP 中点），利用三角形中位线直接得出新圆心在 OA 中点、半径减半","进阶变式：等边三角形/等腰直角三角形手拉手瓜豆，主动点走直线则从动点也走直线","压轴综合：圆上主动点＋手拉手相似缩放旋转，求从动点轨迹圆及最值"],"parentGuide":{"ask":"瓜豆原理口诀叫“种瓜得瓜，种豆得豆”，如果主动点 P 在一个半径为 2 的圆上跑，M 是定点 A 和 P 的中点，M 的轨迹是什么？半径多少？","key":"必须答出：M 的轨迹也是一个圆；新圆心是定点 A 和原圆心 O 连线的中点，新半径是原半径的一半（等于 1）。"},"examples":[{"title":"变式母题拆解 · 中点瓜豆联动一箭穿心","q":"在平面直角坐标系中，定点 A(0, 6)，点 P 在以原点 O 为圆心、半径为 2 的圆上运动，M 是线段 AP 的中点，求点 M 到定点 B(4, 0) 的距离的最小值。","eye":"① 主动点 P 在 ⊙O 上，从动点 M 是 AP 中点（定比 1/2、定角 0°），标准中点瓜豆模型。","method":"② 取 OA 中点 O'(0, 3)，由三角形中位线得 O'M＝1/2 OP＝1，锁定 M 的轨迹圆后用 O'B－r 秒求最小值。","steps":"③ 规范步骤：取 OA 中点 O'(0, 3)，连接 O'M、OP。因为 O'、M 分别为 OA、AP 中点，所以 O'M＝1/2 OP＝1，即 M 在以 O'(0, 3) 为圆心、r＝1 为半径的圆上。算得 O'B＝√(4²＋3²)＝5，故 MB 的最小值为 O'B－r＝5－1＝4。"}]},"card":{"concept":["瓜豆原理（主从联动）：定点 A，主动点 P 和从动点 M 满足“AM/AP＝定比 k，∠PAM＝定角 α”，则从动点 M 的轨迹形状与主动点 P 完全相同！","最常见特例（中点瓜豆）：M 是 AP 中点（k＝1/2，α＝0°）：若 P 在圆上运动，则 M 也在圆上运动，且新圆半径＝原半径的一半！"],"formula":["中点轨迹：P 在圆 O（半径 R）上，A 为定点，M 为 AP 中点 ⇒ M 在以 OA 中点 O' 为圆心、R/2 为半径的圆上！"],"pitfall":["确定从动圆心 O' 时，把主圆心 O 按同样的缩放/旋转规则变换一次就得到 O'！"],"example":{"q":"如图，⊙O 半径为 4，A 为定点，P 在 ⊙O 上运动，M 是 AP 中点，求 M 的轨迹圆半径。","a":"连接 OA 取中点 O'，由中位线 O'M＝1/2 OP＝2，故 M 在半径为 2 的圆上。","img":"./assets/knowledge/math/sp/p13-guadou.svg"}},"qids":["kp-math-sp-p13-01","kp-math-sp-p13-02","kp-math-sp-p13-03","kp-math-sp-p13-04","kp-math-sp-p13-05","kp-math-sp-p13-06","kp-math-sp-p13-07","kp-math-sp-p13-08","kp-math-sp-p13-09"],"refs":[]}]},{"id":"math-sp-c4","name":"几何最值压轴模型","unit":"专题·几何最值","points":[{"id":"math-sp-p14","name":"将军饮马进阶（双动点与两定两动）","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["求同侧两定点到定直线上动点的距离之和 PA＋PB 最小值（基础饮马）","角内一定点与角两边上双动点构成三角形，求周长最小值（双对称饮马）","菱形、正方形、等腰三角形、抛物线中，利用天然对称轴找定点的对称点"],"steps":["① 判对称轴：动点在哪条定直线上运动，就以哪条直线为对称轴","② 作对称点：有几个动点所在直线，就把定点对应作几次对称（注意优先用图形自带的对称点如菱形对角顶点）","③ 化折为直：连接对称点（或两对称点），交对称轴处即为取最值的动点位置","④ 用勾股定理、特殊三角形（30° 翻倍 60° 等边、45° 翻倍 90° 等腰直角）算直线段长"],"variants":["基础考法：坐标轴或图形对称轴上单动点求 PA＋PB 最小","进阶变式：菱形/正方形中对角线上动点，直接借对称顶点把折线拉直（无需额外画点）","压轴综合：两定两动四边形周长最小、造桥选址（平移＋对称）或角内双对称联动等边三角形"],"parentGuide":{"ask":"菱形对角线 BD 上有个动点 P，求 PE＋PC 最小值时，点 C 关于 BD 的对称点不用重新画，直接是谁？","key":"必须答出：直接是点 A！因为菱形的对角线本身就是对称轴，所以 PC＝PA，直接连 AE 就是最小值。"},"examples":[{"title":"变式母题拆解 · 借菱形天然对称轴秒解将军饮马","q":"菱形 ABCD 的边长为 4，∠B＝60°，E 是边 BC 的中点，P 是对角线 BD 上的动点，求 PE＋PC 的最小值。","eye":"① 动点 P 在对称轴 BD 上，定点 C 关于 BD 的天然对称点就是顶点 A，不用另作对称点。","method":"② 把 PC 转化为 PA，原式变为 PE＋PA≥AE，再利用 ∠B＝60° 的等边 △ABC 算中线高 AE。","steps":"③ 规范步骤：连接 PA、AE。由菱形对称性知点 A 与点 C 关于 BD 对称，故 PC＝PA，所以 PE＋PC＝PE＋PA≥AE。又 AB＝BC＝4、∠B＝60°，△ABC 是等边三角形，E 为 BC 中点，故 AE⊥BC，AE＝4×(√3/2)＝2√3，即最小值为 2√3。"}]},"card":{"concept":["角内一定点 P，两边上各有一动点 M、N，求 △PMN 周长最小值：分别作 P 关于两边的对称点 P₁、P₂，连 P₁P₂ 即为最小周长！"],"formula":["若 ∠AOB＝α，OP＝d，则 ∠P₁OP₂＝2α，OP₁＝OP₂＝d。","特例：α＝30° 时 ∠P₁OP₂＝60° ⇒ △OP₁P₂ 等边，最小周长＝d；α＝45° 时 ∠P₁OP₂＝90° ⇒ 最小周长＝√2 d！"],"pitfall":["求最小周长时，对称一次不够，必须对角两边各作一次对称把折线拉直成一条线段 P₁P₂！"],"example":{"q":"如图，∠AOB＝30°，OP＝6，M、N 在 OA、OB 上，求 △PMN 周长最小值。","a":"作 P 关于 OA、OB 的对称点 P₁、P₂，OP₁＝OP₂＝6，∠P₁OP₂＝60°，等边三角形得 P₁P₂＝6。","img":"./assets/knowledge/math/sp/p14-horse2.svg"}},"qids":["kp-math-sp-p14-01","kp-math-sp-p14-02","kp-math-sp-p14-03","kp-math-sp-p14-04","kp-math-sp-p14-05","kp-math-sp-p14-06","kp-math-sp-p14-07","kp-math-sp-p14-08","kp-math-sp-p14-09"],"refs":[]},{"id":"math-sp-p15","name":"垂线段最短与点圆最值（一箭穿心）","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["定点到定直线上动点的最短距离，或动态矩形中对角线长度最值","定点到定圆上动点的最大/最小距离（一箭穿心）","圆上动点 P 与定线段 AB 组成 △PAB，求三角形面积的最大值或最小值"],"steps":["① 动点在直线上 ⇒ 过定点作直线垂线，垂线段长度即最小值","② 动点在圆上求点圆距离 ⇒ 连定点与圆心并延长，d－r 为最小，d＋r 为最大（点在圆内为 r－d）","③ 动点在圆上求三角形面积最值 ⇒ 底边 AB 固定，求高即求圆心到直线 AB 的距离 d 再加减半径 r","④ 涉及矩形对角线转化时（如 EF＝AP），先把双动线段等量转化为单动点到定点的距离"],"variants":["基础考法：直接给圆心、半径和圆外一点，求最大/最小距离","进阶变式：坐标系中定底 AB 与定圆上动点 P，结合等面积法算圆心到直线距离 d 再求面积最值","压轴综合：矩形对角线相等转化＋垂线段最短，或隐圆挖出后再用一箭穿心收尾"],"parentGuide":{"ask":"圆上动点 P 和圆外固定线段 AB 组成三角形，怎么找点 P 让这个三角形面积最小？","key":"必须答出：底边 AB 固定，只要高最小；先算圆心到直线 AB 的距离 d，再减去半径 r 就是最小的高（一箭穿心）。"},"examples":[{"title":"变式母题拆解 · 坐标系定圆与定底面积最值","q":"在平面直角坐标系中，点 A(0, 3)、B(4, 0)，点 P 是以原点 O 为圆心、半径为 1 的圆上的动点，求 △PAB 面积的最小值。","eye":"① △PAB 底边 AB 长度固定为 5，面积最小等价于动点 P 到直线 AB 的距离最小。","method":"② 用等面积法算原点 O 到直线 AB 的距离 d＝OA·OB/AB，再由一箭穿心减半径 r 得最小高。","steps":"③ 规范步骤：在 Rt△AOB 中，AB＝√(3²＋4²)＝5，原点 O 到 AB 的距离 d＝(3×4)/5＝12/5。因为 ⊙O 半径 r＝1，所以点 P 到 AB 的最小距离 h＝d－r＝12/5－1＝7/5，故 S△PAB 最小值＝1/2×5×(7/5)＝7/2。"}]},"card":{"concept":["动点在直线上，定点到直线的最短距离是垂线段长度。","动点在圆上，定点 P 到圆上动点 Q 的距离（一箭穿心）：连 PO 交圆于近点 M、远点 N，则 PQ 最小＝|PO－r|，PQ 最大＝PO＋r。"],"formula":["圆心 O 到直线 l 距离为 d，圆上动点到直线 l 距离：最小 d－r，最大 d＋r（相离时）。"],"pitfall":["遇到“求双线段中垂线段最值”（如矩形里过动点作垂线），先看动点轨迹或转化为定点到定直线的距离！"],"example":{"q":"如图，⊙O 半径 3，OP＝8，求 P 到圆上点的最小和最大距离。","a":"最小 8－3＝5，最大 8＋3＝11。","img":"./assets/knowledge/math/sp/p15-arrow.svg"}},"qids":["kp-math-sp-p15-01","kp-math-sp-p15-02","kp-math-sp-p15-03","kp-math-sp-p15-04","kp-math-sp-p15-05","kp-math-sp-p15-06","kp-math-sp-p15-07","kp-math-sp-p15-08","kp-math-sp-p15-09"],"refs":[]},{"id":"math-sp-p16","name":"胡不归模型（PA＋k·PB）","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["动点 P 在一条定直线上运动，要求 PA＋k·PB（且系数 k≠1）的最小值","系数 k 是特殊角的正弦值：1/2（30°）、√2/2（45°）、√3/2（60°）","系数 k＞1（如 2PA＋PB 或 √2 PA＋PB），可提取系数化为 0＜k＜1 形式"],"steps":["① 确认动点轨迹是直线（圆上动点是阿氏圆，直线上动点才是胡不归）","② 若系数 k＞1，先提公因式使带系数项变为 0＜k＜1（如 2(PA＋1/2 PB)）","③ 构角转化：以 B 为顶点，在动点直线 l 的另一侧作射线 BD 使 sin α＝k，过 P 作 PH⊥BD，把 k·PB 变成垂线段 PH","④ 拉直收尾：原式化为 PA＋PH，过点 A 作射线 BD 的垂线段 AH 即为最小值（注意验证交点落在线段内）"],"variants":["基础考法：直接给出 k＝1/2 或 √2/2，动点在直角边或坐标轴上","进阶变式：系数 k＞1（如 √2 PA＋PB）或物理情境“路程/速度＝时间最小”，需先提取公因式化出 sin α","压轴综合：在抛物线对称轴上找动点 P 满足 PA＋(√2/2)PB 最小，与二次函数解析式结合"],"parentGuide":{"ask":"看到求 PA＋1/2 PB 的最小值，动点 P 在直线上，怎么把那个烦人的“1/2”消掉？","key":"必须答出：看到 1/2 想到 sin 30°，在直线另一侧构造一个 30° 角并作垂线 PH，把 1/2 PB 变成垂线段 PH，再过 A 向新射线作垂线即可。"},"examples":[{"title":"变式母题拆解 · 构造 30° 角秒杀 PA＋1/2 PB","q":"在 Rt△ABC 中，∠C＝90°，∠B＝30°，AC＝2，点 P 是直角边 BC 上的动点，求 PA＋1/2 PB 的最小值。","eye":"① 动点 P 在线段 BC 上，系数 1/2＝sin 30°，与已知 ∠B＝30° 拼起来正好是 60° 特殊角！","method":"② 在 BC 下方作 ∠CBD＝30°，作 PH⊥BD 则 PH＝1/2 PB，过 A 作 AH⊥BD 于 H，在 Rt△ABH 中秒算 AH。","steps":"③ 规范步骤：以 B 为顶点在 BC 下方作射线 BD 使 ∠CBD＝30°，过 P 作 PH⊥BD 于 H，则 PH＝PB·sin 30°＝1/2 PB，故 PA＋1/2 PB＝PA＋PH≥AH（AH⊥BD）。在 Rt△ABC 中 AB＝2AC＝4，又 ∠ABD＝30°＋30°＝60°，故在 Rt△ABH 中 AH＝AB·sin 60°＝4×(√3/2)＝2√3，即最小值为 2√3。"}]},"card":{"concept":["动点 P 在定直线 l 上，求 PA＋k·PB（0＜k＜1）的最小值：不能直接连线段，先把带系数的 k·PB 转化成一条垂线段 PH！","转化秘诀：以 B 为顶点，在直线 l 另一侧构造角 α 使 sin α＝k，过 P 作新射线的垂线 PH，则 PH＝PB·sin α＝k·PB，原式变成 PA＋PH，过 A 作该射线的垂线段即最小！"],"formula":["常见系数：k＝1/2 构造 30° 角；k＝√2/2 构造 45° 角；k＝√3/2 构造 60° 角！"],"pitfall":["如果系数 k＞1（如求 2PA＋PB），先提取 2 变成 2(PA＋1/2 PB)，再对括号内用胡不归！"],"example":{"q":"如图，P 在直线 l 上，求 PA＋1/2 PB 的最小值怎么转化？","a":"过 B 在 l 下方作射线使夹角为 30°，作 PH 垂直该射线，PH＝1/2 PB，故最小值为点 A 到该射线的垂线段长。","img":"./assets/knowledge/math/sp/p16-hbg.svg"}},"qids":["kp-math-sp-p16-01","kp-math-sp-p16-02","kp-math-sp-p16-03","kp-math-sp-p16-04","kp-math-sp-p16-05","kp-math-sp-p16-06","kp-math-sp-p16-07","kp-math-sp-p16-08","kp-math-sp-p16-09"],"refs":[]},{"id":"math-sp-p17","name":"折叠与动点最值综合","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["矩形或三角形中，折痕经过一个固定顶点（如 A），另一个端点 E 在边上滑动","要求折叠对应点 B' 到另一固定顶点（如 C、D）或边上某定点（如中点 M）的最小/最大距离","折叠后对应点落在某条边上或对角线上，要求列方程求折痕或边长"],"steps":["① 找不变量：先圈出折痕上的不动定点 A 和被折过去的线段 AB，得出 AB'＝AB（定长）","② 画隐圆弧：锁定 B' 在以 A 为圆心、AB 为半径的圆弧上运动","③ 算圆心距：用勾股定理算出圆心 A 到目标定点 M（或 C）的固定距离 AM","④ 一箭穿心并验边界：最小值为 |AM－AB|，务必检查此时折点 E 是否落在线段范围内"],"variants":["基础考法：固定折法，对应点落到对边上，在直角三角形中设未知数列勾股方程","进阶变式：折痕绕定点旋转，利用“折叠＋定点＝隐圆”求对应点到顶点或中点的最短距离","压轴综合：动点范围受限时圆弧两端不能取到一箭穿心点，需在临界端点处求最值"],"parentGuide":{"ask":"矩形纸片里，折痕一直过定点 A，另一头在 BC 边上乱动，折过去的 B' 点其实在什么图形上跑？","key":"必须答出：在以 A 为圆心、AB 长为半径的圆（圆弧）上跑，因为不管怎么折，AB' 永远等于 AB。"},"examples":[{"title":"变式母题拆解 · 折叠隐圆到边上中点的最短距离","q":"在矩形 ABCD 中，AB＝10，BC＝12，M 是边 CD 的中点，E 是边 BC 上的动点，将 △ABE 沿 AE 折叠得到 △AB'E，求 B'M 的最小值。","eye":"① 折痕 AE 恒过定点 A，故 AB'＝AB＝10 是定长，点 B' 在隐圆上；目标点是 CD 中点 M。","method":"② 先在 Rt△ADM 中算出圆心 A 到目标点 M 的距离 AM＝13，再用一箭穿心 AM－AB' 秒算。","steps":"③ 规范步骤：由折叠性质得 AB'＝AB＝10，故 B' 在以 A 为圆心、10 为半径的圆弧上。在矩形 ABCD 中 AD＝BC＝12，M 为 CD 中点，故 DM＝5。在 Rt△ADM 中 AM＝√(12²＋5²)＝13。当 A、B'、M 三点共线（且 B' 在 AM 上）时，B'M 最小为 AM－AB'＝13－10＝3（此时折点 E 落在 BC 边内，可取到）。"}]},"card":{"concept":["“折叠＋定点”＝隐圆！把定点 C 沿过另一不动点（如 A）的折痕折叠，对应点 C' 满足 AC'＝AC（定长），故 C' 在以 A 为圆心、AC 为半径的圆上！","再结合“一箭穿心”就能秒求 C' 到另一顶点的最短/最长距离！"],"formula":["矩形 ABCD 中把点 B 沿过点 A 的折痕折到 B'：AB'＝AB（定长），故点 B' 在以 A 为圆心、AB 为半径的圆上，对角线 AC 上取到最小值 B'C＝AC－AB。"],"pitfall":["找准“哪个点不动、哪条线段折叠后长度不变”，立刻锁定隐圆圆心和半径！"],"example":{"q":"矩形 ABCD 中 AB＝6，BC＝8，E 在 BC 上，把 △ABE 沿 AE 折叠得 △AB'E，求 B'C 最小值。","a":"AB'＝AB＝6，AC＝10，B' 在以 A 为圆心、6 为半径的圆上，B'C 最小＝AC－AB'＝10－6＝4。","img":"./assets/knowledge/math/sp/p17-fold.svg"}},"qids":["kp-math-sp-p17-01","kp-math-sp-p17-02","kp-math-sp-p17-03","kp-math-sp-p17-04","kp-math-sp-p17-05","kp-math-sp-p17-06","kp-math-sp-p17-07","kp-math-sp-p17-08","kp-math-sp-p17-09"],"refs":[]}]},{"id":"math-sp-c5","name":"二次函数压轴综合","unit":"专题·二次函数压轴","points":[{"id":"math-sp-p18","name":"二次函数铅垂高面积最值","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["抛物线上有一动点 P，与两个定点 B、C 围成斜放的三角形 △PBC，求面积最大值","要求在抛物线上找动点 P，使 △PBC 面积等于某个定值或与已知三角形面积成比例","四边形 ABPC 由一个固定三角形加一个动态斜三角形组成，求四边形最大面积"],"steps":["① 写出两定点 B、C 所在直线解析式 y＝kx＋b，确定动点 P 横坐标 t 的合法区间","② 过 P 作 y 轴平行线交直线 BC 于 Q，设 P(t, yP)、Q(t, yQ)","③ 算铅垂高 PQ＝上减下（务必注意谁在上方，减式整体加括号），确定水平宽＝|xB－xC|","④ 套公式 S＝1/2 × 铅垂高 × 水平宽，配方求最值（快捷验算：最值必在 t＝(xB＋xC)/2 处取到）"],"variants":["基础考法：开口向下抛物线，P 在第一象限直线 BC 上方，直接抛物线减直线","进阶变式：开口向上抛物线，P 在第四象限直线 BC 下方，必须改为“直线减抛物线”防算成负数","压轴综合：求动态四边形 ABPC 最大面积，拆成“固定 S△ABC ＋ 动态铅垂高 S△PBC”"],"parentGuide":{"ask":"二次函数里求斜三角形 △PBC 的最大面积，不用复杂割补，直接记住的“铅垂高公式”是什么？P 点横坐标在什么位置时面积最大？","key":"必须答出：面积＝1/2 × 铅垂高 × 水平宽；而且当动点 P 的横坐标恰好等于 B、C 两点横坐标的中点 (xB＋xC)/2 时，面积一定最大。"},"examples":[{"title":"变式母题拆解 · 开口向上抛物线（直线减抛物线防负号错）","q":"抛物线 y＝x²－2x－3 与 x 轴交于 A(－1, 0)、B(3, 0)，与 y 轴交于 C(0, －3)，点 P 是第四象限抛物线上的动点，求 △PBC 面积的最大值及此时点 P 坐标。","eye":"① 题眼是抛物线开口向上、点 P 在直线 BC 下方，算铅垂高必须用“直线 yQ 减抛物线 yP”。","method":"② 先求直线 BC：y＝x－3，设 P(t, t²－2t－3)（0＜t＜3），算 PQ＝yQ－yP 再套铅垂高公式。","steps":"③ 规范步骤：由 B(3, 0)、C(0, －3) 得直线 BC：y＝x－3。设 P(t, t²－2t－3)（0＜t＜3），过 P 作 PQ∥y 轴交 BC 于 Q(t, t－3)，则 PQ＝(t－3)－(t²－2t－3)＝－t²＋3t。水平宽 OB＝3，故 S△PBC＝1/2×3×(－t²＋3t)＝－3/2(t－3/2)²＋27/8。当 t＝3/2 时最大面积为 27/8，此时 P(3/2, －15/4)。"}]},"card":{"concept":["斜三角形 △PBC 面积最值通法：过动点 P(t, yP) 作 y 轴平行线交直线 BC 于 Q(t, yQ)，则 S△PBC＝1/2 × 铅垂高 |yP－yQ| × 水平宽 |xB－xC|。"],"formula":["S△PBC 最大 ⇔ 铅垂高 PQ 最大 ⇔ t 取 B、C 两点横坐标的中点 (xB＋xC)/2（对称轴定理，秒杀！）。"],"pitfall":["动点 P 的横坐标必须在 B、C 两点横坐标之间，且看清是抛物线减直线还是直线减抛物线！"],"example":{"q":"如图，抛物线 y＝－x²＋2x＋3 交 y 轴于 C(0, 3)、交 x 轴于 B(3, 0)，P 在第一象限抛物线上，求 △PBC 最大面积。","a":"直线 BC：y＝－x＋3；PQ＝－t²＋3t，t＝1.5 时 PQ 最大 9/4，水平宽 3，最大面积＝1/2×(9/4)×3＝27/8。","img":"./assets/knowledge/math/sp/p18-vheight.svg"}},"qids":["kp-math-sp-p18-01","kp-math-sp-p18-02","kp-math-sp-p18-03","kp-math-sp-p18-04","kp-math-sp-p18-05","kp-math-sp-p18-06","kp-math-sp-p18-07","kp-math-sp-p18-08","kp-math-sp-p18-09"],"refs":[]},{"id":"math-sp-p19","name":"二次函数中的等腰与直角三角形存在性","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["二次函数压轴第（3）问：在坐标轴、对称轴或抛物线上找点 P，使 △PAB 为等腰三角形","在直线或抛物线上找点 P，使 △PAB 为直角三角形（或等腰直角三角形）","题目只说“以 A、B、P 为顶点的三角形”，没有指定哪条是腰或哪个角是直角"],"steps":["① 先画草图定框架：等腰用“两圆一垂线”（AB＝AP、BA＝BP、PA＝PB）；直角用“两垂一圆”（∠A＝90°、∠B＝90°、∠P＝90°）","② 设出动点 P 单参数坐标（如 x 轴上 (t, 0)、对称轴上 (h, m)），写出 AB²、AP²、BP² 三个平方表达式","③ 分别列三类方程求解：等腰两两相等；直角分别以三条边为斜边列勾股方程","④ 终极排雷：把求出的解全部代回检验，踢掉与 A、B 重合或三点共线的假解"],"variants":["基础考法：在 x 轴或对称轴上找点 P 构成等腰或直角三角形，方程均为一元一次或简单二次方程","进阶变式：直角三角形中 ∠P＝90° 时，利用 K 字形（一线三直角）相似或斜率乘积为 －1 降次秒解","压轴综合：动点 P 在抛物线上运动构成直角三角形，涉及一元二次方程求根并检验共线"],"parentGuide":{"ask":"考等腰三角形存在性和直角三角形存在性，防止漏解的两句 5 字口诀分别是什么？算完还要做什么？","key":"必须答出：等腰用“两圆一垂线”（分 3 类），直角用“两垂一圆”（分 3 类）；算完必须剔除“三点共线或重合”的假解。"},"examples":[{"title":"变式母题拆解 · 两圆一垂线不重不漏（含重合点剔除）","q":"已知定点 A(0, 3)、B(4, 0)，在 x 轴上是否存在点 P，使 △PAB 为等腰三角形？若存在，求出所有点 P 的坐标。","eye":"① 设 P(t, 0)，易算 AB＝5，按“两圆一垂线”分三类列方程，特别注意 PA＝AB 时有一解恰好与 B 重合必须剔除！","method":"② 写出 AB²＝25、PA²＝t²＋9、PB²＝(t－4)²，分别令 PA²＝25、PB²＝25、PA²＝PB² 求解。","steps":"③ 规范步骤：设 P(t, 0)（t≠4）。① 当 PA＝AB＝5 时，t²＋9＝25 得 t＝±4，舍去 t＝4（与 B 重合），得 P₁(－4, 0)；② 当 PB＝AB＝5 时，|t－4|＝5 得 t＝9 或 －1，得 P₂(9, 0)、P₃(－1, 0)；③ 当 PA＝PB 时，t²＋9＝(t－4)² 得 8t＝7，t＝7/8，得 P₄(7/8, 0)。综上共 4 个点。"}]},"card":{"concept":["等腰三角形存在性（两圆一线法）：给定两定点 A、B，分三类讨论——以 A 为顶点（AB＝AP）、以 B 为顶点（BA＝BP）、以 P 为顶点（PA＝PB，即 AB 垂直平分线）！","直角三角形存在性（两线一圆法）：分三类——∠A＝90°（过 A 垂线）、∠B＝90°（过 B 垂线）、∠P＝90°（以 AB 为直径的圆）！"],"formula":["代数法：写出 AB²、AP²、BP²，等腰列两两相等，直角列勾股定理三类方程！"],"pitfall":["千万别漏分三类讨论，且求出点 P 后必须剔除“A、B、P 三点共线”的假解！"],"example":{"q":"已知 A(0, 0)、B(4, 0)，在直线 y＝2 上找点 P 使 △PAB 是直角三角形，有几个点？","a":"∠A＝90° 得 (0, 2)；∠B＝90° 得 (4, 2)；以 AB 为直径的圆圆心 (2, 0) 半径 2，与 y＝2 相切于 (2, 2)，共 3 个点！","img":"./assets/knowledge/math/sp/p19-exist.svg"}},"qids":["kp-math-sp-p19-01","kp-math-sp-p19-02","kp-math-sp-p19-03","kp-math-sp-p19-04","kp-math-sp-p19-05","kp-math-sp-p19-06","kp-math-sp-p19-07","kp-math-sp-p19-08","kp-math-sp-p19-09"],"refs":[]},{"id":"math-sp-p20","name":"二次函数中的平行四边形存在性","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["坐标系中已知 3 个定点求第 4 点，使它们构成平行四边形","已知 2 个定点 A、B，以及 2 个动点（分别在坐标轴、对称轴或抛物线上）构成平行四边形","审题区分“四边形 ABCD 是平行四边形”（顺序固定 1 解）与“以 A、B、C、D 为顶点的平行四边形”（无顺序 3 类）"],"steps":["① 死记核心坐标公式：平行四边形对角线互相平分 ⇔ 相对两顶点横坐标之和相等、纵坐标之和相等","② 确定分类数：顺序固定只列 1 组；无顺序限制则按 AB、AC、AD 分别为对角线分 3 类","③ 设出动点坐标代入中点坐标相等方程组（双动点刚好 2 个未知数 2 个方程，直接秒解）","④ 检验四点是否共线，若符合菱形/矩形附加条件再补邻边相等或对角线相等"],"variants":["基础考法：三定一动求第四点坐标，直接套 A＋B－C、A＋C－B、B＋C－A 三解","进阶变式：两定两动（如一动点在 x 轴、一动点在 y 轴或对称轴），按三类对角线各解一组一次方程","压轴综合：一动点在对称轴、一动点在抛物线上，代入中点公式先定横坐标再反代抛物线求纵坐标"],"parentGuide":{"ask":"在坐标系里做平行四边形存在性，最稳最快的代数密码是什么？如果题目没固定字母顺序，要分几类？","key":"必须答出：相对两个顶点的横坐标之和相等、纵坐标之和相等（x₁＋x₃＝x₂＋x₄，y₁＋y₃＝y₂＋y₄）；没固定顺序必须按 3 条不同对角线分 3 类。"},"examples":[{"title":"变式母题拆解 · 两定两动平行四边形三类秒解","q":"在平面直角坐标系中，已知 A(1, 3)、B(4, 1)，点 C 在 x 轴上，点 D 在 y 轴上，若以 A、B、C、D 为顶点的四边形是平行四边形，求所有符合条件的 C、D 坐标。","eye":"① 设 C(c, 0)、D(0, d)，两动点各自带一个 0 坐标，用“相对顶点坐标和相等”根本不用画复杂辅助线。","method":"② 按 AB、AC、AD 分别为对角线分三类列方程组，口算即可出全解。","steps":"③ 规范步骤：设 C(c, 0)、D(0, d)。① AB 为对角线：1＋4＝c＋0，3＋1＝0＋d ⇒ C(5, 0)、D(0, 4)；② AC 为对角线：1＋c＝4＋0，3＋0＝1＋d ⇒ C(3, 0)、D(0, 2)；③ AD 为对角线：1＋0＝4＋c，3＋d＝1＋0 ⇒ C(－3, 0)、D(0, －2)。经检验均不共线，共 3 组解。"}]},"card":{"concept":["平行四边形对角线互相平分 ⇔ 两条对角线的中点重合 ⇔ 相对两顶点坐标之和相等！"],"formula":["若 A、C 为相对顶点，B、D 为相对顶点：xA＋xC＝xB＋xD 且 yA＋yC＝yB＋yD！","已知三定点 A、B、C 求第四点 D（无字母顺序限制）：三类对角线（AB、AC、BC），直接套 D＝A＋B－C、A＋C－B、B＋C－A！"],"pitfall":["审清题目：写“四边形 ABCD 是平行四边形”顺序固定只有 1 解；写“以 A、B、C、D 为顶点的平行四边形”无顺序限制，有 3 解！"],"example":{"q":"如图，已知 A(0, 2)、B(2, 0)、C(3, 2)，求以 A、B、C、D 为顶点的平行四边形所有 D 的坐标。","a":"三解：A＋B－C＝(－1, 0)；A＋C－B＝(1, 4)；B＋C－A＝(5, 0)。","img":"./assets/knowledge/math/sp/p20-paraex.svg"}},"qids":["kp-math-sp-p20-01","kp-math-sp-p20-02","kp-math-sp-p20-03","kp-math-sp-p20-04","kp-math-sp-p20-05","kp-math-sp-p20-06","kp-math-sp-p20-07","kp-math-sp-p20-08","kp-math-sp-p20-09"],"refs":[]},{"id":"math-sp-p21","name":"抛物线与线段交点含参临界问题","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["含参抛物线（参数控制上下平移、左右平移或开口大小 a）与定线段 AB 有 1 个或 2 个公共点","含参二次函数图象与水平直线 y＝m 或折线有特定个数的交点，求参数范围","题目中出现“恰有 1 个公共点”“至少有 1 个公共点”“只有 2 个交点”等关键词"],"steps":["① 固定不动元素（线段 AB 及其端点），看清参数让抛物线怎么动（平移还是缩放开口）","② 抓两大临界状态：抛物线经过端点 A、经过端点 B，以及顶点落在线段上或与线段相切（Δ＝0）","③ 分别把临界条件代入求出几个关键参数值，按大小排在数轴上","④ 逐个区间和临界端点带回去画草图验证：相切必验切点是否在线段内，端点必验能不能取等号"],"variants":["基础考法：抛物线上下平移 y＝a(x－h)²＋m 与水平线段相交，只需算顶点和最远端点两个临界","进阶变式：开口系数 a 变化 y＝a(x－h)²＋k 与水平线段“恰有 1 个公共点”，两端点一高一低卡范围","压轴综合：抛物线与斜线段相切（联立算 Δ＝0）且需验证切点横坐标落在线段两端点之间"],"parentGuide":{"ask":"做抛物线和线段交点求参数范围时，光算出几个临界数字还不够，最后哪两个细节最容易丢分？","key":"必须答出：① 必须逐个检验临界点能不能取等号（≤ 还是 ＜）；② 如果算了相切（Δ＝0），必须检查切点是不是真的落在线段里面而不是延长线上。"},"examples":[{"title":"变式母题拆解 · 开口缩放抛物线与线段恰有 1 交点","q":"已知线段 AB 的端点为 A(1, 2)、B(4, 2)，抛物线 y＝a(x－2)²＋1（a＞0）与线段 AB 恰有 1 个公共点，求实数 a 的取值范围。","eye":"① 顶点 (2, 1) 固定在水平线段 y＝2 下方，a＞0 控制开口宽窄；恰有 1 交点意味着一端穿过线段、另一端还没够到线段！","method":"② 因 x＝4 离对称轴 x＝2 更远，y(4)＞y(1)，故恰有 1 交点等价于 y(4)≥2 且 y(1)＜2。","steps":"③ 规范步骤：当 x＝1 时 y＝a＋1；当 x＝4 时 y＝4a＋1。因为顶点 (2, 1) 在线段 AB 下方且 a＞0，抛物线与线段 AB 恰有 1 个公共点等价于点 B 在抛物线上或下方、点 A 在抛物线上方（若 y(1)＝2 则在 x＝1 和 x＝3 处有 2 个交点），即 4a＋1≥2 且 a＋1＜2，解得 1/4≤a＜1。"}]},"card":{"concept":["含参抛物线与给定线段 AB 恰有 1 个或 2 个交点，关键是画出动态草图，找到两个临界状态：","① 抛物线刚好经过端点 A 或 B；② 抛物线与线段 AB 刚好相切（Δ＝0）或顶点落在 AB 上。"],"formula":["步骤：代端点坐标算临界参数 → 算相切/顶点临界参数 → 结合开口与平移方向检验端点等号！"],"pitfall":["线段有端点限制！相切时必须验证切点的横坐标是不是落在线段 AB 之间！"],"example":{"q":"如图，抛物线 y＝(x－1)²＋m 与水平线段 AB（A(0, 2)、B(3, 2)）有公共点，求 m 的范围。","a":"顶点 (1, m) 在线段下方最高触及 m＝2；经过最远端点 B(3, 2) 时 4＋m＝2 ⇒ m＝－2，故 －2≤m≤2。","img":"./assets/knowledge/math/sp/p21-segint.svg"}},"qids":["kp-math-sp-p21-01","kp-math-sp-p21-02","kp-math-sp-p21-03","kp-math-sp-p21-04","kp-math-sp-p21-05","kp-math-sp-p21-06","kp-math-sp-p21-07","kp-math-sp-p21-08","kp-math-sp-p21-09"],"refs":[]}]},{"id":"math-sp-c6","name":"代数压轴与中考新定义","unit":"专题·代数与新定义","points":[{"id":"math-sp-p22","name":"整体代入与配方法求最值","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["已知一个含无理根的二次方程（如 x²－2x－5＝0），要求高次多项式（含 x³、x⁴）的值","题目出现 x＋1/x＝k 或 a＋b、ab 的值，要求高次对称式（x²＋1/x²、a³＋b³ 等）","要求单变量或双变量二次代数式的最大值或最小值（含交叉项 xy）"],"steps":["① 降次整体代入：把二次条件改写为 x²＝px＋q，把高次项拆成 x·x² 逐次降到一次再代入","② 对称式配凑：利用 a²＋b²＝(a＋b)²－2ab、x²＋1/x²＝(x＋1/x)²－2 整体代换","③ 单变量配方：提二次项系数 a（注意负号变号），加减一次项系数一半的平方得 a(x－h)²＋k","④ 双变量配方：拆开平方项先消交叉项 xy，配成 (x±my)²＋(y±n)²＋c，由非负性定最值与取等条件"],"variants":["基础考法：直接把 ax²＋bx 整体打包代入求值，或单变量二次式配方求最值","进阶变式：负系数配方（如 －2x²＋8x－5）与倒数和平方公式（x＋1/x）综合","压轴综合：双变量含交叉项拆项配方，或利用配方非负性判断三角形形状/证明代数式恒为正"],"parentGuide":{"ask":"给 －2x²＋8x－5 配方时，先把 －2 提出来，括号里应该写什么？常数项容易错在哪？","key":"必须答出：提 －2 后括号里是 (x²－4x)，不是 (x²＋4x)；括号里补 ＋4 实际相当于整体减了 8，外面要加回 8，得到 －2(x－2)²＋3。"},"examples":[{"title":"变式母题拆解 · 负系数配方最值与倒数和整体代入","q":"（1）用配方法求代数式 －2x²＋8x－5 的最大值；（2）已知 x＋1/x＝3，求 x²＋1/x² 的值。","eye":"① 第（1）问考负系数提公因式时的符号切换；第（2）问考完全平方交叉项 2·x·(1/x)＝2 自动消元。","method":"② 第（1）问提 －2 配方为 －2(x－2)²＋3；第（2）问直接用 x²＋1/x²＝(x＋1/x)²－2 整体代入。","steps":"③ 规范步骤：（1）原式＝－2(x²－4x)－5＝－2(x²－4x＋4－4)－5＝－2(x－2)²＋8－5＝－2(x－2)²＋3，因 －2(x－2)²≤0，故 x＝2 时最大值为 3；（2）x²＋1/x²＝(x＋1/x)²－2＝3²－2＝7。"}]},"card":{"concept":["降次整体代入：若已知 x²－3x＝1，不要硬解无理根，反复把 x² 替换成 3x＋1 降次！","配方法求最值：把二次式配成 a(x－h)²＋k（或双变量配成 (x－a)²＋(y－b)²＋c），利用平方非负性秒求最值！"],"formula":["x²＋y²－2x＋4y＋8＝(x－1)²＋(y＋2)²＋3≥3（最小值为 3）。"],"pitfall":["配方提系数时注意符号：－2x²＋4x＋1＝－2(x－1)²＋3，常数项别算反！"],"example":{"q":"已知 x²－3x－1＝0，求 x³－4x²＋2x＋5 的值。","a":"x²＝3x＋1，x³－4x²＋2x＋5＝x(3x＋1)－4x²＋2x＋5＝－x²＋3x＋5＝－(x²－3x)＋5＝－1＋5＝4。","img":"./assets/knowledge/math/sp/p22-complete.svg"}},"qids":["kp-math-sp-p22-01","kp-math-sp-p22-02","kp-math-sp-p22-03","kp-math-sp-p22-04","kp-math-sp-p22-05","kp-math-sp-p22-06","kp-math-sp-p22-07","kp-math-sp-p22-08","kp-math-sp-p22-09"],"refs":[]},{"id":"math-sp-p23","name":"含参方程与不等式（主元法与分类讨论）","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["方程或分式方程含参数 m，条件说“解为正数”“解为整数”或“方程无解”","不等式组含参数 a，条件说“有解”“无解”或“恰有 k 个整数解”","等式或不等式对任意 x 恒成立，需要把 x 当主元让系数归零"],"steps":["① 先当普通题解出未知数（用含参数的式子表示 x 或不等式解集）","② 含参分式方程务必单列一条红线：把增根值代进 x 的表达式求出参数禁值","③ 不等式组整数解问题一律画数轴：先框出那 k 个具体整数，再把参数卡在两个相邻整数之间","④ 终极检验等号：把区间左右两个边界整数分别代入参数，看原不等式组整数解个数是否正好达标"],"variants":["基础考法：含参一元一次方程整数解，利用整除列全正负因数","进阶变式：含参不等式组“恰有 k 个整数解”，重点考查左右边界谁取等号、谁不取等号","压轴综合：分式方程解的符号＋不等式组整数解双联动，必须剔除分式增根对应的参数值"],"parentGuide":{"ask":"不等式组 a≤x＜2 恰有 3 个整数解，算出 a 在 －2 和 －1 之间后，怎么一眼确定哪边带等号？","key":"必须答出：把 －2 和 －1 分别直接代回 a≤x＜2 试一试！a＝－1 有 －1、0、1（3 个，行，带等号）；a＝－2 有 －2、－1、0、1（4 个，不行，不带等号），所以 －2＜a≤－1。"},"examples":[{"title":"变式母题拆解 · 不等式组恰有 3 个整数解的端点验等法","q":"若关于 x 的不等式组 { x－a≥0；3－2x＞－1 } 恰有 3 个整数解，求实数 a 的取值范围。","eye":"① 题眼是“恰有 3 个整数解”，解出 x＜2 后立刻锁死这 3 个整数只能是 1、0、－1，难点在 －2 与 －1 的等号取舍。","method":"② 画数轴确定 －2 与 －1 为边界，再用“边界回代试真法”分别试 a＝－1 和 a＝－2。","steps":"③ 规范步骤：解不等式①得 x≥a，解不等式②得 －2x＞－4，x＜2，故解集为 a≤x＜2。因恰有 3 个整数解，必为 1、0、－1，故 a 在 －2 与 －1 之间。检验：a＝－1 时 －1≤x＜2 恰有 3 个整数解（可取）；a＝－2 时 －2≤x＜2 有 4 个整数解（不可取）。综上，－2＜a≤－1。"}]},"card":{"concept":["“解为整数”问题：先把未知数 x 用参数 m 表示成分式（如 x＝6/(m＋1)），再根据整除性列出分母的所有整数因数（别漏负因数！）","“恒成立”问题：把主元换成给定范围的变量，让系数为 0 或取最值端点满足不等式。"],"formula":["方程与不等式综合：先解方程组用参数表示 x、y，再代入不等式求参数范围！"],"pitfall":["分式方程结合不等式求参数范围时，最后一步千万别忘剔除“产生增根的参数值”！"],"example":{"q":"关于 x 的方程 (m－1)x＝6 的解是正整数，求整数 m 的个数。","a":"m－1 是 6 的正因数 1、2、3、6，得 m＝2、3、4、7，共 4 个。"}},"qids":["kp-math-sp-p23-01","kp-math-sp-p23-02","kp-math-sp-p23-03","kp-math-sp-p23-04","kp-math-sp-p23-05","kp-math-sp-p23-06","kp-math-sp-p23-07","kp-math-sp-p23-08","kp-math-sp-p23-09"],"refs":[]},{"id":"math-sp-p24","name":"中考新定义与规律压轴题","tag":"★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["压轴最后两题出现陌生造词，如“关联点”“智慧点”“k-覆盖圆”“新运算 a⊕b”","图形或数字序列按某种规则迭代，求第 n 项通项公式或第 2026 项的值","新定义条件把点、线段、直线与圆的距离关系包装成“存在性”或“区域包含”问题"],"steps":["① 去魅翻译：把陌生名词原封不动替换成初中学过的数学条件（距离 d≤r、相切、垂直、方程）","② 从特例入手：第（1）问的简单数字验证就是出题人送你的“说明书”，照着画图找感觉","③ 几何新定义画区域：用虚线/实线画出符合定义的圆域、环形域或扫过的带状区域，标清临界相切和端点","④ 规律探究列前 4～5 项：查差值、查平方（n²±k）、查符号交替 (－1)ⁿ 或找周期余数"],"variants":["基础考法：代数新运算或数字/图形周期规律探究，直接套定义算前几项找规律","进阶变式：点圆“关联域”新定义，把存在性问题翻译成圆心到直线的距离 d≤r 求解参数范围","压轴综合：动圆扫过线段形成的“跑道形区域”与动态直线交点临界问题（北京/名校中考真压轴）"],"parentGuide":{"ask":"考试最后遇到完全没见过的“新定义名词”，吓得不敢下手怎么办？第一步干什么？","key":"必须答出：别怕名词，它不是超纲知识；第一步把新定义逐字翻译成熟悉的距离、圆、方程或不等式，先用第（1）问的小例子试懂规则。"},"examples":[{"title":"变式母题拆解 · “2-关联域”几何新定义翻译破局","q":"平面直角坐标系中，到定点 O(0, 0) 距离不超过 2 的所有点构成的区域称为 O 的“2-关联域”。若直线 y＝x＋b 上存在点落在 O 的“2-关联域”内，求实数 b 的取值范围。","eye":"① 撕掉“2-关联域”的外衣，它就是以原点 O 为圆心、半径为 2 的圆及其内部！","method":"② “直线上存在点在圆及内部”等价于“直线与圆相交或相切”，即原点 O 到直线 y＝x＋b 的距离 d≤2。","steps":"③ 规范步骤：由题意，O 的“2-关联域”为以 O(0, 0) 为圆心、半径 r＝2 的圆及内部。直线 y＝x＋b 交坐标轴于 (－b, 0) 和 (0, b)，构成等腰直角三角形，斜边为 √2|b|，故原点 O 到直线距离 d＝|b|·|b|/(√2|b|)＝|b|/√2。令 d≤2，得 |b|/√2≤2，即 |b|≤2√2，解得 －2√2≤b≤2√2。"}]},"card":{"concept":["新定义题不要被陌生名词吓住：核心就是“照着定义翻译成熟悉的方程、不等式或几何关系”！","规律探究题：先算前 4～5 项，看是不是等差、等比、平方数（n²±k）或周期循环（除以周期看余数）。"],"formula":["裂项相消：1/[n(n＋1)]＝1/n－1/(n＋1)；周期规律：第 N 项看 N÷周期 的余数。"],"pitfall":["新定义往往有自变量范围或大小顺序限制（如 a＞b），翻译时一字不漏！"],"example":{"q":"定义新运算 a⊕b＝a²－ab，若 3⊕x＝6，求 x。","a":"3²－3x＝6 ⇒ 9－3x＝6 ⇒ x＝1。","img":"./assets/knowledge/math/sp/p24-newdef.svg"}},"qids":["kp-math-sp-p24-01","kp-math-sp-p24-02","kp-math-sp-p24-03","kp-math-sp-p24-04","kp-math-sp-p24-05","kp-math-sp-p24-06","kp-math-sp-p24-07","kp-math-sp-p24-08","kp-math-sp-p24-09"],"refs":[]}]},{"id":"math-sp-c1","name":"中考计算保底与防错","unit":"专题·计算保底","points":[{"id":"math-sp-p01","name":"符号、乘方与去括号防错","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题目中出现 －aⁿ 与 (－a)ⁿ 混排、负号紧跟多重括号或负系数乘法分配律","有理数混合运算或整式化简求值里给出负数代入值（如 x＝－2，y＝－1）","孩子平时思路全对，但一做计算题就因为“差一个负号”整题丢分"],"steps":["① 先画顺序线：乘方与绝对值 → 乘除 → 加减，绝不跳步口算","② 盯紧底数边界：无括号时负号独立在外（－3²＝－9），有括号时负号归底数（(－3)²＝9）","③ 由内向外逐层去括号：括号前是负号或负系数，里面每一项都要乘并变号","④ 代入负数一律套括号，算完用逆运算复核一遍符号"],"variants":["基础考法：单纯有理数乘方、绝对值与四则混合运算，专挖 －2² 与 (－2)² 的坑","进阶变式：含小括号、中括号的整式化简求值，考查连续变号与同类项合并","压轴综合：在二次函数求顶点、方程求判别式或分式通分中暗藏负号陷阱"],"parentGuide":{"ask":"你看 －3² 和 (－3)² 这两个式子，结果一样吗？为什么不一样？","key":"必须答出：不一样；－3²＝－9（底数是 3，负号在外面），(－3)²＝9（底数是 －3，两个 －3 相乘得正）。"},"examples":[{"title":"变式母题拆解 · 乘方与负系数去括号混合防错","q":"计算：－3²－(－2)³＋|－4|÷(－2)－2(3－5)。","eye":"① 题眼在四个高频雷区同框：－3² 无括号、偶数和奇数次幂混排、绝对值后接除负数、负系数 －2 乘括号。","method":"② 通法“分块先算，符号留痕”：把每一项分别化成一个带符号的数，再统一去括号做加减。","steps":"③ 规范步骤：原式＝－9－(－8)＋4÷(－2)－2×(－2)＝－9＋8－2＋4＝1。"}]},"card":{"concept":["中考计算丢分 70% 出在负号和去括号：先定符号，再算绝对值，步步落纸不跳步。","－2² 表示 2² 的相反数（＝－4）；(－2)² 表示两个 －2 相乘（＝4）。","括号前是“－”号，去掉括号和负号后，括号里每一项都要变号。"],"formula":["－(a－b＋c)＝－a＋b－c；－aⁿ 与 (－a)ⁿ 偶数次幂互为相反数。"],"pitfall":["－3²＝－9，不是 9！","去多重括号时由内向外逐层去，乘法分配律遇到负系数（如 －2(x－3)＝－2x＋6）最易漏变第二项符号。"],"example":{"q":"计算：－2²＋(－3)²－2(1－4)。","a":"－4＋9－2×(－3)＝5＋6＝11。"}},"qids":["kp-math-sp-p01-01","kp-math-sp-p01-02","kp-math-sp-p01-03","kp-math-sp-p01-04","kp-math-sp-p01-05","kp-math-sp-p01-06","kp-math-sp-p01-07","kp-math-sp-p01-08","kp-math-sp-p01-09"],"refs":[]},{"id":"math-sp-p02","name":"实数、二次根式与三角函数混合计算","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["中考解答题第 1 题同时出现 0 次幂、负整数指数幂、绝对值、二次根式和特殊角三角函数","绝对值符号内含有无理数相减（如 |2－√8|、|√3－2|）","算式中出现 √12、√18、√27 等非最简二次根式与 sin/cos/tan 混算"],"steps":["① 单项独立化简：把原式拆成 4～5 块，在草稿纸上逐块化到最简数","② 负指数先倒再乘方：(a/b)⁻ⁿ＝(b/a)ⁿ；0 次幂只要底数非零直接写 1","③ 绝对值先比大小：大减小为正直接去，小减大为负整体变号并加括号","④ 三角函数代精确值后，有理数与有理数合并、同类二次根式合并"],"variants":["基础考法：4 项混合送分题，重点考负指数与 0 次幂基本定义","进阶变式：加入 √a÷√b、平方差公式或无理数绝对值，考查根式化简与去括号","压轴综合：结合网格作图或特殊直角三角形求值，最终结果常出现根式完全抵消为整数"],"parentGuide":{"ask":"考你两个最容易写反的：(－1/3)⁻² 等于多少？|2－√8| 去掉绝对值怎么写？","key":"必须答出：(－1/3)⁻²＝(－3)²＝9（不是 －9 也不是 1/9）；因为 2＝√4＜√8，所以 |2－√8|＝√8－2＝2√2－2。"},"examples":[{"title":"变式母题拆解 · 实数根式与三角函数五项混算","q":"计算：(－1/3)⁻²－|2－√8|＋√18÷√2＋4 cos 45°＋(√5－2)⁰。","eye":"① 题眼在于 －|2－√8| 前有负号且绝对值内为负，需先翻正再加括号；cos 45°＝√2/2 与 2√2 正好呼应。","method":"② 逐项化简到位再抄回原式，同类二次根式 －2√2 与 ＋2√2 抵消验算更放心。","steps":"③ 规范步骤：原式＝9－(2√2－2)＋√9＋4×(√2/2)＋1＝9－2√2＋2＋3＋2√2＋1＝15。"}]},"card":{"concept":["中考解答题第 1 题固定送分题（6～8 分）：通常把零指数幂、负整数指数幂、绝对值、二次根式、特殊角三角函数混在一道题里。","满分动作：每一小项单独在草稿纸化简成最简数，抄下来再合并，绝不跳步！"],"formula":["a⁰＝1（a≠0）；(a/b)⁻ⁿ＝(b/a)ⁿ；√(a²)＝|a|；|√3－2|＝2－√3。"],"pitfall":["(1/2)⁻¹＝2，不是 －2；tan 30°＝√3/3，tan 60°＝√3，别记反！"],"example":{"q":"计算：(1/3)⁻¹－|√3－2|＋(π－3)⁰－2 sin 60°。","a":"3－(2－√3)＋1－√3＝3－2＋√3＋1－√3＝2。"}},"qids":["kp-math-sp-p02-01","kp-math-sp-p02-02","kp-math-sp-p02-03","kp-math-sp-p02-04","kp-math-sp-p02-05","kp-math-sp-p02-06","kp-math-sp-p02-07","kp-math-sp-p02-08","kp-math-sp-p02-09"],"refs":[]},{"id":"math-sp-p03","name":"分式化简求值与防踩禁区","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["题目要求“先化简，再求值”，且最后一句写“从若干个数中选一个合适的数代入”","算式中出现分式加减括号后紧跟“÷ 另一个分式”","分母是二次多项式（如 x²－4x＋4、x²－1）需要先因式分解"],"steps":["① 先分解后通分：把所有能分解的分子、分母全部因式分解，找准最简公分母","② 括号内通分做加减，减号后面的新分子务必整体加括号防符号错","③ 除变乘再约分：除以分式等于乘它的倒数，约分化到最简分式或整式","④ 选值必做排雷表：原式所有分母≠0 且除式分子≠0，划掉禁区再代入"],"variants":["基础考法：直接给定具体数值代入求值，重点考通分和因式分解","进阶变式：自选合适整数代入，4 个备选数中藏着 2～3 个禁区雷值","压轴综合：结合方程的根（如 x²－2x－1＝0）整体代入，或结合不等式组先求整数解再排雷代入"],"parentGuide":{"ask":"分式化简完了，选数字代入求值之前，必须检查哪两类“禁区”不能等于 0？","key":"必须答出：① 原式里每一个分母都不能为 0；② 除号后面那个分式的分子也不能为 0（不能除以 0）。"},"examples":[{"title":"变式母题拆解 · 括号通分＋三重禁区排雷","q":"先化简：(1＋1/(x－2))÷[(x²－1)/(x²－4x＋4)]，再从 －1、1、2、3 中选一个合适的数代入求值。","eye":"① 题眼是备选数里有 －1、1、2 三个雷值，其中 －1 和 1 藏在除式分子 x²－1 里，化简后看不见但代入必扣分！","method":"② 先把整式 1 化成 (x－2)/(x－2) 通分，除式分子分母因式分解后颠倒相乘约分，最后逐一排查禁区。","steps":"③ 规范步骤：原式＝[(x－1)/(x－2)]×[(x－2)²/((x＋1)(x－1))]＝(x－2)/(x＋1)。由原式有意义得 x≠2、x≠1、x≠－1，只能取 x＝3，原式＝(3－2)/(3＋1)＝1/4。"}]},"card":{"concept":["中考解答题第 2 题常见保底题：先算括号内（通分），再把除法变乘法（分子分母因式分解后约分），最后代入求值。"],"formula":["自选代入值排雷清单：① 原式各分母≠0；② 除号后分式的分子≠0！"],"pitfall":["括号内通分时，整式 1 或 x 要看成分母为 1 的分式；选值代入前把所有禁区列出来划掉！"],"example":{"q":"化简 (1－1/(x＋1))÷(x/(x²－1))，并从 －1、0、1、2 中选合适值代入。","a":"原式＝[x/(x＋1)]·[(x＋1)(x－1)/x]＝x－1；x≠－1、0、1，只能取 x＝2，值为 1。"}},"qids":["kp-math-sp-p03-01","kp-math-sp-p03-02","kp-math-sp-p03-03","kp-math-sp-p03-04","kp-math-sp-p03-05","kp-math-sp-p03-06","kp-math-sp-p03-07","kp-math-sp-p03-08","kp-math-sp-p03-09"],"refs":[]},{"id":"math-sp-p04","name":"方程（组）与不等式（组）防丢解/漏变号","tag":"◆★","hasEssay":true,"hasDeep":true,"deep":{"triggers":["一元二次方程两边出现相同含未知数的公因式（如 (2x－1)²＝3(2x－1)）","解不等式（组）时出现分数分母或未知数系数为负数","分式方程中出现互为相反数的分母（如 x－3 与 3－x）"],"steps":["① 一元二次方程严禁两边同除未知因式，一律移项到左边提公因式分解","② 去分母时方程或不等式每一项（含常数项）都要同乘最小公倍数，分子整体加括号","③ 不等式两边同乘或同除负数，不等号方向立刻翻转","④ 分式方程解出 x 后必须写“检验”二字并代入最简公分母，等于 0 则判增根无解"],"variants":["基础考法：单独解二元一次方程组、不等式组或一元二次方程，考查基本规范","进阶变式：方程与不等式混合，要求写出不等式组的整数解或非负整数解","压轴综合：含参分式方程无解（含增根与整式方程本身无解两类）或方程组解满足不等式"],"parentGuide":{"ask":"解方程 (2x－1)²＝3(2x－1) 时，能不能两边直接除以 (2x－1)？为什么？","key":"必须答出：不能！因为 2x－1 可能等于 0，直接除会丢掉 x＝1/2 这个根，应该移项提公因式 (2x－1)(2x－4)＝0。"},"examples":[{"title":"变式母题拆解 · 防丢根与分式增根双演练","q":"（1）解方程：(2x－1)²＝3(2x－1)；（2）解分式方程：x/(x－3)＋2＝3/(x－3)。","eye":"① 第（1）问诱惑你约掉 (2x－1) 丢根；第（2）问常数项 2 容易漏乘 (x－3)，且解出的根恰为增根。","method":"② 一元二次方程移项提公因式；分式方程两边同乘 (x－3) 后务必代入公分母检验。","steps":"③ 规范步骤：（1）移项得 (2x－1)(2x－1－3)＝0，即 (2x－1)(2x－4)＝0，解得 x₁＝1/2，x₂＝2；（2）去分母得 x＋2(x－3)＝3，3x＝9，x＝3，检验 x－3＝0 是增根，故原方程无解。"}]},"card":{"concept":["四大保底防错铁律：① 去分母常数项不漏乘；② 不等式乘除负数必变号；③ 分式方程必验增根；④ 一元二次方程不乱除未知数。"],"formula":["检验习惯：解出方程后花 5 秒代回原方程口算，100% 消灭低级失误！"],"pitfall":["x(x－2)＝x－2 两边直接除以 (x－2) 会丢掉 x＝2！","分式方程解出使分母为 0 的数要写“是增根，原方程无解”。"],"example":{"q":"解分式方程 x/(x－1)－1＝3/[(x－1)(x＋2)]。","a":"去分母 x(x＋2)－(x－1)(x＋2)＝3 ⇒ x＋2＝3 ⇒ x＝1，检验 x－1＝0 是增根，无解！"}},"qids":["kp-math-sp-p04-01","kp-math-sp-p04-02","kp-math-sp-p04-03","kp-math-sp-p04-04","kp-math-sp-p04-05","kp-math-sp-p04-06","kp-math-sp-p04-07","kp-math-sp-p04-08","kp-math-sp-p04-09"],"refs":[]}]}],"questions":[{"id":"kp-math-sp-p01-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（基础）","level":1,"kpFree":true,"type":"blank","stem":"计算：－2²＋(－2)²＝______。","blanks":[["0"]],"answer":["0"],"explanation":"－4＋4＝0。坑点：把 －2² 算成 4 得 8。"},{"id":"kp-math-sp-p01-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（基础）","level":1,"kpFree":true,"type":"blank","stem":"计算：－3²＋(－1)²⁰²⁶＝______。","blanks":[["-8","－8"]],"answer":["-8"],"explanation":"－9＋1＝－8。"},{"id":"kp-math-sp-p01-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（基础）","level":1,"kpFree":true,"type":"single","stem":"化简 －2(x－3) 的结果是（ ）","options":[{"key":"A","text":"－2x＋6"},{"key":"B","text":"－2x－3"},{"key":"C","text":"－2x＋3"},{"key":"D","text":"－2x－6"}],"answer":["A"],"explanation":"－2·x＋(－2)·(－3)＝－2x＋6。坑点：漏变第二项符号。"},{"id":"kp-math-sp-p01-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"计算：－1⁴－(1－0.5)×(－6)＝______。","blanks":[["2"]],"answer":["2"],"explanation":"－1－0.5×(－6)＝－1＋3＝2。"},{"id":"kp-math-sp-p01-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（提高）","level":2,"kpFree":false,"type":"single","stem":"化简 3a－[2a－(a－1)] 的结果是（ ）","options":[{"key":"A","text":"4a－1"},{"key":"B","text":"2a－1"},{"key":"C","text":"a－1"},{"key":"D","text":"2a＋1"}],"answer":["B"],"explanation":"3a－[a＋1]＝2a－1。"},{"id":"kp-math-sp-p01-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（提高）","level":2,"kpFree":false,"type":"blank","stem":"计算：－2³÷(－4)－(－3)²＝______。","blanks":[["-7","－7"]],"answer":["-7"],"explanation":"(－8)÷(－4)－9＝2－9＝－7。"},{"id":"kp-math-sp-p01-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（拓展）","level":3,"kpFree":false,"type":"blank","stem":"若 a＝－2，则 －a²－(－a)²＝______。","blanks":[["-8","－8"]],"answer":["-8"],"explanation":"a²＝4，(－a)²＝4，故 －4－4＝－8。"},{"id":"kp-math-sp-p01-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（拓展）","level":3,"kpFree":false,"type":"blank","stem":"计算：(－2)³＋|－5|－(－1)⁵×3＝______。","blanks":[["0"]],"answer":["0"],"explanation":"－8＋5－(－3)＝－3＋3＝0。"},{"id":"kp-math-sp-p01-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p01","kp":"符号、乘方与去括号防错","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 符号、乘方与去括号防错（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"有理数与整式化简计算大题","stem":"计算与化简求值：（1）计算：－2⁴＋(－3)²×|－2|－(－1)²⁰²⁶÷(－1/2)；（2）先化简，再求值：3(2x²－xy)－2[3x²－(xy－y²)]，其中 x＝－2，y＝－1。","score":10,"points":[{"text":"正确计算各单项：－2⁴＝－16，(－3)²×|－2|＝18，(－1)²⁰²⁶÷(－1/2)＝－2","score":3,"keys":["－16","18","－2"]},{"text":"合并得出第（1）问结果：－16＋18－(－2)＝4","score":2,"keys":["－16＋18","4"]},{"text":"逐层去括号并合并同类项，化简得 －xy－2y²","score":3,"keys":["6x²－3xy","－xy－2y²"]},{"text":"代入 x＝－2、y＝－1 并正确计算结果 －4","score":2,"keys":["－(－2)×(－1)","－4"]}],"method":"① 第一问严格按“先乘方与绝对值、再乘除、最后加减”逐项拆算，特别注意 －2⁴＝－16 而非 16；② 除以分数转化为乘倒数，连同前面的减号一起处理符号；③ 第二问由内向外逐层去括号，括号前是负号时里面每一项都要变号；④ 合并同类项后再代入负数值，代入负数一律加括号。","sample":"解：（1）原式＝－16＋9×2－1×(－2)\n＝－16＋18－(－2)\n＝2＋2\n＝4。\n（2）原式＝6x²－3xy－2(3x²－xy＋y²)\n＝6x²－3xy－6x²＋2xy－2y²\n＝－xy－2y²。\n当 x＝－2，y＝－1 时，\n原式＝－(－2)×(－1)－2×(－1)²＝－2－2＝－4。","explanation":"阅卷易错红线：① 把 －2⁴ 错算成 16（忽略负号不在底数内）；② 去中括号 －2(3x²－xy＋y²) 时漏给第三项 ＋y² 乘 －2；③ 代入 x＝－2、y＝－1 时漏加括号导致 －xy 符号算错。"},{"id":"kp-math-sp-p02-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"计算：(1/2)⁻¹＋(2026－π)⁰－|－3|＝______。","blanks":[["0"]],"answer":["0"],"explanation":"2＋1－3＝0。"},{"id":"kp-math-sp-p02-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"计算：√12－2 sin 60°－√3＝______。","blanks":[["0"]],"answer":["0"],"explanation":"2√3－√3－√3＝0。"},{"id":"kp-math-sp-p02-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（基础）","level":1,"kpFree":true,"type":"blank","stem":"计算：∛(－8)＋(－1)²⁰²⁶＋2 cos 60°＝______。","blanks":[["0"]],"answer":["0"],"explanation":"－2＋1＋1＝0。"},{"id":"kp-math-sp-p02-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"计算：(1/3)⁻¹－|√3－2|＋(π－3)⁰－2 sin 60°＝______。","blanks":[["2"]],"answer":["2"],"explanation":"3－(2－√3)＋1－√3＝2。"},{"id":"kp-math-sp-p02-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"计算：(－1/2)⁻²＋√8－4 cos 45°＝______。","blanks":[["4"]],"answer":["4"],"explanation":"4＋2√2－2√2＝4。"},{"id":"kp-math-sp-p02-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（提高）","level":2,"kpFree":false,"type":"blank","stem":"计算：|1－√2|＋(√2－1)⁰－√2＋2 tan 45°＝______。","blanks":[["2"]],"answer":["2"],"explanation":"(√2－1)＋1－√2＋2＝2。"},{"id":"kp-math-sp-p02-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（拓展）","level":3,"kpFree":false,"type":"blank","stem":"计算：(－2)⁻²×8＋√27÷√3－(√5－2)⁰＝______。","blanks":[["4"]],"answer":["4"],"explanation":"1/4×8＋3－1＝2＋3－1＝4。"},{"id":"kp-math-sp-p02-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（拓展）","level":3,"kpFree":false,"type":"blank","stem":"计算：√((－3)²)－2⁻¹×4＋√3 tan 30°－(－1)³＝______。","blanks":[["3"]],"answer":["3"],"explanation":"3－2＋1－(－1)＝3。"},{"id":"kp-math-sp-p02-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p02","kp":"实数、二次根式与三角函数混合计算","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 实数、二次根式与三角函数混合计算（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"实数与三角函数混合计算大题","stem":"计算下列各题：（1）(－1/2)⁻²＋|√3－2|－(2026－π)⁰－√12＋6 sin 60°；（2）(√27－√12)÷√3＋(√2－1)(√2＋1)－2 cos 30°×√3＋(－1/3)⁻¹。","score":10,"points":[{"text":"正确化简第（1）问各项：(－1/2)⁻²＝4，|√3－2|＝2－√3，(2026－π)⁰＝1，√12＝2√3，6 sin 60°＝3√3","score":3,"keys":["2－√3","2√3","3√3"]},{"text":"合并同类项及同类二次根式，得第（1）问最终结果 5","score":2,"keys":["4＋2－√3－1","5"]},{"text":"正确化简第（2）问各项：(√27－√12)÷√3＝1，(√2－1)(√2＋1)＝1，2 cos 30°×√3＝3，(－1/3)⁻¹＝－3","score":3,"keys":["3－2","－3","√3/2"]},{"text":"合并计算得出第（2）问结果 －4","score":2,"keys":["1＋1－3－3","－4"]}],"method":"① 每一小项单独化简到位：负整数指数幂先取倒数再乘方，非零数的 0 次幂恒为 1；② 去绝对值前先比大小：√3＜2，故 |√3－2|＝2－√3；③ 牢记 sin 60°＝√3/2、cos 30°＝√3/2，代入后与二次根式合并；④ 第二问用除法分配律和平方差公式化简后再做加减。","sample":"解：（1）原式＝4＋(2－√3)－1－2√3＋6×(√3/2)\n＝4＋2－√3－1－2√3＋3√3\n＝5。\n（2）原式＝(3√3－2√3)÷√3＋[(√2)²－1²]－2×(√3/2)×√3＋(－3)\n＝3－2＋(2－1)－3－3\n＝1＋1－3－3\n＝－4。","explanation":"阅卷易错红线：① 把 (－1/2)⁻² 错算成 －4 或 －1/4（偶数次幂必为正）；② 去 |√3－2| 时忘记变号写成 √3－2；③ 把 (－1/3)⁻¹ 错算成 3（负指数只取倒数不改变底数正负号）。"},{"id":"kp-math-sp-p03-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（基础）","level":1,"kpFree":true,"type":"single","stem":"化简 (x²－4)/(x²－4x＋4) 的结果是（ ）","options":[{"key":"A","text":"(x－2)/(x＋2)"},{"key":"B","text":"x＋2"},{"key":"C","text":"(x＋2)/(x－2)"},{"key":"D","text":"－1"}],"answer":["C"],"explanation":"(x＋2)(x－2)/(x－2)²＝(x＋2)/(x－2)。"},{"id":"kp-math-sp-p03-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（基础）","level":1,"kpFree":true,"type":"single","stem":"化简 (1－1/x)÷[(x－1)/x²] 的结果是（ ）","options":[{"key":"A","text":"1"},{"key":"B","text":"1/x"},{"key":"C","text":"x－1"},{"key":"D","text":"x"}],"answer":["D"],"explanation":"[(x－1)/x]·[x²/(x－1)]＝x。"},{"id":"kp-math-sp-p03-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（基础）","level":1,"kpFree":true,"type":"blank","stem":"先化简 [a/(a－2)－2/(a－2)]·(a＋3)，当 a＝5 时值为______。","blanks":[["8"]],"answer":["8"],"explanation":"1·(a＋3)＝a＋3，a＝5 时为 8。"},{"id":"kp-math-sp-p03-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"化简 [1/(x－1)－1/(x＋1)]÷[2/(x²－1)] 后，下列哪个 x 值不能代入原式求值？（ ）","options":[{"key":"A","text":"x＝1"},{"key":"B","text":"x＝－2"},{"key":"C","text":"x＝3"},{"key":"D","text":"x＝2"}],"answer":["A"],"explanation":"x＝1 使原分母 x－1＝0 无意义。"},{"id":"kp-math-sp-p03-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（提高）","level":2,"kpFree":false,"type":"blank","stem":"化简 (1＋2/(x－1))÷[(x＋1)/(x－1)]，当 x＝4 时，结果为______。","blanks":[["1"]],"answer":["1"],"explanation":"[(x＋1)/(x－1)]÷[(x＋1)/(x－1)]＝1（x≠±1 时恒为 1）。"},{"id":"kp-math-sp-p03-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（提高）","level":2,"kpFree":false,"type":"blank","stem":"化简 (a－2＋4/(a＋2))÷[a/(a＋2)]，当 a＝3 时，结果为______。","blanks":[["3"]],"answer":["3"],"explanation":"括号内＝(a²－4＋4)/(a＋2)＝a²/(a＋2)，除以 a/(a＋2) 得 a，代入得 3。"},{"id":"kp-math-sp-p03-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（拓展）","level":3,"kpFree":false,"type":"blank","stem":"已知 x²－2x－1＝0，则 (x－1)²＋2/(x²－2x)＝______。","blanks":[["4"]],"answer":["4"],"explanation":"x²－2x＝1，原式＝(x²－2x＋1)＋2/1＝2＋2＝4。"},{"id":"kp-math-sp-p03-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（拓展）","level":3,"kpFree":false,"type":"blank","stem":"化简 [1/(x－2)＋1/(x＋2)]÷[2x/(x²－4)]，当 x＝5 时值为______。","blanks":[["1"]],"answer":["1"],"explanation":"括号内＝2x/(x²－4)，相除恒为 1。"},{"id":"kp-math-sp-p03-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p03","kp":"分式化简求值与防踩禁区","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 分式化简求值与防踩禁区（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"分式化简求值与禁区排雷大题","stem":"先化简：[ (x＋2)/(x²－2x) － (x－1)/(x²－4x＋4) ] ÷ (x－4)/x，再从 －2、0、2、4 中选取一个合适的整数代入求值。","score":8,"points":[{"text":"分解分母并通分，分子正确化简为 x－4","score":3,"keys":["x(x－2)²","x－4"]},{"text":"把除法转化为乘法并约分，得到最简结果 1/(x－2)²","score":2,"keys":["x/(x－4)","1/(x－2)²"]},{"text":"明确列出所有禁区 x≠0、x≠2、x≠4，只选 x＝－2 并算出结果 1/16","score":3,"keys":["x≠0","x＝－2","1/16"]}],"method":"① 先把所有分母因式分解：x²－2x＝x(x－2)，x²－4x＋4＝(x－2)²，确定最简公分母 x(x－2)²；② 括号内通分减法时，后一个分子展开务必加括号；③ 除以分式变为乘它的倒数，约分化到最简；④ 选值前必须排雷：原式所有分母及除式分子均不能为 0，逐一排除禁区值。","sample":"解：原式＝[ (x＋2)/[x(x－2)] － (x－1)/(x－2)² ] × x/(x－4)\n＝[ (x＋2)(x－2)－x(x－1) ] / [ x(x－2)² ] × x/(x－4)\n＝[ (x²－4)－(x²－x) ] / [ x(x－2)² ] × x/(x－4)\n＝(x－4) / [ x(x－2)² ] × x/(x－4)\n＝1/(x－2)²。\n要使原分式有意义，需满足 x(x－2)≠0，(x－2)²≠0 且 x－4≠0，即 x≠0，x≠2，x≠4。\n故只能取 x＝－2，\n当 x＝－2 时，原式＝1/(－2－2)²＝1/16。","explanation":"阅卷易错红线：① 只看最终结果 1/(x－2)² 而误代 x＝0 或 x＝4（踩中原分母与除式分子禁区，求值分全扣）；② 通分做减法 －x(x－1) 时漏变号写成 －x²－x。"},{"id":"kp-math-sp-p04-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（基础）","level":1,"kpFree":true,"type":"single","stem":"解不等式 (x－1)/2－1＞0，去分母正确的一步是（ ）","options":[{"key":"A","text":"2x－2－1＞0"},{"key":"B","text":"x－1－2＞0"},{"key":"C","text":"x－1＋2＞0"},{"key":"D","text":"x－1－1＞0"}],"answer":["B"],"explanation":"两边同乘 2，常数项 －1 也要乘 2 得 －2。"},{"id":"kp-math-sp-p04-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（基础）","level":1,"kpFree":true,"type":"single","stem":"方程 x(x－3)＝2(x－3) 的解是（ ）","options":[{"key":"A","text":"x₁＝－2，x₂＝3"},{"key":"B","text":"x＝3"},{"key":"C","text":"x₁＝2，x₂＝3"},{"key":"D","text":"x＝2"}],"answer":["C"],"explanation":"移项提公因式 (x－3)(x－2)＝0，得 x₁＝2，x₂＝3。坑点：两边同除 (x－3) 丢根 3。"},{"id":"kp-math-sp-p04-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（基础）","level":1,"kpFree":true,"type":"single","stem":"分式方程 2/(x－2)＝x/(x－2) 的解的情况是（ ）","options":[{"key":"A","text":"x＝2"},{"key":"B","text":"x＝0"},{"key":"C","text":"x＝－2"},{"key":"D","text":"无解"}],"answer":["D"],"explanation":"去分母得 x＝2，但 x＝2 使分母 x－2＝0 是增根，原方程无解。坑点：忘记验根。"},{"id":"kp-math-sp-p04-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"不等式组 3－x≥1 与 (x＋1)/2＞0 的所有整数解之和是______。","blanks":[["3"]],"answer":["3"],"explanation":"x≤2 且 x＞－1，整数解 0、1、2，和为 3。"},{"id":"kp-math-sp-p04-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（提高）","level":2,"kpFree":false,"type":"blank","stem":"解方程组 2x＋3y＝13 与 3x－2y＝0，得 x＋y＝______。","blanks":[["5"]],"answer":["5"],"explanation":"①×2＋②×3 得 13x＝26 ⇒ x＝2，y＝3，x＋y＝5。"},{"id":"kp-math-sp-p04-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（提高）","level":2,"kpFree":false,"type":"blank","stem":"解分式方程 x/(x－1)－2/(x＋1)＝1，得 x＝______。","blanks":[["3"]],"answer":["3"],"explanation":"去分母 x(x＋1)－2(x－1)＝x²－1 ⇒ x²＋x－2x＋2＝x²－1 ⇒ －x＝－3 ⇒ x＝3，检验成立！"},{"id":"kp-math-sp-p04-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（拓展）","level":3,"kpFree":false,"type":"blank","stem":"若关于 x 的不等式组 x－a＞0 与 1－2x＞－3 恰有 2 个整数解，且 a 为整数，则 a＝______。","blanks":[["-1","－1"]],"answer":["-1"],"explanation":"a＜x＜2 恰有 2 个整数解 1、0，故 －1≤a＜0，整数 a＝－1。"},{"id":"kp-math-sp-p04-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（拓展）","level":3,"kpFree":false,"type":"blank","stem":"方程 (x－1)²＝3(x－1) 的两根之和是______。","blanks":[["5"]],"answer":["5"],"explanation":"(x－1)(x－4)＝0，两根 1 和 4，和为 5。"},{"id":"kp-math-sp-p04-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p04","kp":"方程（组）与不等式（组）防丢解/漏变号","unit":"专题·计算保底","chapter":"专题与压轴 · 中考计算保底与防错","source":"知识点精练 · 专题与压轴 · 方程（组）与不等式（组）防丢解/漏变号（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"不等式组与分式方程计算大题","stem":"解答下列两题：（1）解不等式组：{ ① 2－(x－1)/3 ≥ x；② 5－2x ＜ 9 }，并写出它的所有整数解；（2）解分式方程：(x－1)/(x－2) ＋ 1/(2－x) ＝ 2。","score":10,"points":[{"text":"正确解出不等式①得 x≤7/4，解出不等式②得 x＞－2","score":3,"keys":["x≤7/4","x＞－2"]},{"text":"得出不等式组解集 －2＜x≤7/4，并写出所有整数解 －1、0、1","score":2,"keys":["－2＜x≤7/4","－1、0、1"]},{"text":"化同分母并去分母，列出整式方程 (x－1)－1＝2(x－2) 并解得 x＝2","score":3,"keys":["2(x－2)","x＝2"]},{"text":"代入最简公分母检验 x－2＝0，判定 x＝2 是增根，得出原方程无解","score":2,"keys":["增根","无解"]}],"method":"① 解第（1）问不等式①去分母时，常数项 2 和右侧 x 都要同乘 3，且分子 (x－1) 务必加括号；② 不等式②除以负数 －2 时不等号方向必须改变；③ 取两个解集的公共部分后再列整数解；④ 解第（2）问先把 1/(2－x) 化为 －1/(x－2)，去分母解出 x 后必须代入最简公分母检验是否为增根。","sample":"解：（1）解不等式①：去分母，得 6－(x－1)≥3x，\n去括号，得 6－x＋1≥3x，\n移项合并，得 －4x≥－7，\n系数化为 1，得 x≤7/4。\n解不等式②：移项，得 －2x＜4，\n两边同除以 －2，得 x＞－2。\n所以不等式组的解集为 －2＜x≤7/4，\n它的所有整数解为 －1、0、1。\n（2）原方程可化为 (x－1)/(x－2)－1/(x－2)＝2。\n方程两边同乘 (x－2)，得 (x－1)－1＝2(x－2)，\n即 x－2＝2x－4，解得 x＝2。\n检验：当 x＝2 时，x－2＝0，故 x＝2 是原分式方程的增根，\n因此原分式方程无解。","explanation":"阅卷易错红线：① 解①时去分母漏乘常数项 2 或去掉 －(x－1) 括号漏变号；② 解② －2x＜4 两边除以 －2 忘记变号；③ 分式方程不写“检验”步骤，直接答 x＝2 扣光结论分。"},{"id":"kp-math-sp-p05-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p05-dblmed.svg","type":"single","stem":"如图，在 △ABC 中，AD 是 BC 边上的中线，延长 AD 到 E 使 DE＝AD，连接 BE，判定 △ADC≌△EDB 的依据是（ ）","options":[{"key":"A","text":"SAS"},{"key":"B","text":"SSS"},{"key":"C","text":"ASA"},{"key":"D","text":"HL"}],"answer":["A"],"explanation":"AD＝ED，∠ADC＝∠EDB（对顶角），DC＝DB，满足 SAS。"},{"id":"kp-math-sp-p05-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p05-dblmed.svg","type":"single","stem":"如图，△ABC 中 AB＝8，AC＝6，AD 是中线，则 AD 的取值范围是（ ）","options":[{"key":"A","text":"2＜AD＜7"},{"key":"B","text":"1＜AD＜7"},{"key":"C","text":"1≤AD≤7"},{"key":"D","text":"2＜AD＜14"}],"answer":["B"],"explanation":"2＜2AD＜14 ⇒ 1＜AD＜7。"},{"id":"kp-math-sp-p05-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（基础）","level":1,"kpFree":true,"type":"blank","stem":"△ABC 中 AB＝10，AC＝4，AD 是中线，则 AD 的最大整数值是______。","blanks":[["6"]],"answer":["6"],"explanation":"3＜AD＜7，最大整数为 6。"},{"id":"kp-math-sp-p05-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（提高）","level":2,"kpFree":true,"kpDiag":true,"image":"./assets/knowledge/math/sp/p05-dblmed.svg","type":"blank","stem":"如图，△ABC 中 AB＝5，AC＝3，AD 是中线且 AD＝2，则 △ABC 的面积是______。","blanks":[["6"]],"answer":["6"],"explanation":"倍长 AD 到 E 得 △ABE 三边为 5、3、4（直角三角形），S△ABC＝S△ABE＝1/2×3×4＝6！"},{"id":"kp-math-sp-p05-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（提高）","level":2,"kpFree":false,"type":"blank","stem":"△ABC 中 AB＝13，AC＝5，中线 AD＝6，则 ∠BAC＋∠ABE 的对应角关系中，△ABE 是直角三角形，故 △ABC 面积是______。","blanks":[["30"]],"answer":["30"],"explanation":"倍长中线得 2AD＝12，5²＋12²＝13²，S△ABC＝S△ABE＝1/2×5×12＝30。"},{"id":"kp-math-sp-p05-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p05-dblmed.svg","type":"single","stem":"如图，倍长中线 AD 到 E 后，线段 AC 与 BE 的位置和数量关系是（ ）","options":[{"key":"A","text":"相等但不平行"},{"key":"B","text":"平行但不相等"},{"key":"C","text":"平行且相等"},{"key":"D","text":"互相垂直"}],"answer":["C"],"explanation":"△ADC≌△EDB 得 AC＝BE 且内错角 ∠CAD＝∠BED ⇒ AC∥BE。"},{"id":"kp-math-sp-p05-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p05-dblmed.svg","type":"blank","stem":"如图，在 △ABC 中，AD 是中线，AB＝10，AC＝6，AD＝4，则 ∠CAD＝______°。","blanks":[["90"]],"answer":["90"],"explanation":"倍长 AD 到 E 得 2AD＝8，BE＝6，AB＝10，6²＋8²＝10² 得 ∠AEB＝90°，由全等得 ∠CAD＝∠AEB＝90°！"},{"id":"kp-math-sp-p05-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在 △ABC 中，AB＝7，AC＝5，中线 AD 为整数，则 AD 的所有可能取值之和是______。","blanks":[["14"]],"answer":["14"],"explanation":"1＜AD＜6，整数为 2、3、4、5，和为 2＋3＋4＋5＝14。"},{"id":"kp-math-sp-p05-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p05","kp":"倍长中线模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 倍长中线模型（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"几何证明压轴题","stem":"在 △ABC 中，AB＝6，AC＝10，AD 是 BC 边上的中线。（1）求 AD 的取值范围；（2）若 ∠BAC＝90°，求中线 AD 的长。","score":10,"points":[{"text":"延长 AD 到 E 使 DE＝AD，连接 BE，用 SAS 证明 △ADC≌△EDB 得 BE＝AC＝10","score":4,"keys":["延长","DE","SAS","全等","10"]},{"text":"在 △ABE 中列三边不等式 10－6＜2AD＜10＋6，解得 2＜AD＜8","score":3,"keys":["2AD","2＜AD＜8","2<AD<8"]},{"text":"∠BAC＝90° 时 BC＝√(6²＋10²)＝2√34，故 AD＝1/2 BC＝√34","score":3,"keys":["2√34","√34","斜边"]}],"method":"① 见中线先“倍长中线”：延长 AD 到 E 使 DE＝AD，连 BE；② 证 △ADC≌△EDB（SAS），把分散边 AC 转移到 BE；③ 在 △ABE 中利用三边关系求 2AD 范围，最后别忘除以 2；④ 第二问用勾股定理求斜边 BC，再由“直角三角形斜边中线等于斜边一半”秒解。","sample":"解：（1）延长 AD 至点 E，使 DE＝AD，连接 BE。\n因为 AD 是 △ABC 的中线，所以 BD＝CD。\n在 △ADC 和 △EDB 中，AD＝ED，∠ADC＝∠EDB，DC＝DB，\n所以 △ADC≌△EDB（SAS），得 BE＝AC＝10。\n在 △ABE 中，由三角形三边关系得：BE－AB＜AE＜BE＋AB，\n即 10－6＜2AD＜10＋6，4＜2AD＜16，\n故 2＜AD＜8。\n（2）当 ∠BAC＝90° 时，在 Rt△ABC 中，BC＝√(AB²＋AC²)＝√(6²＋10²)＝√136＝2√34。\n因为 AD 是 Rt△ABC 斜边 BC 上的中线，所以 AD＝1/2 BC＝√34。","explanation":"阅卷易错点：① 辅助线必须写清“延长 AD 到 E 使 DE＝AD，连接 BE”；② 求出 4＜2AD＜16 后忘记除以 2 是高频丢分点；③ 结果 √136 必须化简为 2√34。"},{"id":"kp-math-sp-p06-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p06-cut.svg","type":"blank","stem":"如图，在 △ABC 中，AD 平分 ∠BAC，∠B＝2∠C，若 AB＝5，BD＝3，则 AC＝______。","blanks":[["8"]],"answer":["8"],"explanation":"在 AC 上截 AE＝AB＝5，证 △ABD≌△AED 得 EC＝DE＝BD＝3，AC＝5＋3＝8。"},{"id":"kp-math-sp-p06-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p06-cut.svg","type":"blank","stem":"如图，AD 平分 ∠BAC，∠B＝2∠C，若 AC＝11，AB＝7，则 BD＝______。","blanks":[["4"]],"answer":["4"],"explanation":"BD＝AC－AB＝11－7＝4。"},{"id":"kp-math-sp-p06-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p06-cut.svg","type":"single","stem":"如图，用截长法在 AC 上截取 AE＝AB，连接 DE，判定 △ABD≌△AED 的依据是（ ）","options":[{"key":"A","text":"HL"},{"key":"B","text":"ASA"},{"key":"C","text":"SSS"},{"key":"D","text":"SAS"}],"answer":["D"],"explanation":"AB＝AE，∠BAD＝∠EAD，AD＝AD，满足 SAS。"},{"id":"kp-math-sp-p06-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"在四边形 ABCD 中，AB∥CD，AE 平分 ∠BAD 交 BC 中点 E，则 AD＝AB＋CD。若 AB＝4，CD＝7，则 AD＝______。","blanks":[["11"]],"answer":["11"],"explanation":"延长 AE 交 DC 延长线（补短）得等腰三角形，AD＝AB＋CD＝11。"},{"id":"kp-math-sp-p06-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p06-cut.svg","type":"blank","stem":"如图，△ABC 中 ∠B＝2∠C，AD 平分 ∠BAC，若 ∠C＝28°，在 AC 上截 AE＝AB，则 ∠CDE＝______°。","blanks":[["28"]],"answer":["28"],"explanation":"∠AED＝∠B＝56°，由外角得 ∠CDE＝56°－28°＝28°。"},{"id":"kp-math-sp-p06-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（提高）","level":2,"kpFree":false,"type":"blank","stem":"在 △ABC 中，∠A＝60°，BD、CE 分别平分 ∠ABC、∠ACB 交于点 I，用截长补短法可得 BC＝BE＋CD。若 BE＝3，CD＝4，则 BC＝______。","blanks":[["7"]],"answer":["7"],"explanation":"在 BC 上截 BF＝BE，连 IF，由 ∠BIC＝120° 得双 SAS 全等，BC＝BE＋CD＝7。"},{"id":"kp-math-sp-p06-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在 △ABC 中，∠A＝60°，BD、CE 分别平分 ∠ABC、∠ACB 交于点 I，则 ∠BIC＝______°。","blanks":[["120"]],"answer":["120"],"explanation":"∠BIC＝90°＋1/2∠A＝120°。"},{"id":"kp-math-sp-p06-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（拓展）","level":3,"kpFree":false,"type":"blank","stem":"正方形 ABCD 边长为 6，E 在 BC 上，F 在 CD 上，∠EAF＝45°，若 BE＝2，DF＝3，则 EF＝______。","blanks":[["5"]],"answer":["5"],"explanation":"补短（或旋转）得 EF＝BE＋DF＝2＋3＝5。"},{"id":"kp-math-sp-p06-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p06","kp":"截长补短模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 截长补短模型（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"几何证明压轴题","stem":"在 △ABC 中，AD 平分 ∠BAC 交 BC 于 D，且 ∠B＝2∠C。（1）求证：AC＝AB＋BD；（2）若 AB＝5，BD＝3，求 AC 的长。","score":10,"points":[{"text":"在 AC 上截取 AE＝AB，连接 DE，利用角平分线用 SAS 证 △ABD≌△AED","score":4,"keys":["截取","AE","SAS","全等"]},{"text":"由全等得 DE＝BD、∠AED＝∠B＝2∠C，结合外角定理推出 ∠EDC＝∠C，得 EC＝DE＝BD","score":4,"keys":["外角","∠EDC","EC＝DE","EC=DE"]},{"text":"证得 AC＝AE＋EC＝AB＋BD，代入得 AC＝5＋3＝8","score":2,"keys":["AB＋BD","8"]}],"method":"① 见“a＋b＝c ＋ 角平分线 ＋ 二倍角”，立刻选用“截长法”：在长边 AC 上截取 AE＝AB，连接 DE；② 先用 SAS 证 △ABD≌△AED，把 BD 和 ∠B 转移到 DE 和 ∠AED；③ 再用三角形外角定理把 2∠C 拆成 ∠C＋∠EDC，证出等腰 △DEC 得 EC＝DE＝BD。","sample":"（1）证明：在 AC 上截取 AE＝AB，连接 DE。\n因为 AD 平分 ∠BAC，所以 ∠BAD＝∠EAD。\n又因为 AD＝AD，AB＝AE，所以 △ABD≌△AED（SAS）。\n因此 DE＝BD，∠AED＝∠B。\n又因为 ∠B＝2∠C，所以 ∠AED＝2∠C。\n因为 ∠AED 是 △DEC 的外角，所以 ∠AED＝∠C＋∠EDC，\n故 ∠EDC＝∠C，所以 EC＝DE＝BD。\n因此 AC＝AE＋EC＝AB＋BD。\n（2）解：由（1）得 AC＝AB＋BD＝5＋3＝8。","explanation":"本题也可采用“补短法”（延长 AB 到 F 使 BF＝BD，连接 DF），同样通过等腰三角形与 AAS 证明 AF＝AC；书写时需交代外角关系，不可跳步。"},{"id":"kp-math-sp-p07-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p07-hand.svg","type":"blank","stem":"如图，△ABC 和 △CDE 都是等边三角形，A、C、D 共线，若 BD＝10，则 AE＝______。","blanks":[["10"]],"answer":["10"],"explanation":"手拉手全等 △ACE≌△BCD，AE＝BD＝10。"},{"id":"kp-math-sp-p07-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p07-hand.svg","type":"blank","stem":"如图，△ABC 和 △CDE 都是等边三角形，AE 与 BD 交于点 P，则锐角 ∠APD＝______°。","blanks":[["60"]],"answer":["60"],"explanation":"旋转角为 60°，两对应直线夹角等于 60°。"},{"id":"kp-math-sp-p07-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（基础）","level":1,"kpFree":true,"type":"blank","stem":"共顶点 O 的两个等腰直角三角形 △OAB 和 △OCD（∠AOB＝∠COD＝90°），连接 AC、BD，若 AC＝7，则 BD＝______。","blanks":[["7"]],"answer":["7"],"explanation":"△OAC≌△OBD（SAS），BD＝AC＝7。"},{"id":"kp-math-sp-p07-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"共顶点 O 的两个等腰直角三角形 △OAB、△OCD（∠AOB＝∠COD＝90°），连接 AC、BD，则直线 AC 与 BD 的夹角是______°。","blanks":[["90"]],"answer":["90"],"explanation":"旋转角 90°，故 AC⊥BD，夹角 90°。"},{"id":"kp-math-sp-p07-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p07-hand.svg","type":"blank","stem":"如图，△ABC、△CDE 均为等边三角形，AE 交 BC 于 M，BD 交 CE 于 N，则 △CMN 一定是等边三角形，若 CM＝3，则 MN＝______。","blanks":[["3"]],"answer":["3"],"explanation":"由 ASA 得 △ACM≌△BCN ⇒ CM＝CN，又 ∠MCN＝60°，故 △CMN 是等边三角形，MN＝3。"},{"id":"kp-math-sp-p07-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（提高）","level":2,"kpFree":false,"type":"blank","stem":"两个共顶点 C 的等腰三角形 △CAB 与 △CDE，顶角 ∠ACB＝∠DCE＝50°，连接 AD、BE 相交于 P，则锐角 ∠APB＝______°。","blanks":[["50"]],"answer":["50"],"explanation":"拉手线夹角等于顶角 50°。"},{"id":"kp-math-sp-p07-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p07-hand.svg","type":"blank","stem":"如图，△ABC 和 △CDE 均为等边三角形，AE、BD 交于 P，连接 PC，则 ∠APC＝______°。","blanks":[["60"]],"answer":["60"],"explanation":"PC 平分 ∠APD 的邻补角 ∠APE（120°），故 ∠APC＝60°。"},{"id":"kp-math-sp-p07-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（拓展）","level":3,"kpFree":false,"type":"blank","stem":"若两个共顶点 O 的正方形 OABC 与 ODEF（顺时针排列），连接 AD、CF，若 AD＝6√2，则以 AD、CF 为对角线的四边形 ACDF 面积是______。","blanks":[["36"]],"answer":["36"],"explanation":"手拉手得 AD＝CF＝6√2 且 AD⊥CF，对角线垂直的四边形面积＝1/2×6√2×6√2＝36！"},{"id":"kp-math-sp-p07-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p07","kp":"手拉手旋转全等模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 手拉手旋转全等模型（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"旋转全等压轴题","stem":"点 C 在线段 AD 上，分别以 AC、CD 为边在 AD 同侧作等边 △ABC 和等边 △CDE，连接 AE、BD 交于点 P。（1）求证：AE＝BD；（2）求 ∠APD 的度数，并求出 AE 与 BD 所成锐角的度数。","score":12,"points":[{"text":"由双等边三角形得 AC＝BC、CE＝CD、∠ACB＝∠ECD＝60°，推得 ∠ACE＝∠BCD＝120°","score":4,"keys":["120°","120","AC＝BC","CE＝CD"]},{"text":"用 SAS 证明 △ACE≌△BCD，得出 AE＝BD 及 ∠CEA＝∠CDB","score":4,"keys":["SAS","全等","AE＝BD","AE=BD"]},{"text":"在 △APD 中求得 ∠PAD＋∠PDA＝∠CAE＋∠CEA＝60°，故 ∠APD＝120°，所成锐角为 60°","score":4,"keys":["120°","60°","60"]}],"method":"① 识别共顶点 C 的双等边三角形→典型“手拉手”模型；② 证 ∠ACE＝∠BCD＝120°，用 SAS 证 △ACE≌△BCD；③ 倒角求夹角：在 △APD 中把 ∠PDA 换成全等对应角 ∠CEA，直接用 △ACE 内角和 60° 秒算 ∠APD。","sample":"（1）证明：因为 △ABC 和 △CDE 都是等边三角形，\n所以 AC＝BC，CE＝CD，∠ACB＝∠ECD＝60°。\n因为点 C 在线段 AD 上，所以 ∠BCE＝180°－60°－60°＝60°。\n因此 ∠ACE＝∠ACB＋∠BCE＝120°，∠BCD＝∠ECD＋∠BCE＝120°，即 ∠ACE＝∠BCD。\n在 △ACE 和 △BCD 中，AC＝BC，∠ACE＝∠BCD，CE＝CD，\n所以 △ACE≌△BCD（SAS），故 AE＝BD。\n（2）解：由 △ACE≌△BCD 得 ∠CEA＝∠CDB。\n在 △ACE 中，∠CAE＋∠CEA＝180°－∠ACE＝180°－120°＝60°。\n在 △APD 中，∠PAD＋∠PDA＝∠CAE＋∠CEA＝60°，\n所以 ∠APD＝180°－60°＝120°。\n因此 AE 与 BD 所成的锐角为 180°－120°＝60°。","explanation":"手拉手全等常见第三问还会考“连接 PC，求证 PC 平分 ∠APD”（过 C 向 AE、BD 作高，用全等三角形对应高相等＋角平分线判定即可证明）。"},{"id":"kp-math-sp-p08-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p08-3rt.svg","type":"blank","stem":"如图，B、C、D 共线，∠B＝∠ACE＝∠D＝90°，AC＝CE，若 AB＝4，DE＝3，则 BD＝______。","blanks":[["7"]],"answer":["7"],"explanation":"△ABC≌△CDE，BC＝3，CD＝4，BD＝7。"},{"id":"kp-math-sp-p08-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p08-3rt.svg","type":"blank","stem":"如图，B、C、D 共线，∠B＝∠ACE＝∠D＝90°，AC＝CE，AB＝3，DE＝4，则 AE 的平方 AE²＝______。","blanks":[["50"]],"answer":["50"],"explanation":"AC＝√(3²＋4²)＝5，等腰 Rt△ACE 中 AE²＝5²＋5²＝50。"},{"id":"kp-math-sp-p08-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p08-3rt.svg","type":"single","stem":"如图，B、C、D 共线，∠B＝∠ACE＝∠D＝90°，AC＝CE，判定 △ABC≌△CDE 的依据是（ ）","options":[{"key":"A","text":"SSS"},{"key":"B","text":"SAS"},{"key":"C","text":"AAS"},{"key":"D","text":"HL"}],"answer":["C"],"explanation":"∠B＝∠D＝90°，∠A＝∠ECD，AC＝CE，满足 AAS。"},{"id":"kp-math-sp-p08-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"在平面直角坐标系中，等腰直角三角形 ABC 中 ∠C＝90°，CA＝CB，已知 C(0, 0)、A(－2, 3)，点 B 在第一象限，则点 B(x, y) 满足 x＋y＝______。","blanks":[["5"]],"answer":["5"],"explanation":"一线三直角构造全等得 B(3, 2)，x＋y＝5。"},{"id":"kp-math-sp-p08-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（提高）","level":2,"kpFree":false,"type":"blank","stem":"在平面直角坐标系中，等腰 Rt△ABC 中 ∠B＝90°，BA＝BC，A(0, 4)、B(2, 0)，点 C 在第一象限，则点 C 的纵坐标是______。","blanks":[["2"]],"answer":["2"],"explanation":"过 C 作 CD⊥x 轴，△AOB≌△BDC，CD＝OB＝2，BD＝OA＝4，故 C(6, 2)，纵坐标 2。"},{"id":"kp-math-sp-p08-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p08-3rt.svg","type":"blank","stem":"如图，B、C、D 共线，∠B＝∠ACE＝∠D＝90°（不要求 AC＝CE），若 AB＝4，BC＝6，CD＝2，则 DE＝______。","blanks":[["3"]],"answer":["3"],"explanation":"△ABC∽△CDE，AB/CD＝BC/DE ⇒ 4/2＝6/DE ⇒ DE＝3。"},{"id":"kp-math-sp-p08-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p08-3rt.svg","type":"blank","stem":"如图，梯形 ABDE 中 ∠B＝∠D＝90°，∠ACE＝90° 且 AC＝CE，AB＝5，DE＝3，则梯形 ABDE 的面积是______。","blanks":[["32"]],"answer":["32"],"explanation":"BD＝5＋3＝8，面积＝(5＋3)×8÷2＝32。"},{"id":"kp-math-sp-p08-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在等腰 △ABC 中，AB＝AC，D、E、F 分别在 BC、AB、AC 上，若 ∠EDF＝∠B（一线三等角），则 △EBD∽△DCF。若 BD＝4，DC＝6，BE＝3，则 CF＝______。","blanks":[["8"]],"answer":["8"],"explanation":"BE/CD＝BD/CF ⇒ 3/6＝4/CF ⇒ CF＝8。"},{"id":"kp-math-sp-p08-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p08","kp":"一线三等角（一线三直角）模型","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 一线三等角（一线三直角）模型（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"坐标系几何压轴题","stem":"在平面直角坐标系中，等腰直角 △ABC 的直角顶点为 C(2, 0)，点 A 的坐标为 (0, 4)，点 B 在第一象限内。（1）求点 B 的坐标；（2）求直线 AB 的函数解析式。","score":10,"points":[{"text":"过点 B 作 BD⊥x 轴于 D，由 ∠AOC＝∠ACB＝∠BDC＝90° 倒角得 ∠OAC＝∠DCB","score":3,"keys":["BD⊥x轴","垂线","∠OAC＝∠DCB","互余"]},{"text":"结合 AC＝BC 用 AAS 证 △AOC≌△CDB，得 CD＝OA＝4、BD＝OC＝2，推出 B(6, 2)","score":4,"keys":["AAS","全等","6","B(6,2)","(6, 2)"]},{"text":"设 y＝kx＋b 代入 A(0, 4) 与 B(6, 2)，解得直线 AB 为 y＝－1/3 x＋4","score":3,"keys":["-1/3","－1/3","y＝－1/3 x＋4"]}],"method":"① 坐标系遇等腰直角三角形，立刻过非轴上顶点 B 作 x 轴垂线 BD，构造“一线三直角”（∠AOC＝∠ACB＝∠BDC＝90°）；② 互余倒角用 AAS 证 △AOC≌△CDB；③ 由对应边相等直接读出点 B 坐标，再用待定系数法求直线 AB。","sample":"解：（1）过点 B 作 BD⊥x 轴于点 D，则 ∠BDC＝∠AOC＝90°。\n因为 ∠ACB＝90°，所以 ∠ACO＋∠BCD＝90°。\n又在 Rt△AOC 中，∠ACO＋∠OAC＝90°，所以 ∠OAC＝∠DCB。\n因为 △ABC 是等腰直角三角形，所以 AC＝BC。\n在 △AOC 和 △CDB 中，∠AOC＝∠CDB，∠OAC＝∠DCB，AC＝CB，\n所以 △AOC≌△CDB（AAS）。\n因此 CD＝OA＝4，BD＝OC＝2。\n又 OC＝2 且点 B 在第一象限，所以 OD＝OC＋CD＝2＋4＝6，故 B(6, 2)。\n（2）设直线 AB 的解析式为 y＝kx＋b，代入 A(0, 4) 得 b＝4；\n代入 B(6, 2) 得 6k＋4＝2，解得 k＝－1/3。\n所以直线 AB 的解析式为 y＝－1/3 x＋4。","explanation":"本题若不限定点 B 在第一象限，还存在第四象限对称解 B'(-2, -2)（绕 C 顺/逆时针旋转 90°），审题时务必看清象限条件。"},{"id":"kp-math-sp-p09-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p09-half.svg","type":"blank","stem":"如图，正方形 ABCD 边长为 6，E 在 BC 上、F 在 CD 上，∠EAF＝45°，若 BE＝2，DF＝3，则 EF＝______。","blanks":[["5"]],"answer":["5"],"explanation":"半角模型结论：EF＝BE＋DF＝5。"},{"id":"kp-math-sp-p09-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p09-half.svg","type":"blank","stem":"如图，正方形 ABCD 边长为 5，∠EAF＝45°，则 △CEF 的周长是______。","blanks":[["10"]],"answer":["10"],"explanation":"周长＝CE＋CF＋EF＝CE＋CF＋BE＋DF＝2AB＝10。"},{"id":"kp-math-sp-p09-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p09-half.svg","type":"blank","stem":"如图，正方形 ABCD 边长为 6，∠EAF＝45°，过点 A 作 AH⊥EF 于 H，则 AH＝______。","blanks":[["6"]],"answer":["6"],"explanation":"全等三角形对应高相等，AH＝AB＝6。"},{"id":"kp-math-sp-p09-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（提高）","level":2,"kpFree":true,"kpDiag":true,"image":"./assets/knowledge/math/sp/p09-half.svg","type":"blank","stem":"如图，正方形 ABCD 边长为 6，∠EAF＝45°，若 BE＝2，则 DF＝______。","blanks":[["3"]],"answer":["3"],"explanation":"设 DF＝x，EF＝2＋x，CE＝4，CF＝6－x，4²＋(6－x)²＝(2＋x)² ⇒ 16x＝48 ⇒ x＝3。"},{"id":"kp-math-sp-p09-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p09-half.svg","type":"blank","stem":"如图，正方形 ABCD 边长为 6，E 在 BC 上、F 在 CD 上，∠EAF＝45°，若 BE＝2，DF＝3，则 △AEF 的面积是______。","blanks":[["15"]],"answer":["15"],"explanation":"EF＝5，高 AH＝6，S△AEF＝1/2×5×6＝15。"},{"id":"kp-math-sp-p09-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p09-half.svg","type":"blank","stem":"如图，正方形 ABCD 中 ∠EAF＝45°，若 ∠BAE＝20°，则 ∠AFE＝______°。","blanks":[["65"]],"answer":["65"],"explanation":"∠DAF＝25°，∠AFD＝65°，由全等得 ∠AFE＝∠AFD＝65°。"},{"id":"kp-math-sp-p09-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"等腰直角三角形 ABC 中 ∠BAC＝90°，点 D、E 在斜边 BC 上且 ∠DAE＝45°。把 △ABD 绕 A 旋转 90° 可得 BD²＋CE²＝DE²！若 BD＝3，CE＝4，则 DE＝______。","blanks":[["5"]],"answer":["5"],"explanation":"DE＝√(3²＋4²)＝5。"},{"id":"kp-math-sp-p09-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p09-half.svg","type":"blank","stem":"如图，正方形 ABCD 边长为 4，∠EAF＝45°，若 E 是 BC 中点（BE＝2），设 DF＝x，则 2²＋(4－x)²＝(2＋x)²，解得 DF＝______（填最简分数）。","blanks":[["4/3"]],"answer":["4/3"],"explanation":"4＋16－8x＝4＋4x ⇒ 12x＝16 ⇒ x＝4/3。"},{"id":"kp-math-sp-p09-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p09","kp":"半角模型（90° 夹 45° / 120° 夹 60°）","unit":"专题·全等模型","chapter":"专题与压轴 · 全等与辅助线模型","source":"知识点精练 · 专题与压轴 · 半角模型（90° 夹 45° / 120° 夹 60°）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"正方形半角压轴题","stem":"正方形 ABCD 的边长为 6，点 E 在边 BC 上，点 F 在边 CD 上，且 ∠EAF＝45°。（1）求证：EF＝BE＋DF；（2）若 BE＝2，求 DF 的长及 △AEF 的面积。","score":12,"points":[{"text":"延长 CD 到 G 使 DG＝BE，连 AG，用 SAS 证 △ABE≌△ADG，得 AE＝AG、∠BAE＝∠DAG","score":4,"keys":["延长","DG＝BE","旋转","△ADG"]},{"text":"推出 ∠GAF＝45°＝∠EAF，用 SAS 证 △AEF≌△AGF，证得 EF＝GF＝BE＋DF","score":4,"keys":["45°","SAS","△AGF","BE＋DF"]},{"text":"设 DF＝x，在 Rt△ECF 中列方程 4²＋(6－x)²＝(2＋x)² 解得 DF＝3，并求得 S△AEF＝15","score":4,"keys":["DF＝3","x＝3","x=3","15"]}],"method":"① 半角模型必用旋转拼接：把 △ABE 绕 A 顺时针旋转 90° 至 △ADG（使 AB 与 AD 重合，G 在 CD 延长线上）；② 证 ∠GAF＝45°＝∠EAF，用 SAS 证 △AEF≌△AGF 得 EF＝BE＋DF；③ 第二问设 DF＝x，把三边表示出来代入 Rt△ECF 勾股定理求解，面积可用“正方形面积减三小角”或“1/2·EF·AB”秒算。","sample":"（1）证明：延长 CD 至点 G，使 DG＝BE，连接 AG。\n在正方形 ABCD 中，AB＝AD，∠B＝∠ADG＝90°，\n又 BE＝DG，所以 △ABE≌△ADG（SAS）。\n因此 AE＝AG，∠BAE＝∠DAG。\n因为 ∠EAF＝45°，所以 ∠BAE＋∠DAF＝90°－45°＝45°，\n故 ∠GAF＝∠DAG＋∠DAF＝45°＝∠EAF。\n在 △AEF 和 △AGF 中，AE＝AG，∠EAF＝∠GAF，AF＝AF，\n所以 △AEF≌△AGF（SAS），得 EF＝GF＝DF＋DG＝BE＋DF。\n（2）解：设 DF＝x，则 CF＝6－x，CE＝6－2＝4，由（1）得 EF＝2＋x。\n在 Rt△ECF 中，CE²＋CF²＝EF²，即 4²＋(6－x)²＝(2＋x)²。\n展开得 16＋36－12x＋x²＝4＋4x＋x²，解得 16x＝48，x＝3，即 DF＝3。\n所以 EF＝5；又由 △AEF≌△AGF 知点 A 到 EF 的距离等于 AD＝6，\n故 S△AEF＝1/2 × EF × AD＝1/2 × 5 × 6＝15。","explanation":"半角模型两大计算捷径：① Rt△ECF 必列勾股方程；② △AEF 边 EF 上的高恒等于正方形边长 AB，直接算 1/2·EF·AB 又快又准。"},{"id":"kp-math-sp-p10-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p10-sim.svg","type":"blank","stem":"如图，Rt△ABC 中 ∠C＝90°，CD⊥AB 于 D，若 AD＝3，BD＝12，则 CD＝______。","blanks":[["6"]],"answer":["6"],"explanation":"CD²＝3×12＝36，CD＝6。"},{"id":"kp-math-sp-p10-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p10-sim.svg","type":"blank","stem":"如图，Rt△ABC 中 ∠C＝90°，CD⊥AB 于 D，若 AC＝6，AB＝9，则 AD＝______。","blanks":[["4"]],"answer":["4"],"explanation":"AC²＝AD·AB ⇒ 36＝9AD ⇒ AD＝4。"},{"id":"kp-math-sp-p10-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（基础）","level":1,"kpFree":true,"type":"blank","stem":"在 △ABC 中，点 D 在 AB 上，∠ACD＝∠B，若 AD＝2，DB＝6，则 AC＝______。","blanks":[["4"]],"answer":["4"],"explanation":"AC²＝AD·AB＝2×8＝16，AC＝4。"},{"id":"kp-math-sp-p10-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"矩形 ABCD 中 AB＝6，BC＝8，AE⊥BD 于 E，则 BE＝______。","blanks":[["3.6","18/5"]],"answer":["3.6"],"explanation":"BD＝10，射影定理 AB²＝BE·BD ⇒ 36＝10BE ⇒ BE＝3.6。"},{"id":"kp-math-sp-p10-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（提高）","level":2,"kpFree":false,"type":"blank","stem":"矩形 ABCD 中 AB＝4，BC＝6，点 E 在 BC 上，点 F 在 CD 上，且 AE⊥EF。若 BE＝2，则 CF＝______。","blanks":[["2"]],"answer":["2"],"explanation":"一线三直角得 △ABE∽△ECF，AB/EC＝BE/CF ⇒ 4/4＝2/CF ⇒ CF＝2。"},{"id":"kp-math-sp-p10-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p10-sim.svg","type":"blank","stem":"如图，Rt△ABC 中 ∠C＝90°，CD⊥AB，若 AD∶BD＝1∶4，则 S△ACD∶S△CBD＝1∶k，k＝______。","blanks":[["4"]],"answer":["4"],"explanation":"两三角形等高，面积比等于底之比 AD∶BD＝1∶4。"},{"id":"kp-math-sp-p10-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"圆中相交弦定理：⊙O 中两弦 AB、CD 交于 P，由 △APC∽△DPB 得 PA·PB＝PC·PD。若 PA＝3，PB＝8，PC＝4，则 PD＝______。","blanks":[["6"]],"answer":["6"],"explanation":"3×8＝4·PD ⇒ PD＝6。"},{"id":"kp-math-sp-p10-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"切割线定理：从圆外 P 引切线 PA 与割线 PBC，由 △PAB∽△PCA 得 PA²＝PB·PC。若 PB＝4，BC＝5，则 PA＝______。","blanks":[["6"]],"answer":["6"],"explanation":"PC＝4＋5＝9，PA²＝4×9＝36，PA＝6。"},{"id":"kp-math-sp-p10-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p10","kp":"相似综合（母子型、射影与一线三等角）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 相似综合（母子型、射影与一线三等角）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"相似综合解答题","stem":"在 Rt△ABC 中，∠ACB＝90°，CD⊥AB 于点 D，已知 AD＝4，BD＝9。（1）求证：△ACD∽△CBD；（2）求 CD、AC、BC 的长。","score":12,"points":[{"text":"由 ∠ACB＝90° 与 CD⊥AB 得 ∠ADC＝∠CDB＝90° 及 ∠A＝∠BCD（同角的余角相等）","score":4,"keys":["90°","∠A＝∠BCD","余角"]},{"text":"由两角对应相等（AA）证得 △ACD∽△CBD","score":2,"keys":["∽","相似"]},{"text":"列比例 AD/CD＝CD/BD 得 CD²＝36，解得 CD＝6","score":3,"keys":["CD＝6","CD=6","36"]},{"text":"由勾股定理（或射影定理）求得 AC＝2√13，BC＝3√13","score":3,"keys":["2√13","3√13"]}],"method":"① 直角三角形斜边作高构成“一图三相似”射影模型；② 利用同角的余角相等（∠A＝∠BCD）配直角证 △ACD∽△CBD；③ 写比例时对齐对应顶点字母，先求 CD，再用勾股定理或母子型相似求 AC、BC。","sample":"（1）证明：因为 CD⊥AB，所以 ∠ADC＝∠CDB＝90°。\n因为 ∠ACB＝90°，所以 ∠A＋∠ACD＝90°，\n又 ∠BCD＋∠ACD＝90°，所以 ∠A＝∠BCD。\n在 △ACD 和 △CBD 中，∠ADC＝∠CDB，∠A＝∠BCD，\n所以 △ACD∽△CBD（AA）。\n（2）解：由 △ACD∽△CBD 得 AD/CD＝CD/BD，\n即 CD²＝AD·BD＝4×9＝36，因为 CD＞0，所以 CD＝6。\n在 Rt△ACD 中，AC＝√(AD²＋CD²)＝√(4²＋6²)＝√52＝2√13；\n在 Rt△BCD 中，BC＝√(BD²＋CD²)＝√(9²＋6²)＝√117＝3√13。","explanation":"中考阅卷注意：射影定理不能在解答题里直接当已知定理用，必须像本题这样先证相似再写出乘积式，否则会扣过程分！"},{"id":"kp-math-sp-p11-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p11-circsim.svg","type":"blank","stem":"如图，BC 是 ⊙O 直径，PA 切 ⊙O 于 A 交 BC 延长线于 P，若 PC＝2，PA＝4，则 ⊙O 的半径 r＝______。","blanks":[["3"]],"answer":["3"],"explanation":"r²＋4²＝(r＋2)² ⇒ 4r＝12 ⇒ r＝3。"},{"id":"kp-math-sp-p11-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p11-circsim.svg","type":"blank","stem":"如图，PA 切 ⊙O 于 A，若 r＝3，PC＝2，则 sin P＝______（填小数或分数）。","blanks":[["0.6","3/5"]],"answer":["0.6"],"explanation":"OP＝5，OA＝3，sin P＝3/5＝0.6。"},{"id":"kp-math-sp-p11-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p11-circsim.svg","type":"blank","stem":"如图，BC 是 ⊙O 直径，PA 切 ⊙O 于 A，若 ∠P＝30°，半径 r＝4，则 PC＝______。","blanks":[["4"]],"answer":["4"],"explanation":"OP＝2OA＝8，PC＝8－4＝4。"},{"id":"kp-math-sp-p11-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（提高）","level":2,"kpFree":true,"kpDiag":true,"image":"./assets/knowledge/math/sp/p11-circsim.svg","type":"blank","stem":"如图，BC 是 ⊙O 直径，PA 切 ⊙O 于 A，由弦切角得 △PAC∽△PBA，故 PA²＝PC·PB。若 PC＝4，PB＝9，则 PA＝______。","blanks":[["6"]],"answer":["6"],"explanation":"PA＝√(4×9)＝6。"},{"id":"kp-math-sp-p11-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p11-circsim.svg","type":"blank","stem":"如图，BC 是 ⊙O 直径，PA 切 ⊙O 于 A 交 BC 延长线于 P，若 PC＝4，PB＝9，PA＝6，则 ⊙O 的半径 r＝______。","blanks":[["2.5","5/2"]],"answer":["2.5"],"explanation":"直径 BC＝PB－PC＝5，半径 2.5。"},{"id":"kp-math-sp-p11-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（提高）","level":2,"kpFree":false,"type":"blank","stem":"在 ⊙O 中，直径 AB＝10，弦 AC＝6，点 D 在圆上（与 C 在 AB 同侧），则 sin∠ADC＝______（填小数或分数）。","blanks":[["0.6","3/5"]],"answer":["0.6"],"explanation":"∠ADC＝∠ABC（同弧），Rt△ACB 中 sin∠ABC＝AC/AB＝6/10＝0.6。"},{"id":"kp-math-sp-p11-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p11-circsim.svg","type":"blank","stem":"如图，BC 是 ⊙O 直径，PA 切 ⊙O 于 A，若 r＝3，PA＝4，则 AB 与 AC 之比 AB/AC＝______。","blanks":[["2"]],"answer":["2"],"explanation":"△PAC∽△PBA，AB/AC＝PB/PA＝(5＋3)/4＝2！"},{"id":"kp-math-sp-p11-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在 △ABC 中，AB＝AC＝5，BC＝6，⊙O 是 △ABC 的外接圆，则 ⊙O 的半径 R＝______（填分数或小数）。","blanks":[["25/8","3.125"]],"answer":["25/8"],"explanation":"底边高 AD＝4，设半径 R：R²＝3²＋(4－R)² ⇒ 8R＝25 ⇒ R＝25/8（3.125）。"},{"id":"kp-math-sp-p11-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p11","kp":"圆与切线、相似及三角函数综合","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 圆与切线、相似及三角函数综合（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"圆的切线与相似压轴","stem":"已知 AB 是 ⊙O 的直径，点 C 在 ⊙O 上，AC 平分 ∠DAB，AD⊥CD 于点 D。（1）求证：CD 是 ⊙O 的切线；（2）若 AD＝4，AC＝5，求 ⊙O 的直径 AB 的长。","score":12,"points":[{"text":"连接 OC，由 OA＝OC 得 ∠OAC＝∠OCA，结合 AC 平分 ∠DAB 推出 ∠DAC＝∠OCA，故 OC∥AD","score":4,"keys":["连接OC","连OC","OC∥AD","平行"]},{"text":"由 AD⊥CD 得 OC⊥CD，且 OC 为半径，证得 CD 是 ⊙O 的切线","score":3,"keys":["OC⊥CD","切线"]},{"text":"连接 BC，由直径得 ∠ACB＝90°＝∠ADC，证 △ADC∽△ACB，列 AD/AC＝AC/AB 解得 AB＝25/4（或 6.25）","score":5,"keys":["△ACB","相似","25/4","6.25"]}],"method":"① 证切线且已知切点 C：“连半径 OC，证 OC⊥CD”；② 利用 OA＝OC 得等腰等角，结合角平分线证出内错角相等→OC∥AD→OC⊥CD；③ 第二问见直径连 BC 得 ∠ACB＝90°，构造母子/双直角相似 △ADC∽△ACB 算 AB。","sample":"（1）证明：连接 OC。\n因为 OA＝OC，所以 ∠OAC＝∠OCA。\n因为 AC 平分 ∠DAB，所以 ∠DAC＝∠OAC，\n故 ∠DAC＝∠OCA，所以 OC∥AD。\n又因为 AD⊥CD，所以 OC⊥CD。\n因为点 C 在 ⊙O 上（OC 是半径），所以 CD 是 ⊙O 的切线。\n（2）解：连接 BC。\n因为 AB 是 ⊙O 的直径，所以 ∠ACB＝90°。\n又 AD⊥CD，所以 ∠ADC＝90°＝∠ACB。\n因为 ∠DAC＝∠CAB，所以 △ADC∽△ACB（AA）。\n因此 AD/AC＝AC/AB，即 4/5＝5/AB，解得 AB＝25/4（即 6.25）。","explanation":"圆综合大题满分模板：“连半径证平行得垂直”证切线＋“见直径连弦得 90°”找相似；第二问也可直接用 cos∠DAC＝cos∠CAB＝4/5 得 AB＝5÷(4/5)＝25/4。"},{"id":"kp-math-sp-p12-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p12-hidden.svg","type":"blank","stem":"如图，线段 AB＝8 固定，动点 P 满足 ∠APB＝90°，则点 P 运动轨迹所在圆的半径是______。","blanks":[["4"]],"answer":["4"],"explanation":"直径为 8，半径为 4。"},{"id":"kp-math-sp-p12-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（基础）","level":1,"kpFree":true,"type":"blank","stem":"在平面内，定点 O，动点 P 满足 OP＝5，另一点 Q 满足 OQ＝12，则 PQ 的最小值是______。","blanks":[["7"]],"answer":["7"],"explanation":"P 在半径 5 的圆上，PQ 最小＝12－5＝7。"},{"id":"kp-math-sp-p12-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（基础）","level":1,"kpFree":true,"type":"blank","stem":"在平面内，定点 O，动点 P 满足 OP＝5，另一点 Q 满足 OQ＝12，则 PQ 的最大值是______。","blanks":[["17"]],"answer":["17"],"explanation":"PQ 最大＝12＋5＝17。"},{"id":"kp-math-sp-p12-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"在矩形 ABCD 中，AB＝6，BC＝4，点 P 是矩形内一动点且 ∠APB＝90°，则 PC 的最小值是______。","blanks":[["2"]],"answer":["2"],"explanation":"取 AB 中点 O，P 在以 O 为圆心、r＝3 的半圆上；OC＝√(3²＋4²)＝5，PC 最小＝5－3＝2。"},{"id":"kp-math-sp-p12-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（提高）","level":2,"kpFree":false,"type":"blank","stem":"已知 OA＝OB＝OC＝5，若 ∠AOB＝80°，且 C 在优弧 AB 上，则 ∠ACB＝______°。","blanks":[["40"]],"answer":["40"],"explanation":"A、B、C 在以 O 为圆心的隐圆上，圆周角＝1/2 圆心角＝40°。"},{"id":"kp-math-sp-p12-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p12-hidden.svg","type":"blank","stem":"如图，点 P 在以 AB（AB＝6）为直径的圆上运动，定点 Q 在 AB 的中垂线上且 OQ＝4，则 PQ 的最大值是______。","blanks":[["7"]],"answer":["7"],"explanation":"半径 r＝3，OQ＝4，最大值＝OQ＋r＝4＋3＝7。"},{"id":"kp-math-sp-p12-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在四边形 ABCD 中，∠A＝∠C＝90°，若 BD＝10，O 是 BD 中点，则 OA＋OC＝______。","blanks":[["10"]],"answer":["10"],"explanation":"A、B、C、D 四点共圆（BD 为直径），OA＝OC＝5，和为 10。"},{"id":"kp-math-sp-p12-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在 Rt△ABC 中，∠C＝90°，AC＝6，BC＝8，将点 C 绕点 A 旋转到 P 使 AP＝AC＝6，则 BP 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"AB＝10，P 在以 A 为圆心、6 为半径的圆上，BP 最小＝10－6＝4。"},{"id":"kp-math-sp-p12-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p12","kp":"隐圆模型（定点定长、定弦定角、四点共圆）","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 隐圆模型（定点定长、定弦定角、四点共圆）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"隐圆最值压轴题","stem":"在边长为 4 的正方形 ABCD 中，点 E、F 分别是边 BC、CD 上的动点，且 BE＝CF，连接 AE、BF 交于点 P。（1）求证：AE⊥BF；（2）在点 E、F 运动过程中，求线段 PC 长度的最小值。","score":12,"points":[{"text":"用 SAS 证明 △ABE≌△BCF，得 ∠BAE＝∠CBF，推出 ∠APB＝90° 即 AE⊥BF","score":4,"keys":["SAS","全等","90°","AE⊥BF"]},{"text":"识别隐圆：∠APB＝90° 且 AB＝4，点 P 在以 AB 中点 O 为圆心、半径 r＝2 的圆上","score":4,"keys":["中点","圆","半径","2"]},{"text":"在 Rt△OBC 中算得 OC＝√(2²＋4²)＝2√5，由一箭穿心得 PC 最小值为 2√5－2","score":4,"keys":["2√5","2√5－2","2√5-2"]}],"method":"① 第一问直接用 SAS 证 △ABE≌△BCF，互余倒角证 ∠APB＝90°；② 第二问抓住“AB＝4 定长 ＋ ∠APB＝90° 定角”→典型“定弦定角”隐圆！点 P 在以 AB 中点 O 为圆心、r＝2 为半径的圆弧上；③ 连接 OC 用勾股定理算圆心距，再用“一箭穿心”求 PCmin＝OC－r。","sample":"（1）证明：在正方形 ABCD 中，AB＝BC，∠ABE＝∠BCF＝90°。\n又因为 BE＝CF，所以 △ABE≌△BCF（SAS），得 ∠BAE＝∠CBF。\n因为 ∠CBF＋∠ABF＝90°，所以 ∠BAE＋∠ABF＝90°，\n故 ∠APB＝180°－90°＝90°，即 AE⊥BF。\n（2）解：取 AB 的中点 O，连接 OP、OC。\n在 Rt△APB 中，OP 是斜边 AB 上的中线，所以 OP＝1/2 AB＝2（定值）。\n因此点 P 在以 O 为圆心、半径 r＝2 的圆弧上运动。\n在 Rt△OBC 中，OB＝2，BC＝4，由勾股定理得 OC＝√(2²＋4²)＝2√5。\n由三角形三边关系 OP＋PC≥OC，得 PC≥OC－OP＝2√5－2（当 O、P、C 三点共线时取等号）。\n故 PC 长度的最小值为 2√5－2。","explanation":"规范作答技巧：中考解答题写隐圆时，补一句“OP＋PC≥OC（当 O、P、C 共线时取等号）”，既严谨又不怕扣说明分！"},{"id":"kp-math-sp-p13-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p13-guadou.svg","type":"blank","stem":"如图，⊙O 半径为 6，点 A 为定点，P 在 ⊙O 上运动，M 是线段 AP 的中点，则点 M 运动轨迹的圆半径是______。","blanks":[["3"]],"answer":["3"],"explanation":"中位线 O'M＝1/2 OP＝3。"},{"id":"kp-math-sp-p13-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（基础）","level":1,"kpFree":true,"type":"blank","stem":"在平面直角坐标系中，点 A(0, 4)，点 P 在 x 轴上运动，M 是 AP 的中点，则点 M 始终在直线 y＝______ 上运动。","blanks":[["2"]],"answer":["2"],"explanation":"M 纵坐标恒为 (4＋0)/2＝2。"},{"id":"kp-math-sp-p13-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（基础）","level":1,"kpFree":true,"type":"blank","stem":"定点 O，主动点 P 在长 10 的线段 AB 上运动，M 是 OP 中点，则从动点 M 运动的路径总长是______。","blanks":[["5"]],"answer":["5"],"explanation":"相似比 1/2，路径长 10×1/2＝5。"},{"id":"kp-math-sp-p13-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（提高）","level":2,"kpFree":true,"kpDiag":true,"image":"./assets/knowledge/math/sp/p13-guadou.svg","type":"blank","stem":"如图，⊙O 半径为 4，OA＝10，P 在 ⊙O 上运动，M 是 AP 中点，则 OM 的最小值是______。","blanks":[["3"]],"answer":["3"],"explanation":"O' 是 OA 中点，OO'＝5，从动圆半径 r'＝2，OM 最小＝5－2＝3。"},{"id":"kp-math-sp-p13-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（提高）","level":2,"kpFree":false,"image":"./assets/knowledge/math/sp/p13-guadou.svg","type":"blank","stem":"如图，⊙O 半径为 4，OA＝10，P 在 ⊙O 上运动，M 是 AP 中点，则 OM 的最大值是______。","blanks":[["7"]],"answer":["7"],"explanation":"OO'＝5，r'＝2，OM 最大＝5＋2＝7。"},{"id":"kp-math-sp-p13-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（提高）","level":2,"kpFree":false,"type":"single","stem":"定点 A，主动点 P 沿直线 l 运动，以 AP 为边向外作等边三角形 APM，则点 M 的运动轨迹是（ ）","options":[{"key":"A","text":"圆"},{"key":"B","text":"直线"},{"key":"C","text":"抛物线"},{"key":"D","text":"无法确定"}],"answer":["B"],"explanation":"瓜豆原理：主轨迹是直线，经旋转 60°（定比 1）后从轨迹仍是直线。"},{"id":"kp-math-sp-p13-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（拓展）","level":3,"kpFree":false,"type":"blank","stem":"⊙O 半径为 2，点 P 在 ⊙O 上运动，A 是圆外定点，以 AP 为边作等边三角形 APM，则点 M 运动轨迹圆的半径是______。","blanks":[["2"]],"answer":["2"],"explanation":"缩放比 k＝1，从动圆半径等于原半径 2。"},{"id":"kp-math-sp-p13-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在正方形 ABCD 中，AB＝4，P 是 CD 边上一动点，M 是 AP 中点，当 P 从 C 移动到 D 时，点 M 运动的路径长是______。","blanks":[["2"]],"answer":["2"],"explanation":"M 路径长＝1/2 CD＝2。"},{"id":"kp-math-sp-p13-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p13","kp":"动点轨迹与瓜豆原理入门","unit":"专题·相似与圆","chapter":"专题与压轴 · 相似与圆综合压轴","source":"知识点精练 · 专题与压轴 · 动点轨迹与瓜豆原理入门（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"瓜豆原理轨迹压轴","stem":"已知 ⊙O 的半径为 4，点 A 为 ⊙O 外一定点，且 OA＝10，点 P 是 ⊙O 上的动点，M 是线段 AP 的中点。（1）求证：点 M 到定点 O'（OA 的中点）的距离为定值，并指出点 M 的轨迹；（2）求线段 OM 长度的最大值与最小值。","score":12,"points":[{"text":"取 OA 中点 O'，连接 O'M、OP，由三角形中位线定理证得 O'M＝1/2 OP＝2","score":5,"keys":["中位线","O'M","2"]},{"text":"指出点 M 的运动轨迹是以 OA 中点 O' 为圆心、半径为 2 的圆","score":3,"keys":["圆心","半径","2","圆"]},{"text":"由 OO'＝5，得 OM 最小值为 5－2＝3，最大值为 5＋2＝7","score":4,"keys":["OO'＝5","3","7"]}],"method":"① 识别“定点 A ＋ 圆上主动点 P ＋ 中点 M”→典型中点瓜豆模型；② 取 OA 中点 O'，连接 O'M、OP，用三角形中位线定理得 O'M＝1/2 OP＝2；③ 转化成定点 O 到圆 O' 上动点 M 的最值（一箭穿心）：OO'±r'。","sample":"（1）证明：取 OA 的中点 O'，连接 O'M、OP。\n因为 O' 是 OA 的中点，M 是 AP 的中点，\n所以 O'M 是 △OAP 的中位线，故 O'M＝1/2 OP＝1/2 × 4＝2（定值）。\n因此，点 M 的运动轨迹是以 OA 中点 O' 为圆心、2 为半径的圆。\n（2）解：因为 O' 是 OA 中点，OA＝10，所以 OO'＝5。\n因为点 M 在以 O' 为圆心、r'＝2 为半径的圆上，\n由一箭穿心（三边关系）可知：\nOM 的最小值为 OO'－r'＝5－2＝3，\nOM 的最大值为 OO'＋r'＝5＋2＝7。","explanation":"瓜豆原理书写秘诀：不要只写“由瓜豆原理得”，必须用中位线或相似三角形把 O'M＝定值 证出来，阅卷稳拿满分。"},{"id":"kp-math-sp-p14-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p14-horse2.svg","type":"blank","stem":"如图，∠AOB＝30°，点 P 在角内且 OP＝6，M、N 分别是 OA、OB 上的动点，则 △PMN 周长的最小值是______。","blanks":[["6"]],"answer":["6"],"explanation":"∠P₁OP₂＝60°，等边三角形得 P₁P₂＝OP＝6。"},{"id":"kp-math-sp-p14-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p14-horse2.svg","type":"single","stem":"如图，∠AOB＝45°，OP＝4，M、N 分别在 OA、OB 上，则 △PMN 周长的最小值是（ ）","options":[{"key":"A","text":"4√3"},{"key":"B","text":"8"},{"key":"C","text":"4√2"},{"key":"D","text":"4"}],"answer":["C"],"explanation":"∠P₁OP₂＝90°，等腰 Rt△OP₁P₂ 斜边＝4√2。"},{"id":"kp-math-sp-p14-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（基础）","level":1,"kpFree":true,"type":"blank","stem":"在平面直角坐标系中，A(1, 2)、B(4, 2)，P 是 x 轴上动点，则 PA＋PB 的最小值是______。","blanks":[["5"]],"answer":["5"],"explanation":"A'(1, －2)，A'B＝√[(4－1)²＋(2－(－2))²]＝√(9＋16)＝5。"},{"id":"kp-math-sp-p14-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"在平面直角坐标系中，A(0, 3)、B(6, 5)，P 在 x 轴上，则 PA＋PB 的最小值是______。","blanks":[["10"]],"answer":["10"],"explanation":"A'(0, －3)，A'B＝√(6²＋8²)＝10。"},{"id":"kp-math-sp-p14-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（提高）","level":2,"kpFree":false,"type":"blank","stem":"在平面直角坐标系中，A(1, 1)、B(3, 5)，P 在 x 轴上使 |PB－PA| 最大，最大值等于 AB；若求 PA＋PB 最小值，A'(1, －1)，则 A'B²＝______。","blanks":[["40"]],"answer":["40"],"explanation":"(3－1)²＋(5－(－1))²＝4＋36＝40。"},{"id":"kp-math-sp-p14-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（提高）","level":2,"kpFree":false,"type":"blank","stem":"在边长为 4 的正方形 ABCD 中，E 在 AB 上且 BE＝3，P 是对角线 BD 上一动点，则 PA＋PE 的最小值是______。","blanks":[["5"]],"answer":["5"],"explanation":"A、C 关于 BD 对称，PA＋PE＝PC＋PE≥CE＝√(4²＋3²)＝5。"},{"id":"kp-math-sp-p14-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"等边三角形 ABC 边长为 6，AD 是高，E 在 AC 上且 AE＝2，P 是 AD 上一动点，则 PB＋PE 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"B、C 关于高 AD 对称，PB＋PE＝PC＋PE≥CE＝6－2＝4。"},{"id":"kp-math-sp-p14-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"∠AOB＝30°，OP＝8，M 在 OA 上、N 在 OB 上，当 △PMN 周长取最小值 8 时，∠MPN＝______°。","blanks":[["120"]],"answer":["120"],"explanation":"△OP₁P₂ 等边，∠P₁＝∠P₂＝60°，倒角得 ∠MPN＝180°－2×30°＝120°。"},{"id":"kp-math-sp-p14-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p14","kp":"将军饮马进阶（双动点与两定两动）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 将军饮马进阶（双动点与两定两动）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"将军饮马最值压轴","stem":"已知 ∠AOB＝30°，点 P 在 ∠AOB 内部，且 OP＝6，点 M、N 分别是射线 OA、OB 上的动点。求 △PMN 周长的最小值，并说明如何确定 M、N 的位置。","score":10,"points":[{"text":"分别作点 P 关于 OA、OB 的对称点 P₁、P₂，连接 P₁P₂ 交 OA 于 M、交 OB 于 N","score":3,"keys":["对称","P1","P₁","P2","P₂"]},{"text":"由轴对称性质得 PM＝P₁M、PN＝P₂N，故 △PMN 周长＝P₁M＋MN＋NP₂≥P₁P₂","score":3,"keys":["PM＝P₁M","两点之间线段最短","P₁P₂","P1P2"]},{"text":"证得 OP₁＝OP₂＝6、∠P₁OP₂＝2∠AOB＝60°，△OP₁P₂ 为等边三角形，最小周长为 6","score":4,"keys":["60°","等边","6"]}],"method":"① 角内一定点＋两边双动点求周长最小值→两次对称拉直折线；② 分别作 P 关于 OA、OB 的对称点 P₁、P₂，连 P₁P₂ 交 OA、OB 于 M、N；③ 证 OP₁＝OP₂＝6 且 ∠P₁OP₂＝2∠AOB＝60°，得等边 △OP₁P₂，立出最小周长。","sample":"解：分别作点 P 关于射线 OA、OB 的对称点 P₁、P₂，连接 P₁P₂，分别交 OA、OB 于点 M、N，此时 △PMN 周长最小。\n证明与计算：\n由轴对称性质得 PM＝P₁M，PN＝P₂N，OP₁＝OP＝6，OP₂＝OP＝6，\n∠P₁OA＝∠POA，∠P₂OB＝∠POB。\n因此 △PMN 的周长＝PM＋MN＋PN＝P₁M＋MN＋NP₂≥P₁P₂（两点之间线段最短，当 P₁、M、N、P₂ 共线时取等号）。\n又 ∠P₁OP₂＝∠P₁OA＋∠POA＋∠POB＋∠P₂OB＝2(∠POA＋∠POB)＝2∠AOB＝2×30°＝60°。\n因为 OP₁＝OP₂＝6 且 ∠P₁OP₂＝60°，所以 △OP₁P₂ 是等边三角形。\n故 P₁P₂＝6，即 △PMN 周长的最小值为 6。","explanation":"记住通式：若 ∠AOB＝α，OP＝d，则最小周长＝P₁P₂，α＝30° 时为 d，α＝45° 时为 √2 d，α＝60° 时为 √3 d。"},{"id":"kp-math-sp-p15-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p15-arrow.svg","type":"blank","stem":"如图，⊙O 半径为 3，点 P 在圆外且 OP＝8，Q 是圆上一动点，则 PQ 的最小值是______。","blanks":[["5"]],"answer":["5"],"explanation":"一箭穿心：OP－r＝8－3＝5。"},{"id":"kp-math-sp-p15-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p15-arrow.svg","type":"blank","stem":"如图，⊙O 半径为 3，OP＝8，则 PQ 的最大值是______。","blanks":[["11"]],"answer":["11"],"explanation":"OP＋r＝8＋3＝11。"},{"id":"kp-math-sp-p15-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（基础）","level":1,"kpFree":true,"type":"blank","stem":"点 P 在直线 y＝－3/4 x＋3 上运动，则原点 O 到点 P 的最小距离是______。","blanks":[["2.4","12/5"]],"answer":["2.4"],"explanation":"直线交坐标轴于 (4, 0) 和 (0, 3)，斜边 5，斜边高＝(3×4)÷5＝2.4。"},{"id":"kp-math-sp-p15-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"⊙O 半径为 2，圆心 O 到直线 l 的距离为 7，则 ⊙O 上任意一点到直线 l 的最小距离是______。","blanks":[["5"]],"answer":["5"],"explanation":"7－2＝5。"},{"id":"kp-math-sp-p15-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（提高）","level":2,"kpFree":false,"type":"blank","stem":"在 Rt△ABC 中，∠C＝90°，AC＝6，BC＝8，P 是斜边 AB 上一动点，作 PD⊥AC、PE⊥BC，则 DE 的最小值是______。","blanks":[["4.8","24/5"]],"answer":["4.8"],"explanation":"四边形 CDPE 是矩形，DE＝CP，CP 最小值为斜边高 4.8。"},{"id":"kp-math-sp-p15-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（提高）","level":2,"kpFree":false,"type":"blank","stem":"在平面直角坐标系中，⊙M 圆心 M(3, 4)，半径为 1，点 P 在 ⊙M 上运动，则 OP 的最大值是______。","blanks":[["6"]],"answer":["6"],"explanation":"OM＝√(3²＋4²)＝5，OP 最大＝5＋1＝6。"},{"id":"kp-math-sp-p15-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在平面直角坐标系中，⊙M 圆心 M(3, 4)，半径为 1，点 P 在 ⊙M 上运动，则 OP 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"OM－r＝5－1＝4。"},{"id":"kp-math-sp-p15-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"⊙O 半径为 5，点 P 在圆内且 OP＝3，过 P 的所有弦中，最短弦的长度是______。","blanks":[["8"]],"answer":["8"],"explanation":"垂直于 OP 的弦最短：半弦＝√(5²－3²)＝4，全弦长 8。"},{"id":"kp-math-sp-p15-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p15","kp":"垂线段最短与点圆最值（一箭穿心）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 垂线段最短与点圆最值（一箭穿心）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"点圆与垂线段最值","stem":"在平面直角坐标系中，⊙M 的圆心坐标为 M(3, 4)，半径 r＝2，点 P 是 ⊙M 上的动点。（1）求原点 O 到点 P 距离 OP 的最大值与最小值；（2）若点 Q 是 x 轴上的动点，求线段 PQ 长度的最小值。","score":10,"points":[{"text":"计算圆心距 OM＝√(3²＋4²)＝5","score":3,"keys":["5","OM＝5","OM=5"]},{"text":"由点圆最值得 OP 最小值为 5－2＝3，最大值为 5＋2＝7","score":4,"keys":["3","7"]},{"text":"过 M 作 MH⊥x 轴于 H，MH＝4＞r，故 PQ 最小值为 MH－r＝4－2＝2","score":3,"keys":["4","4－2＝2","2"]}],"method":"① 第一问先用两点距离公式算圆心距 OM＝5，再用“一箭穿心”得 OM±r；② 第二问“圆上动点到定直线最短距离”＝圆心到直线垂线段长 d 减去半径 r（先确认相离 d＞r）。","sample":"解：（1）连接 OM，在平面直角坐标系中，由 M(3, 4) 得 OM＝√(3²＋4²)＝5。\n因为 ⊙M 的半径 r＝2＜OM，原点 O 在圆外，\n所以当点 P 在线段 OM 上时，OP 最小＝OM－r＝5－2＝3；\n当点 P 在 OM 的延长线上时，OP 最大＝OM＋r＝5＋2＝7。\n（2）过圆心 M 作 MH⊥x 轴于点 H，则 MH＝4（即点 M 的纵坐标）。\n因为 MH＝4＞r＝2，所以 ⊙M 与 x 轴相离。\n由垂线段最短及一箭穿心可知，当 Q 与 H 重合且 P 在线段 MH 上时，PQ 取得最小值，\nPQmin＝MH－r＝4－2＝2。","explanation":"若圆与直线相交或相切（d≤r），圆上动点到直线的最小距离直接为 0，动笔前先比较 d 与 r 的大小。"},{"id":"kp-math-sp-p16-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p16-hbg.svg","type":"single","stem":"如图，动点 P 在直线 l 上，求 PA＋1/2 PB 的最小值时，需过 B 在 l 另一侧构造的辅助角是（ ）","options":[{"key":"A","text":"15°"},{"key":"B","text":"45°"},{"key":"C","text":"60°"},{"key":"D","text":"30°"}],"answer":["D"],"explanation":"sin 30°＝1/2，构造 30° 角把 1/2 PB 转化为垂线段 PH。"},{"id":"kp-math-sp-p16-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（基础）","level":1,"kpFree":true,"type":"single","stem":"动点 P 在直线 l 上，求 PA＋(√2/2)PB 的最小值时，应构造的辅助角是（ ）","options":[{"key":"A","text":"45°"},{"key":"B","text":"30°"},{"key":"C","text":"60°"},{"key":"D","text":"90°"}],"answer":["A"],"explanation":"sin 45°＝√2/2。"},{"id":"kp-math-sp-p16-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（基础）","level":1,"kpFree":true,"type":"single","stem":"动点 P 在直线 l 上，求 PA＋(√3/2)PB 的最小值时，应构造的辅助角是（ ）","options":[{"key":"A","text":"75°"},{"key":"B","text":"60°"},{"key":"C","text":"45°"},{"key":"D","text":"30°"}],"answer":["B"],"explanation":"sin 60°＝√3/2。"},{"id":"kp-math-sp-p16-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"在 Rt△ABC 中，∠C＝90°，AC＝3，BC＝4（AB＝5），P 是边 BC 上一动点，则 PC＋(3/5)PB 的最小值是______。","blanks":[["2.4","12/5"]],"answer":["2.4"],"explanation":"sin B＝3/5，过 P 作 PH⊥AB 于 H 得 PH＝(3/5)PB，故 PC＋PH 最小值为点 C 到 AB 的距离 (3×4)÷5＝2.4。"},{"id":"kp-math-sp-p16-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（提高）","level":2,"kpFree":false,"type":"single","stem":"若要求动点 P 在直线 l 上满足 2PA＋PB 的最小值，第一步变形正确的是（ ）","options":[{"key":"A","text":"直接构造 sin α＝2"},{"key":"B","text":"把 PB 放大 2 倍"},{"key":"C","text":"提取 2 转化为 2(PA＋1/2 PB)"},{"key":"D","text":"无法用胡不归"}],"answer":["C"],"explanation":"正弦值小于 1，提取 2 化为 2(PA＋1/2 PB) 再对 1/2 构造 30° 角。"},{"id":"kp-math-sp-p16-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（提高）","level":2,"kpFree":false,"type":"blank","stem":"在等腰直角三角形 ABC 中，∠C＝90°，AC＝BC＝2√2，P 是边 BC 上一动点，则 PC＋(√2/2)PB 的最小值是______。","blanks":[["2"]],"answer":["2"],"explanation":"∠B＝45°，作 PH⊥AB 于 H 得 PH＝(√2/2)PB，PC＋PH 最小值为 C 到 AB 的距离 2√2×(√2/2)＝2。"},{"id":"kp-math-sp-p16-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p16-hbg.svg","type":"blank","stem":"如图，在直线 l 上找动点 P 使 PA＋1/2 PB 最小，已知点 A 在直线 l 上方，且 AB＝10，AB 与直线 l 夹角为 60°（∠ABL＝60°），则 PA＋1/2 PB 的最小值是______。","blanks":[["10"]],"answer":["10"],"explanation":"在 l 下方作 30° 射线 BD，则 ∠ABD＝60°＋30°＝90°，故点 A 到射线 BD 的垂线段就是 AB＝10！"},{"id":"kp-math-sp-p16-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p16-hbg.svg","type":"blank","stem":"如图，在直线 l 上找动点 P 使 PA＋1/2 PB 最小，已知点 A 在 l 上方，AB＝8 且 ∠ABL＝30°（在 l 下方作 30° 射线 BD 得 ∠ABD＝60°），则 PA＋1/2 PB 最小值的平方是______。","blanks":[["48"]],"answer":["48"],"explanation":"距离 d＝8·sin 60°＝4√3，d²＝48。"},{"id":"kp-math-sp-p16-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p16","kp":"胡不归模型（PA＋k·PB）","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 胡不归模型（PA＋k·PB）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"胡不归最值压轴题","stem":"在平面直角坐标系中，点 A(0, 4)，点 B(6, 0)，动点 P 在线段 OB（x 轴正半轴）上运动，求 PA＋1/2 PB 的最小值。","score":12,"points":[{"text":"过 B 在 x 轴下方作射线 BD 使 ∠OBD＝30°，过 P 作 PH⊥BD 于 H，得 PH＝PB·sin 30°＝1/2 PB","score":4,"keys":["30°","sin","PH","1/2"]},{"text":"转化为 PA＋PH≥AE（AE⊥BD 于 E），并设射线 BD 交 y 轴负半轴于 C，算出 OC＝6·tan 30°＝2√3","score":4,"keys":["垂线段","OC","2√3"]},{"text":"由 AC＝4＋2√3 及 ∠ACE＝60°，算得 AE＝AC·sin 60°＝2√3＋3（且验证最优 P 落在线段 OB 上）","score":4,"keys":["4＋2√3","2√3＋3","3＋2√3","3+2√3"]}],"method":"① 动点 P 在直线上，系数 k＝1/2＜1 → 标准“胡不归”模型；② 在 x 轴下方过 B 作射线 BD 使 ∠OBD＝30°（sin 30°＝1/2），过 P 作 PH⊥BD 于 H，把 1/2 PB 转化为 PH；③ 原式化为 PA＋PH，过 A 作 AE⊥BD 即得最小值，利用射线 BD 与 y 轴交点 C 解含 30° 直角三角形计算 AE。","sample":"解：过点 B(6, 0) 在 x 轴下方作射线 BD，使 ∠OBD＝30°，交 y 轴负半轴于点 C。\n过点 P 作 PH⊥BD 于点 H，在 Rt△PBH 中，∠PBH＝30°，所以 PH＝PB·sin 30°＝1/2 PB。\n因此 PA＋1/2 PB＝PA＋PH。\n过点 A 作 AE⊥BD 于点 E，交线段 OB 于点 P₀，由“垂线段最短”知 PA＋PH≥AE，当 P 与 P₀ 重合时取等号。\n在 Rt△OBC 中，OB＝6，∠OBC＝30°，所以 OC＝OB·tan 30°＝6×(√3/3)＝2√3。\n故 AC＝OA＋OC＝4＋2√3。\n在 Rt△AEC 中，∠ACE＝90°－30°＝60°，\n所以 AE＝AC·sin 60°＝(4＋2√3)×(√3/2)＝2√3＋3。\n（检验：OP₀＝OA·tan 30°＝4√3/3≈2.31＜6，点 P₀ 确实在线段 OB 上。）\n所以 PA＋1/2 PB 的最小值为 2√3＋3。","explanation":"胡不归压轴题满分细节：算出垂线段后顺手检验一下“交点 P₀ 落在线段 OB 内”，能体现极高的严谨度。"},{"id":"kp-math-sp-p17-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（基础）","level":1,"kpFree":true,"type":"blank","stem":"矩形 ABCD 中 AB＝6，BC＝8，点 E 在 BC 上，将 △ABE 沿 AE 折叠得到 △AB'E，则 B'C 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"AB'＝6，AC＝10，B'C 最小＝10－6＝4。"},{"id":"kp-math-sp-p17-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（基础）","level":1,"kpFree":true,"type":"blank","stem":"正方形 ABCD 边长为 5，点 E 在 BC 上，将 △ABE 沿 AE 折叠得 △AB'E，若 B' 落在对角线 AC 上，则 B'A＝______。","blanks":[["5"]],"answer":["5"],"explanation":"折叠不改变线段长度，AB'＝AB＝5。"},{"id":"kp-math-sp-p17-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（基础）","level":1,"kpFree":true,"type":"blank","stem":"矩形 ABCD 中 AB＝3，BC＝4，点 E 在 BC 上，沿 AE 折叠 △ABE 得 △AB'E，则 B'C 的最小值是______。","blanks":[["2"]],"answer":["2"],"explanation":"AC＝5，AB'＝3，B'C 最小＝5－3＝2。"},{"id":"kp-math-sp-p17-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"Rt△ABC 中 ∠C＝90°，AC＝6，BC＝8，点 D 在 BC 上，将 △ACD 沿 AD 折叠得 △AC'D，则 BC' 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"AB＝10，AC'＝6，BC' 最小＝10－6＝4。"},{"id":"kp-math-sp-p17-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（提高）","level":2,"kpFree":false,"type":"blank","stem":"在 Rt△ABC 中，∠C＝90°，AC＝6，BC＝8，点 D 在射线 BC 上运动，将 △ACD 沿 AD 折叠得 △AC'D，则 BC' 的最大值是______。","blanks":[["16"]],"answer":["16"],"explanation":"AB＋AC'＝10＋6＝16。"},{"id":"kp-math-sp-p17-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（提高）","level":2,"kpFree":false,"type":"blank","stem":"矩形 ABCD 中 AB＝5，BC＝12，E 在 BC 上，沿 AE 折叠 △ABE 得 △AB'E，则 B'C 的最小值是______。","blanks":[["8"]],"answer":["8"],"explanation":"AC＝13，AB'＝5，B'C 最小＝13－5＝8。"},{"id":"kp-math-sp-p17-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（拓展）","level":3,"kpFree":false,"type":"blank","stem":"在 Rt△ABC 中 ∠C＝90°，AC＝3，BC＝4，D 在 AC 上，E 在 BC 上，沿 DE 折叠使 C 落在 AB 上的 C' 处，当 C' 是 AB 垂足（CC'⊥AB）时，CC' 的最小值是______。","blanks":[["2.4","12/5"]],"answer":["2.4"],"explanation":"C' 在 AB 上，CC' 最小即斜边高＝(3×4)÷5＝2.4。"},{"id":"kp-math-sp-p17-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（拓展）","level":3,"kpFree":false,"type":"blank","stem":"矩形 ABCD 中 AB＝6，BC＝8，点 Q 在 BC 边上，将 △CDQ 沿 DQ 折叠使点 C 落在 C' 处，则 BC' 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"DC'＝DC＝6，BD＝10，C' 在以 D 为圆心、6 为半径的圆上，BC' 最小＝10－6＝4。"},{"id":"kp-math-sp-p17-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p17","kp":"折叠与动点最值综合","unit":"专题·几何最值","chapter":"专题与压轴 · 几何最值压轴模型","source":"知识点精练 · 专题与压轴 · 折叠与动点最值综合（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"折叠隐圆综合压轴","stem":"在矩形 ABCD 中，AB＝6，BC＝8，点 E 是边 BC 上的动点，将 △ABE 沿 AE 折叠得到 △AB'E。（1）说明点 B' 的运动轨迹；（2）求线段 B'C 长度的最小值，并求 B'C 取最小值时 BE 的长。","score":12,"points":[{"text":"由折叠性质得 AB'＝AB＝6（定长），故点 B' 在以 A 为圆心、6 为半径的圆弧上运动","score":4,"keys":["AB'＝AB","6","圆弧","圆"]},{"text":"由勾股定理得 AC＝10，当 A、B'、C 三点共线时 B'C 最小＝10－6＝4","score":4,"keys":["AC＝10","共线","4"]},{"text":"设 BE＝B'E＝x，在 Rt△CB'E 中列方程 x²＋4²＝(8－x)²，解得 BE＝3","score":4,"keys":["8－x","x＝3","BE＝3","BE=3"]}],"method":"① 折叠必留“定长”：AB'＝AB＝6 且点 A 不动→点 B' 在以 A 为圆心、6 为半径的圆弧上；② 连接 AC＝10，由一箭穿心得 B'Cmin＝AC－AB'＝4（A、B'、C 共线时）；③ 此时 ∠CB'E＝90°，设 BE＝B'E＝x，在 Rt△CB'E 中列勾股方程秒解 x。","sample":"解：（1）由折叠的性质可知 AB'＝AB＝6（定值），且点 A 为定点，\n所以点 B' 的运动轨迹是以点 A 为圆心、6 为半径的一段圆弧。\n（2）连接 AC，在 Rt△ABC 中，AB＝6，BC＝8，所以 AC＝√(6²＋8²)＝10。\n因为 AB'＋B'C≥AC，所以 B'C≥AC－AB'＝10－6＝4，\n当 A、B'、C 三点共线（点 B' 落在线段 AC 上）时，B'C 取得最小值 4。\n此时由折叠知 ∠AB'E＝∠B＝90°，所以 ∠CB'E＝180°－90°＝90°。\n设 BE＝x，则 B'E＝BE＝x，CE＝8－x。\n在 Rt△CB'E 中，B'E²＋B'C²＝CE²，即 x²＋4²＝(8－x)²。\n展开得 x²＋16＝64－16x＋x²，解得 16x＝48，x＝3。\n故 B'C 的最小值为 4，此时 BE 的长为 3。","explanation":"折叠最值套路：找准不动点（圆心）和不变边（半径），先用一箭穿心求最值，再用折叠直角列勾股方程求折点位置。"},{"id":"kp-math-sp-p18-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p18-vheight.svg","type":"blank","stem":"如图，抛物线 y＝－x²＋2x＋3 与直线 BC：y＝－x＋3 交于 C(0, 3)、B(3, 0)，P(t, yP) 在第一象限抛物线上，PQ∥y 轴交 BC 于 Q，当 △PBC 面积最大时，t＝______。","blanks":[["1.5","3/2"]],"answer":["1.5"],"explanation":"PQ＝－t²＋3t，对称轴 t＝(0＋3)/2＝1.5。"},{"id":"kp-math-sp-p18-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（基础）","level":1,"kpFree":true,"type":"blank","stem":"抛物线 y＝－x²＋4x 交 x 轴于 O(0, 0)、B(4, 0)，P 在第一象限抛物线上，则 △POB 面积的最大值是______。","blanks":[["8"]],"answer":["8"],"explanation":"底 4，最大高 4（顶点 (2,4)），面积 1/2×4×4＝8。"},{"id":"kp-math-sp-p18-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（基础）","level":1,"kpFree":true,"type":"blank","stem":"抛物线 y＝－x²＋4 与直线 y＝－2x＋4 交于 A(0, 4)、B(2, 0)，P 在第一象限抛物线上，当 △PAB 面积最大时，点 P 的横坐标是______。","blanks":[["1"]],"answer":["1"],"explanation":"t＝(0＋2)/2＝1。"},{"id":"kp-math-sp-p18-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"抛物线 y＝－x²＋4 与直线 y＝－2x＋4 交于 A(0, 4)、B(2, 0)，P 在第一象限抛物线上，则 △PAB 面积的最大值是______。","blanks":[["1"]],"answer":["1"],"explanation":"PQ＝(－t²＋4)－(－2t＋4)＝－t²＋2t，t＝1 时 PQ 最大 1，水平宽 2，最大面积 1/2×1×2＝1。"},{"id":"kp-math-sp-p18-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（提高）","level":2,"kpFree":false,"type":"blank","stem":"抛物线 y＝x²－4x 与直线 y＝0 交于 O(0, 0)、A(4, 0)，P 在第四象限抛物线上，则 △POA 面积的最大值是______。","blanks":[["8"]],"answer":["8"],"explanation":"顶点 (2, －4)，最大高 4，面积 1/2×4×4＝8。"},{"id":"kp-math-sp-p18-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（提高）","level":2,"kpFree":false,"type":"blank","stem":"抛物线 y＝－1/2 x²＋2x＋6 交 x 轴正半轴于 B(6, 0)、交 y 轴于 C(0, 6)，直线 BC：y＝－x＋6。P 在第一象限抛物线上，则 PQ 最大值是______。","blanks":[["4.5","9/2"]],"answer":["4.5"],"explanation":"PQ＝－1/2 t²＋3t，t＝3 时最大＝－4.5＋9＝4.5。"},{"id":"kp-math-sp-p18-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（拓展）","level":3,"kpFree":false,"type":"blank","stem":"抛物线 y＝－1/2 x²＋2x＋6 交 x 轴正半轴于 B(6, 0)、交 y 轴于 C(0, 6)，P 在第一象限抛物线上，过 P 作 PQ∥y 轴交 BC 于 Q（PQ 最大值为 4.5），则 △PBC 的最大面积是______。","blanks":[["13.5","27/2"]],"answer":["13.5"],"explanation":"1/2×4.5×6＝13.5。"},{"id":"kp-math-sp-p18-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（拓展）","level":3,"kpFree":false,"image":"./assets/knowledge/math/sp/p18-vheight.svg","type":"blank","stem":"如图，抛物线 y＝－x²＋2x＋3 交 x 轴于 A(－1, 0)、B(3, 0)，交 y 轴于 C(0, 3)，则四边形 ABPC（P 在第一象限）面积最大值是______（填小数或分数）。","blanks":[["9.375","75/8"]],"answer":["9.375"],"explanation":"S△ABC＝1/2×4×3＝6，S△PBC 最大 27/8＝3.375，合计 6＋3.375＝9.375（75/8）。"},{"id":"kp-math-sp-p18-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p18","kp":"二次函数铅垂高面积最值","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数铅垂高面积最值（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"二次函数压轴综合","stem":"已知抛物线 y＝－x²＋2x＋3 与 x 轴交于 A、B 两点（A 在 B 左侧），与 y 轴交于点 C。（1）求 A、B、C 三点坐标及直线 BC 的解析式；（2）点 P 是第一象限抛物线上的动点，求 △PBC 面积的最大值及此时点 P 的坐标。","score":12,"points":[{"text":"求得 A(－1, 0)、B(3, 0)、C(0, 3) 及直线 BC：y＝－x＋3","score":4,"keys":["(-1,0)","(3,0)","(0,3)","y＝－x＋3","y=-x+3"]},{"text":"设 P(t, －t²＋2t＋3)(0＜t＜3)，作 PQ∥y 轴交 BC 于 Q(t, －t＋3)，得铅垂高 PQ＝－t²＋3t","score":4,"keys":["PQ","-t²+3t","－t²＋3t"]},{"text":"S△PBC＝1/2·PQ·OB＝－3/2(t－3/2)²＋27/8，当 t＝3/2 时最大面积为 27/8，P(3/2, 15/4)","score":4,"keys":["27/8","3/2","15/4"]}],"method":"① 令 y＝0、x＝0 分别求交点，再求直线 BC；② 斜三角形面积最值必用“铅垂高×水平宽÷2”：过 P(t, －t²＋2t＋3) 作 PQ∥y 轴交 BC 于 Q(t, －t＋3)；③ 写出 PQ＝yP－yQ 关于 t 的二次函数，配方求顶点即得最大面积与 P 坐标。","sample":"解：（1）令 y＝0，得 －x²＋2x＋3＝0，即 (x－3)(x＋1)＝0，解得 x₁＝－1，x₂＝3。\n因为 A 在 B 左侧，所以 A(－1, 0)，B(3, 0)。令 x＝0 得 C(0, 3)。\n设直线 BC 为 y＝kx＋3，代入 B(3, 0) 得 3k＋3＝0，k＝－1，故直线 BC：y＝－x＋3。\n（2）设点 P 的坐标为 (t, －t²＋2t＋3)（0＜t＜3），过点 P 作 PQ∥y 轴交线段 BC 于点 Q，则 Q(t, －t＋3)。\n所以铅垂高 PQ＝(－t²＋2t＋3)－(－t＋3)＝－t²＋3t。\n因为水平宽 OB＝3，所以 S△PBC＝1/2 × PQ × OB＝3/2(－t²＋3t)＝－3/2(t－3/2)²＋27/8。\n因为 －3/2＜0 且 0＜3/2＜3，所以当 t＝3/2 时，S△PBC 取得最大值 27/8。\n此时 yP＝－(3/2)²＋2×(3/2)＋3＝15/4，故 P(3/2, 15/4)。","explanation":"验算捷径：铅垂高最大时，点 P 的横坐标必等于 B、C 横坐标中点 (0＋3)/2＝3/2，用这个规律能 1 秒检查配方有没有算错！"},{"id":"kp-math-sp-p19-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（基础）","level":1,"kpFree":true,"type":"blank","stem":"已知 A(0, 0)、B(4, 0)，在直线 y＝2 上找点 P 使 △PAB 是直角三角形，满足条件的点 P 共有______个。","blanks":[["3"]],"answer":["3"],"explanation":"(0, 2)、(4, 2) 及圆切点 (2, 2)，共 3 个。"},{"id":"kp-math-sp-p19-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（基础）","level":1,"kpFree":true,"type":"blank","stem":"已知 A(0, 0)、B(6, 0)，在 y 轴正半轴上找点 P 使 △PAB 是等腰三角形（AB 为底或腰），满足条件的点 P 共有______个。","blanks":[["1"]],"answer":["1"],"explanation":"y 轴正半轴上点 P(0, y)：PA＝PB 需 x＝3 不在 y 轴；PB＝AB＝6 无解（OB＝6 已有直角边 6，斜边 PB＞6）；只有 PA＝AB＝6 得 P(0, 6)，共 1 个！"},{"id":"kp-math-sp-p19-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（基础）","level":1,"kpFree":true,"type":"blank","stem":"已知 A(0, 0)、B(3, 4)，点 P 在 x 轴正半轴上使 △OAB？即 △PAB 是以 AB 为腰、A 为顶点的等腰三角形（AP＝AB），则点 P 的横坐标是______。","blanks":[["5"]],"answer":["5"],"explanation":"AB＝5，AP＝5，x 轴正半轴上为 (5, 0)。"},{"id":"kp-math-sp-p19-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"已知 A(0, 0)、B(4, 0)，点 P(t, t²－4t) 在抛物线上，若 △PAB 是以 AB 为底的等腰三角形，则 t＝______。","blanks":[["2"]],"answer":["2"],"explanation":"PA＝PB ⇒ 点 P 在 AB 垂直平分线 x＝2 上，故 t＝2（P(2, －4) 不共线）。"},{"id":"kp-math-sp-p19-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（提高）","level":2,"kpFree":false,"type":"single","stem":"已知定点 A、B，找点 P 使 △PAB 是等腰三角形，经典的几何作图口诀是（ ）","options":[{"key":"A","text":"两线一圆"},{"key":"B","text":"两圆一线"},{"key":"C","text":"三圆"},{"key":"D","text":"三线"}],"answer":["B"],"explanation":"以 A、B 为圆心 AB 为半径画两圆，再画 AB 垂直平分线（一线），共“两圆一线”。"},{"id":"kp-math-sp-p19-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（提高）","level":2,"kpFree":false,"type":"blank","stem":"已知 A(0, 0)、B(6, 0)，点 P 在直线 y＝3 上，若 ∠APB＝90°，则点 P 的横坐标是______。","blanks":[["3"]],"answer":["3"],"explanation":"以 AB 为直径的圆圆心 (3, 0)、半径 3，与 y＝3 恰好相切于 (3, 3)，横坐标 3。"},{"id":"kp-math-sp-p19-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（拓展）","level":3,"kpFree":false,"type":"blank","stem":"抛物线 y＝x²－2x－3 交 x 轴于 A(－1, 0)、B(3, 0)，顶点 C(1, －4)，则 △ABC 是等腰三角形，它的腰长 AC 的平方是______。","blanks":[["20"]],"answer":["20"],"explanation":"AC²＝(1－(－1))²＋(－4－0)²＝4＋16＝20。"},{"id":"kp-math-sp-p19-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（拓展）","level":3,"kpFree":false,"type":"blank","stem":"已知 A(1, 0)、B(5, 0)，在直线 y＝3 上找点 P 使 △PAB 是直角三角形，共有______个点。","blanks":[["2"]],"answer":["2"],"explanation":"过 A 得 (1, 3)，过 B 得 (5, 3)；以 AB 为直径的圆半径 2＜3 与 y＝3 相离，故共 2 个点。"},{"id":"kp-math-sp-p19-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p19","kp":"二次函数中的等腰与直角三角形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的等腰与直角三角形存在性（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"二次函数存在性压轴","stem":"已知抛物线 y＝x²－2x－3 与 x 轴交于 A(－1, 0)、B(3, 0)，与 y 轴交于 C(0, －3)。在抛物线的对称轴上是否存在点 P，使 △PBC 为直角三角形？若存在，求出所有满足条件的点 P 坐标。","score":12,"points":[{"text":"求得对称轴 x＝1，设 P(1, m)，列出 BC²＝18、PB²＝m²＋4、PC²＝m²＋6m＋10","score":3,"keys":["x＝1","x=1","18","m²＋4","m²+4"]},{"text":"分 ∠B＝90°（BC²＋PB²＝PC²）得 m＝2，P₁(1, 2)；∠C＝90°（BC²＋PC²＝PB²）得 m＝－4，P₂(1, －4)","score":4,"keys":["(1, 2)","(1,2)","(1, -4)","(1, －4)"]},{"text":"分 ∠P＝90°（PB²＋PC²＝BC²）得 m²＋3m－2＝0，解得 P₃(1, (－3＋√17)/2)、P₄(1, (－3－√17)/2)，且均不与 B、C 共线","score":5,"keys":["√17","-3+√17","－3＋√17","不共线"]}],"method":"① 先求对称轴 x＝1，设动点 P(1, m)；② 写出三边平方 BC²、PB²、PC²；③ 按直角顶点分三类讨论（∠B＝90°、∠C＝90°、∠P＝90°），分别套勾股定理求解，最后检验三点不共线。","sample":"解：存在。抛物线 y＝x²－2x－3 的对称轴为直线 x＝－(－2)/2＝1。\n设点 P 的坐标为 (1, m)。由 B(3, 0)、C(0, －3)，由两点距离公式得：\nBC²＝(3－0)²＋(0＋3)²＝18；\nPB²＝(1－3)²＋m²＝m²＋4；\nPC²＝(1－0)²＋(m＋3)²＝m²＋6m＋10。\n分三种情况讨论：\n① 当 ∠CBP＝90° 时，BC²＋PB²＝PC²，即 18＋m²＋4＝m²＋6m＋10，解得 m＝2，得 P₁(1, 2)；\n② 当 ∠BCP＝90° 时，BC²＋PC²＝PB²，即 18＋m²＋6m＋10＝m²＋4，解得 m＝－4，得 P₂(1, －4)；\n③ 当 ∠BPC＝90° 时，PB²＋PC²＝BC²，即 (m²＋4)＋(m²＋6m＋10)＝18，化简得 m²＋3m－2＝0，\n解得 m＝(－3±√17)/2，得 P₃(1, (－3＋√17)/2)，P₄(1, (－3－√17)/2)。\n经检验，直线 BC 为 y＝x－3，与 x＝1 交于 (1, －2)，上述四点均不与 B、C 共线。\n综上，满足条件的点 P 共有 4 个：(1, 2)、(1, －4)、(1, (－3＋√17)/2)、(1, (－3－√17)/2)。","explanation":"存在性压轴题拿满分的关键：分类标签要清晰（①②③），用平方公式避免根号，最后补一句“均不共线”防漏扣。"},{"id":"kp-math-sp-p20-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p20-paraex.svg","type":"blank","stem":"如图，平行四边形 ABCD（按字母顺序）中，A(0, 2)、B(2, 0)、C(5, 2)，则点 D(x, y) 满足 x＋y＝______。","blanks":[["7"]],"answer":["7"],"explanation":"A＋C＝B＋D ⇒ D＝(0＋5－2, 2＋2－0)＝(3, 4)，x＋y＝7。"},{"id":"kp-math-sp-p20-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（基础）","level":1,"kpFree":true,"type":"single","stem":"平面内有不在同一直线上的三点 A、B、C，以 A、B、C、D 为顶点可以画出的平行四边形共有（ ）","options":[{"key":"A","text":"3 个"},{"key":"B","text":"1 个"},{"key":"C","text":"2 个"},{"key":"D","text":"4 个"}],"answer":["A"],"explanation":"分别以 AB、BC、AC 为对角线，共 3 个。"},{"id":"kp-math-sp-p20-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（基础）","level":1,"kpFree":true,"type":"blank","stem":"已知 A(1, 2)、B(4, 2)、C(2, 5)，若以 AB 为对角线构成平行四边形 ACBD，则点 D(x, y) 满足 x＋y＝______。","blanks":[["2"]],"answer":["2"],"explanation":"D＝A＋B－C＝(1＋4－2, 2＋2－5)＝(3, －1)，x＋y＝2。"},{"id":"kp-math-sp-p20-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"抛物线 y＝x²－2x－3 交 y 轴于 C(0, －3)，对称轴为 x＝1。点 M 在对称轴上，点 N 在 x 轴上，若以 O(0,0)、C(0,－3)、M、N 为顶点的平行四边形以 OC 为边，则 |yM|＝______。","blanks":[["3"]],"answer":["3"],"explanation":"MN∥OC 且 MN＝OC＝3，因 N 在 x 轴（yN＝0），故 |yM|＝3。"},{"id":"kp-math-sp-p20-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（提高）","level":2,"kpFree":false,"type":"blank","stem":"已知 A(0, 3)、B(3, 0)，点 P 在 x 轴上、Q 在抛物线 y＝－x²＋2x＋3 上，若以 A、B、P、Q 为顶点且 AB 为对角线，则点 Q 的纵坐标是______。","blanks":[["3"]],"answer":["3"],"explanation":"yP＋yQ＝yA＋yB＝3＋0＝3，因 P 在 x 轴（yP＝0），故 yQ＝3。"},{"id":"kp-math-sp-p20-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（提高）","level":2,"kpFree":false,"type":"blank","stem":"抛物线 y＝－x²＋2x＋3 交 y 轴于 A(0, 3)，点 Q 在该抛物线上且 yQ＝3（Q 与 A 不重合），则点 Q 的横坐标是______。","blanks":[["2"]],"answer":["2"],"explanation":"－x²＋2x＋3＝3 ⇒ x＝0（舍去，与 A 重合）或 x＝2，故横坐标 2。"},{"id":"kp-math-sp-p20-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（拓展）","level":3,"kpFree":false,"type":"blank","stem":"已知 A(1, 3)、B(4, 1)，点 P 在直线 x＝5 上且纵坐标为 2，点 Q 在 y 轴上，若以 AB 为对角线构成平行四边形 APBQ，则点 Q 的纵坐标是______。","blanks":[["2"]],"answer":["2"],"explanation":"yA＋yB＝3＋1＝4，yP＋yQ＝4 ⇒ yQ＝4－2＝2。"},{"id":"kp-math-sp-p20-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（拓展）","level":3,"kpFree":false,"type":"blank","stem":"已知 A(0, 0)、B(4, 0)、C(1, 3)，以 A、B、C、D 为顶点作平行四边形，三个可能的点 D 的横坐标之和是______。","blanks":[["5"]],"answer":["5"],"explanation":"三个横坐标分别为 (0＋4－1)＝3、(0＋1－4)＝－3、(4＋1－0)＝5，和为 3＋(－3)＋5＝5（恒等于 xA＋xB＋xC！）。"},{"id":"kp-math-sp-p20-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p20","kp":"二次函数中的平行四边形存在性","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 二次函数中的平行四边形存在性（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"二次函数平行四边形","stem":"已知抛物线 y＝x²－4x＋3 与 x 轴交于 A(1, 0)、B(3, 0)，与 y 轴交于 C(0, 3)。（1）若点 D 在平面内，使以 A、B、C、D 为顶点的四边形是平行四边形，求所有点 D 的坐标；（2）若点 M 在抛物线上、点 N 在 x 轴上，且以 B、C、M、N 为顶点的四边形是平行四边形，求点 M 的坐标。","score":12,"points":[{"text":"（1）分 AB、AC、BC 为对角线三类，由中点公式求得 D₁(4, －3)、D₂(－2, 3)、D₃(2, 3)","score":6,"keys":["(4,-3)","(4, －3)","(-2,3)","(－2, 3)","(2,3)","(2, 3)"]},{"text":"（2）利用纵坐标和相等分类：BC 为边或对角线均要求 yM＝3 或 yM＝－3","score":3,"keys":["yM＝3","yM=3","yM＝－3","纵坐标"]},{"text":"代 y＝3 得 x²－4x＝0 ⇒ x＝4（x＝0 与 C 重合舍去），代 y＝－3 得 Δ＜0 无解，故 M(4, 3)","score":3,"keys":["M(4,3)","(4, 3)","舍去","无解"]}],"method":"① 第一问无字母顺序限制，直接按“对角线互相平分（相对顶点坐标和相等）”分三类：D＝A＋B－C、A＋C－B、B＋C－A；② 第二问点 B、N 都在 x 轴上（纵坐标为 0），根据相对顶点纵坐标之和相等，直接推出 yM＝±yC＝±3，代入抛物线秒解点 M！","sample":"解：（1）以 A(1, 0)、B(3, 0)、C(0, 3)、D 为顶点的平行四边形，由对角线互相平分（相对顶点坐标和相等）分三类：\n① AB 为对角线：D₁＝A＋B－C＝(1＋3－0, 0＋0－3)＝(4, －3)；\n② AC 为对角线：D₂＝A＋C－B＝(1＋0－3, 0＋3－0)＝(－2, 3)；\n③ BC 为对角线：D₃＝B＋C－A＝(3＋0－1, 0＋3－0)＝(2, 3)。\n（2）因为 B(3, 0)、N(n, 0) 均在 x 轴上，纵坐标均为 0，C(0, 3)，设 M(x, x²－4x＋3)。\n① 若 BC 或 BM 为对角线：yM＋0＝3＋0 ⇒ yM＝3，即 x²－4x＋3＝3，解得 x＝0（与 C 重合，舍去）或 x＝4，得 M(4, 3)；\n② 若 CM 为对角线：yC＋yM＝yB＋yN＝0 ⇒ yM＝－3，即 x²－4x＋3＝－3，x²－4x＋6＝0，Δ＝16－24＝－8＜0，无实数解。\n综上，满足条件的点 M 坐标为 (4, 3)。","explanation":"易错防雷：① x＝0 算出点 (0, 3) 与已知点 C 重合，必须明确写出“舍去”；② 碰到无解分支要写清判别式 Δ＜0，才算分类讨论完整。"},{"id":"kp-math-sp-p21-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p21-segint.svg","type":"single","stem":"如图，抛物线 y＝(x－1)²＋m 与线段 AB（A(0, 2)、B(3, 2)）有公共点，则 m 的取值范围是（ ）","options":[{"key":"A","text":"－2≤m≤2"},{"key":"B","text":"－2＜m＜2"},{"key":"C","text":"1≤m≤2"},{"key":"D","text":"m≤2"}],"answer":["A"],"explanation":"最高顶点触及 y＝2 得 m＝2；最低过最远端点 B(3, 2) 得 4＋m＝2 ⇒ m＝－2，故 －2≤m≤2。"},{"id":"kp-math-sp-p21-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（基础）","level":1,"kpFree":true,"image":"./assets/knowledge/math/sp/p21-segint.svg","type":"single","stem":"如图，抛物线 y＝(x－1)²＋m 与线段 AB（A(0, 2)、B(3, 2)）恰有 2 个公共点，则 m 的取值范围是（ ）","options":[{"key":"A","text":"－2≤m＜2"},{"key":"B","text":"1≤m＜2"},{"key":"C","text":"1＜m＜2"},{"key":"D","text":"－2＜m＜1"}],"answer":["B"],"explanation":"过 A(0, 2) 时 1＋m＝2 ⇒ m＝1（此时交 A(0,2) 和 (2,2) 共 2 个点）；m＝2 时只有 1 个顶点，故 1≤m＜2。"},{"id":"kp-math-sp-p21-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（基础）","level":1,"kpFree":true,"type":"blank","stem":"抛物线 y＝x²＋c 与线段 AB（A(－1, 2)、B(2, 2)）有公共点，则 c 的最大值是______。","blanks":[["2"]],"answer":["2"],"explanation":"顶点 (0, c) 恰好落在线段 AB 上时 c 最大，为 2。"},{"id":"kp-math-sp-p21-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"抛物线 y＝x²＋c 与线段 AB（A(－1, 2)、B(2, 2)）有公共点，则 c 的最小值是______。","blanks":[["-2","－2"]],"answer":["-2"],"explanation":"过最远端点 B(2, 2) 时 4＋c＝2 ⇒ c＝－2。"},{"id":"kp-math-sp-p21-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（提高）","level":2,"kpFree":false,"type":"blank","stem":"抛物线 y＝ax²（a＞0）经过线段 AB（A(1, 4)、B(2, 4)）上的点，则 a 的最小值是______。","blanks":[["1"]],"answer":["1"],"explanation":"开口最宽时过 B(2, 4)：4a＝4 ⇒ a＝1。"},{"id":"kp-math-sp-p21-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（提高）","level":2,"kpFree":false,"type":"blank","stem":"抛物线 y＝ax²（a＞0）经过线段 AB（A(1, 4)、B(2, 4)）上的点，则 a 的最大值是______。","blanks":[["4"]],"answer":["4"],"explanation":"开口最窄时过 A(1, 4)：a＝4。"},{"id":"kp-math-sp-p21-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（拓展）","level":3,"kpFree":false,"type":"blank","stem":"抛物线 y＝(x－h)² 顶点在 x 轴上左右平移，若它与线段 AB（A(0, 1)、B(4, 1)）恰有 1 个公共点且 h＞4，则 h 的最大值是______。","blanks":[["5"]],"answer":["5"],"explanation":"抛物线右移至左支刚好经过 B(4, 1)：(4－h)²＝1 且 h＞4 ⇒ h＝5。"},{"id":"kp-math-sp-p21-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（拓展）","level":3,"kpFree":false,"type":"blank","stem":"抛物线 y＝－(x－1)²＋k 与线段 AB（A(0, 1)、B(3, 1)）有公共点，则 k 的最小值是______。","blanks":[["1"]],"answer":["1"],"explanation":"开口向下，顶点 (1, k) 最低触及 y＝1，故 k 最小为 1。"},{"id":"kp-math-sp-p21-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p21","kp":"抛物线与线段交点含参临界问题","unit":"专题·二次函数压轴","chapter":"专题与压轴 · 二次函数压轴综合","source":"知识点精练 · 专题与压轴 · 抛物线与线段交点含参临界问题（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"二次函数含参临界","stem":"已知抛物线 y＝x²－2x＋m（m 为常数）与水平线段 AB（端点 A(0, 2)、B(3, 2)）有公共点。（1）求 m 的取值范围；（2）若抛物线与线段 AB 恰有 1 个公共点，求 m 的取值范围。","score":12,"points":[{"text":"配方得 y＝(x－1)²＋m－1，对称轴 x＝1 在 0～3 之间，顶点最低触及 AB 时 m－1＝2 ⇒ m＝3","score":4,"keys":["(x-1)²","(x－1)²","m＝3","m=3"]},{"text":"代入远端点 B(3, 2) 得 9－6＋m＝2 ⇒ m＝－1，故有公共点时 －1≤m≤3","score":4,"keys":["m＝－1","m=-1","-1≤m≤3","－1≤m≤3"]},{"text":"代入近端点 A(0, 2) 得 m＝2（此时恰 2 交点），故恰有 1 个公共点时 －1≤m＜2 或 m＝3","score":4,"keys":["m＝2","m=2","-1≤m<2","－1≤m＜2","m＝3"]}],"method":"① 先配方找顶点 (1, m－1) 与对称轴 x＝1（恰好在 0 和 3 之间）；② 画草图找 3 个临界位置：顶点触及线段 y＝2、经过近端点 A(0, 2)、经过远端点 B(3, 2)；③ 逐一验证端点处的等号能否取到（区间端点的开闭最易丢分！）。","sample":"解：将抛物线配方得 y＝(x－1)²＋m－1，开口向上，对称轴为 x＝1，顶点为 (1, m－1)。\n（1）因为对称轴 x＝1 在线段 AB（0≤x≤3，y＝2）的横坐标范围内，抛物线上下平移时：\n当顶点刚好落在线段 AB 上时，m－1＝2，解得 m＝3（最高临界）；\n因为点 B(3, 2) 离对称轴 x＝1 比点 A(0, 2) 更远，当抛物线刚好经过点 B(3, 2) 时，3²－2×3＋m＝2，解得 m＝－1（最低临界）。\n所以抛物线与线段 AB 有公共点时，m 的取值范围是 －1≤m≤3。\n（2）当抛物线经过近端点 A(0, 2) 时，0－0＋m＝2，得 m＝2，此时抛物线同时过 (0, 2) 和 (2, 2)，与线段 AB 有 2 个公共点。\n当 2≤m＜3 时，抛物线与线段 AB 有 2 个公共点；\n当 －1≤m＜2 时，左交点横坐标小于 0（在线段外），右交点落在线段上，恰有 1 个公共点；\n当 m＝3 时，顶点 (1, 2) 落在线段上，也恰有 1 个公共点。\n综上，恰有 1 个公共点时，－1≤m＜2 或 m＝3。","explanation":"含参临界题头号易错点：第二问漏掉孤立点 m＝3，或把 m＜2 误写成 m≤2！记住考场上把边界值代回去数交点个数，100% 不丢分。"},{"id":"kp-math-sp-p22-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（基础）","level":1,"kpFree":true,"type":"blank","stem":"无论 x、y 取何实数，代数式 (x－2)²＋(y＋3)²＋5 的最小值是______。","blanks":[["5"]],"answer":["5"],"explanation":"两平方项均≥0，最小值为 5。"},{"id":"kp-math-sp-p22-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（基础）","level":1,"kpFree":true,"type":"blank","stem":"已知 a²＋2a＝3，则 2a²＋4a－5＝______。","blanks":[["1"]],"answer":["1"],"explanation":"2(a²＋2a)－5＝6－5＝1。"},{"id":"kp-math-sp-p22-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（基础）","level":1,"kpFree":true,"type":"blank","stem":"代数式 x²－6x＋13 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"(x－3)²＋4≥4，最小值为 4。"},{"id":"kp-math-sp-p22-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"代数式 x²＋y²－4x＋2y＋9 的最小值是______。","blanks":[["4"]],"answer":["4"],"explanation":"(x－2)²＋(y＋1)²＋4≥4，最小值为 4。"},{"id":"kp-math-sp-p22-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（提高）","level":2,"kpFree":false,"type":"blank","stem":"已知 x²－3x－1＝0，则 x³－4x²＋2x＋5＝______。","blanks":[["4"]],"answer":["4"],"explanation":"x²＝3x＋1，原式＝x(3x＋1)－4x²＋2x＋5＝－(x²－3x)＋5＝－1＋5＝4。"},{"id":"kp-math-sp-p22-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（提高）","level":2,"kpFree":false,"type":"blank","stem":"已知 x＋y＝6，则 xy 的最大值是______。","blanks":[["9"]],"answer":["9"],"explanation":"xy＝x(6－x)＝－(x－3)²＋9≤9，最大值为 9。"},{"id":"kp-math-sp-p22-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（拓展）","level":3,"kpFree":false,"type":"blank","stem":"已知实数 x 满足 x＋1/x＝3，则 x²＋1/x²＋2(x＋1/x)＝______。","blanks":[["13"]],"answer":["13"],"explanation":"x²＋1/x²＝9－2＝7，7＋2×3＝13。"},{"id":"kp-math-sp-p22-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（拓展）","level":3,"kpFree":false,"type":"blank","stem":"代数式 12/(x²－2x＋4) 的最大值是______。","blanks":[["4"]],"answer":["4"],"explanation":"分母＝(x－1)²＋3≥3，分母最小时分式最大：12÷3＝4。"},{"id":"kp-math-sp-p22-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p22","kp":"整体代入与配方法求最值","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 整体代入与配方法求最值（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"降次整体代入与配方法压轴大题","stem":"解答下列代数求值与最值问题：（1）已知实数 x 满足 x²－2x－5＝0，求代数式 x³－x²－7x＋9 的值；（2）已知 M＝x²＋2y²－2xy＋4y＋10（x、y 为实数），利用配方法求 M 的最小值，并写出 M 取最小值时 x、y 的值。","score":10,"points":[{"text":"由条件写出降次关系 x²＝2x＋5，将 x³ 替换为 x(2x＋5) 化简得 x²－2x＋9","score":3,"keys":["x²＝2x＋5","x²－2x＋9"]},{"text":"再次整体代入 x²－2x＝5，算得第（1）问结果为 14","score":2,"keys":["5＋9","14"]},{"text":"拆项并配方得 M＝(x－y)²＋(y＋2)²＋6","score":3,"keys":["(x－y)²","(y＋2)²＋6"]},{"text":"利用平方非负性得出 M 最小值为 6，并求出取等条件 x＝－2、y＝－2","score":2,"keys":["最小值为 6","x＝－2","y＝－2"]}],"method":"① 第（1）问不要硬解无理根，把条件改写为降次公式 x²＝2x＋5，反复将高次项 x³ 降为 x·x² 消去高次；② 降到二次后再整体代入 x²－2x＝5 即可秒出结果；③ 第（2）问含交叉项 －2xy，先把 2y² 拆成 y²＋y²，分别与 x²－2xy 和 4y 配成两个完全平方式；④ 利用平方非负性得出最小值及取等条件。","sample":"解：（1）由 x²－2x－5＝0，得 x²＝2x＋5，且 x²－2x＝5。\n原式＝x·x²－x²－7x＋9\n＝x(2x＋5)－x²－7x＋9\n＝2x²＋5x－x²－7x＋9\n＝x²－2x＋9\n＝5＋9＝14。\n（2）M＝(x²－2xy＋y²)＋(y²＋4y＋4)＋6\n＝(x－y)²＋(y＋2)²＋6。\n因为 x、y 为实数，所以 (x－y)²≥0，(y＋2)²≥0，\n故 M≥6。\n当且仅当 x－y＝0 且 y＋2＝0，即 x＝－2，y＝－2 时等号成立，\n所以 M 的最小值为 6，此时 x＝－2，y＝－2。","explanation":"阅卷易错红线：① 第（1）问用求根公式硬算 x＝1±√6 导致计算繁琐出错；② 第（2）问不会拆分 2y² 而无法消去交叉项 －2xy；③ 求出最小值为 6 后漏写取最小值时的 x、y 值。"},{"id":"kp-math-sp-p23-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（基础）","level":1,"kpFree":true,"type":"blank","stem":"关于 x 的方程 (m－1)x＝6 的解是正整数，则满足条件的整数 m 共有______个。","blanks":[["4"]],"answer":["4"],"explanation":"m－1∈{1, 2, 3, 6}，m∈{2, 3, 4, 7}，共 4 个。"},{"id":"kp-math-sp-p23-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（基础）","level":1,"kpFree":true,"type":"blank","stem":"若关于 x 的不等式组 x＞a 与 x≤3 恰有 2 个整数解，且 a 为整数，则 a＝______。","blanks":[["1"]],"answer":["1"],"explanation":"整数解为 2、3，故 1≤a＜2，整数 a＝1。"},{"id":"kp-math-sp-p23-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（基础）","level":1,"kpFree":true,"type":"single","stem":"关于 x 的方程 ax＝b 无解的条件是（ ）","options":[{"key":"A","text":"a＝0，b＝0"},{"key":"B","text":"a≠0，b＝0"},{"key":"C","text":"a≠0，b≠0"},{"key":"D","text":"a＝0，b≠0"}],"answer":["D"],"explanation":"0·x＝非零常数时方程无解。"},{"id":"kp-math-sp-p23-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"single","stem":"若关于 x 的分式方程 m/(x－1)＝2 的解是正数，则 m 的取值范围是（ ）","options":[{"key":"A","text":"m＞－2 且 m≠0"},{"key":"B","text":"m＞－2"},{"key":"C","text":"m＞0"},{"key":"D","text":"m≥－2"}],"answer":["A"],"explanation":"x＝(m＋2)/2＞0 得 m＞－2，又增根 x≠1 得 m≠0。坑点：漏排除增根 m＝0！"},{"id":"kp-math-sp-p23-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（提高）","level":2,"kpFree":false,"type":"blank","stem":"方程组 2x＋y＝k＋1 与 x＋2y＝2k－4 的解满足 x＋y＝3，则 k＝______。","blanks":[["4"]],"answer":["4"],"explanation":"两式相加 3(x＋y)＝3k－3 ⇒ 9＝3k－3 ⇒ k＝4。"},{"id":"kp-math-sp-p23-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（提高）","level":2,"kpFree":false,"type":"blank","stem":"若关于 x 的方程 (k－2)x²－2x＋1＝0 有两个实数根，则满足条件的最大整数 k＝______。","blanks":[["3"]],"answer":["3"],"explanation":"Δ＝4－4(k－2)≥0 得 k≤3，且 k≠2，最大整数 3。"},{"id":"kp-math-sp-p23-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"若不等式 ax＋2＞0 对 0≤x≤2 上一切 x 都成立，则整数 a 的最小值是______。","blanks":[["0"]],"answer":["0"],"explanation":"端点 x＝0 得 2＞0，x＝2 得 2a＋2＞0 ⇒ a＞－1，最小整数 a＝0。"},{"id":"kp-math-sp-p23-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（拓展）","level":3,"kpFree":false,"type":"blank","stem":"若关于 x 的分式方程 (x＋a)/(x－2)＝2 的解为非负数，则整数 a 的最小值是______。","blanks":[["-4","－4"]],"answer":["-4"],"explanation":"去分母得 x＋a＝2x－4 ⇒ x＝a＋4≥0 得 a≥－4，且增根 x≠2 得 a≠－2，最小整数为 －4。"},{"id":"kp-math-sp-p23-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p23","kp":"含参方程与不等式（主元法与分类讨论）","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 含参方程与不等式（主元法与分类讨论）（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"含参分式方程与不等式综合压轴","stem":"已知关于 x 的分式方程 (x＋m)/(x－2) ＋ 2m/(2－x) ＝ 3。（1）若该分式方程的解为正数，求实数 m 的取值范围；（2）若关于 y 的不等式组 { y－2m ＞ －3；3y－2 ≤ 7 } 有解，且 m 同时满足（1）的条件，求满足条件的最大整数 m。","score":10,"points":[{"text":"正确解分式方程并用参数表示：x＝(6－m)/2","score":3,"keys":["x－m＝3x－6","(6－m)/2"]},{"text":"由 x＞0 且 x≠2，得出 m＜6 且 m≠2","score":3,"keys":["m＜6","m≠2"]},{"text":"解不等式组得 2m－3＜y≤3，由有解得 2m－3＜3，即 m＜3","score":2,"keys":["y＞2m－3","y≤3","m＜3"]},{"text":"综合 m＜3 且 m≠2，剔除增根值 m＝2，求得最大整数 m＝1","score":2,"keys":["m＜3 且 m≠2","m＝1"]}],"method":"① 先把分式方程化同分母去分母，用含 m 的式子表示出未知数 x；② “解为正数”包含双重要求：x＞0 且不能为增根（x≠2），由此列出关于 m 的双限制；③ 解关于 y 的不等式组，由“有解”即下界小于上界（注意临界等号能否取到）求 m 的范围；④ 取两部分范围的交集，特别注意避开增根对应的参数禁值，再找最大整数。","sample":"解：（1）原方程可化为 (x＋m)/(x－2)－2m/(x－2)＝3，\n方程两边同乘 (x－2)，得 x＋m－2m＝3(x－2)，\n即 x－m＝3x－6，解得 x＝(6－m)/2。\n因为原方程的解为正数，所以 (6－m)/2＞0，解得 m＜6。\n又因为 x－2≠0，即 (6－m)/2≠2，解得 m≠2。\n综上，m 的取值范围是 m＜6 且 m≠2。\n（2）解不等式 y－2m＞－3，得 y＞2m－3；\n解不等式 3y－2≤7，得 y≤3。\n因为不等式组有解，所以 2m－3＜3，解得 m＜3。\n结合（1）的条件得 m＜3 且 m≠2，\n故满足条件的最大整数 m＝1。","explanation":"阅卷易错红线：① 第（1）问漏掉 x≠2 导致丢掉 m≠2，进而第（2）问错答最大整数 m＝2（最致命坑点）；② 由 2m－3＜y≤3 有解错写成 2m－3≤3（当 2m－3＝3 时，y＞3 且 y≤3 无解）。"},{"id":"kp-math-sp-p24-01","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（基础）","level":1,"kpFree":true,"type":"blank","stem":"定义新运算 a⊕b＝a²－ab，若 3⊕x＝6，则 x＝______。","blanks":[["1"]],"answer":["1"],"explanation":"9－3x＝6，x＝1。"},{"id":"kp-math-sp-p24-02","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（基础）","level":1,"kpFree":true,"type":"blank","stem":"观察数列 2、5、10、17、26、……，第 7 个数是______。","blanks":[["50"]],"answer":["50"],"explanation":"第 n 项为 n²＋1，第 7 项 7²＋1＝50。"},{"id":"kp-math-sp-p24-03","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（基础）","level":1,"kpFree":true,"type":"blank","stem":"一列数按 1、3、5、7、1、3、5、7、……循环排列，第 2026 个数是______。","blanks":[["3"]],"answer":["3"],"explanation":"周期为 4，2026＝4×506＋2，余 2 对应第 2 个数 3。"},{"id":"kp-math-sp-p24-04","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（提高）","level":2,"kpFree":true,"kpDiag":true,"type":"blank","stem":"用 [x] 表示不超过 x 的最大整数（如 [3.7]＝3，[－1.2]＝－2），则 [√10]＋[－2.3]＝______。","blanks":[["0"]],"answer":["0"],"explanation":"[√10]＝3，[－2.3]＝－3，和为 0。坑点：把 [－2.3] 算成 －2。"},{"id":"kp-math-sp-p24-05","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（提高）","level":2,"kpFree":false,"type":"blank","stem":"裂项计算：1/(1×2)＋1/(2×3)＋1/(3×4)＋…＋1/(9×10)＝______（填小数或最简分数）。","blanks":[["0.9","9/10"]],"answer":["0.9"],"explanation":"(1－1/2)＋(1/2－1/3)＋…＋(1/9－1/10)＝1－1/10＝9/10。"},{"id":"kp-math-sp-p24-06","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（提高）","level":2,"kpFree":false,"type":"blank","stem":"我们称坐标满足 x＋y＝0 的点为“平衡点”。若直线 y＝2x－6 上有一点 P 是“平衡点”，则点 P 的横坐标是______。","blanks":[["2"]],"answer":["2"],"explanation":"x＋(2x－6)＝0 ⇒ 3x＝6 ⇒ x＝2。"},{"id":"kp-math-sp-p24-07","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（拓展）","level":3,"kpFree":false,"type":"blank","stem":"定义：如果一元二次方程 ax²＋bx＋c＝0（a≠0）满足 a－b＋c＝0，称其为“友好方程”。已知 2x²＋kx－3＝0 是“友好方程”，则 k＝______。","blanks":[["-1","－1"]],"answer":["-1"],"explanation":"2－k－3＝0 ⇒ k＝－1。"},{"id":"kp-math-sp-p24-08","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（拓展）","level":3,"kpFree":false,"type":"blank","stem":"定义两点 P(x₁, y₁)、Q(x₂, y₂) 的“折线距离”为 |x₁－x₂|＋|y₁－y₂|。已知 A(1, 2)、B(4, 6)，则 A、B 的折线距离是______。","blanks":[["7"]],"answer":["7"],"explanation":"|1－4|＋|2－6|＝3＋4＝7。"},{"id":"kp-math-sp-p24-09","subject":"math","subjectLabel":"数学","knowledge":true,"kpId":"math-sp-p24","kp":"中考新定义与规律压轴题","unit":"专题·代数与新定义","chapter":"专题与压轴 · 代数压轴与中考新定义","source":"知识点精练 · 专题与压轴 · 中考新定义与规律压轴题（压轴解答）","level":3,"kpFree":false,"type":"essay","meta":"中考新定义压轴题","stem":"对任意实数 a、b，定义新运算：a⊕b＝a²－ab＋b。（1）计算 3⊕(－2) 的值；（2）若关于 x 的方程 x⊕(2x－1)＝k 有两个不相等的实数根，求实数 k 的取值范围；（3）当 a＝2 时，若 a⊕b＝b⊕a，求 b 的值。","score":12,"points":[{"text":"（1）3⊕(－2)＝3²－3×(－2)＋(－2)＝9＋6－2＝13","score":3,"keys":["13"]},{"text":"（2）翻译得 x²－x(2x－1)＋(2x－1)＝k ⇒ x²－3x＋(k＋1)＝0，由 Δ＝9－4(k＋1)＞0 解得 k＜5/4","score":5,"keys":["x²-3x","x²－3x","5/4","k＜5/4","k<5/4"]},{"text":"（3）2⊕b＝4－b，b⊕2＝b²－2b＋2，列方程 b²－b－2＝0，解得 b₁＝2，b₂＝－1","score":4,"keys":["b²-b-2","b²－b－2","2","-1","－1"]}],"method":"① 读新定义题只做一件事：严格按位置把 a、b 整体套进括号里翻译成普通代数式；② 第二问翻译后整理成一元二次方程标准形式，用 Δ＞0 求 k；③ 第三问分别展开 2⊕b 和 b⊕2，解一元二次方程注意别漏解。","sample":"解：（1）3⊕(－2)＝3²－3×(－2)＋(－2)＝9＋6－2＝13。\n（2）按定义展开：x⊕(2x－1)＝x²－x(2x－1)＋(2x－1)＝－x²＋3x－1。\n由 －x²＋3x－1＝k 移项整理得：x²－3x＋(k＋1)＝0。\n因为方程有两个不相等的实数根，所以 Δ＝(－3)²－4×1×(k＋1)＝5－4k＞0，\n解得 k＜5/4。\n（3）当 a＝2 时，2⊕b＝2²－2b＋b＝4－b；\nb⊕2＝b²－2b＋2。\n由 4－b＝b²－2b＋2 整理得 b²－b－2＝0，即 (b－2)(b＋1)＝0，\n解得 b₁＝2，b₂＝－1。","explanation":"代入表达式（如 2x－1 或负数 －2）时务必加括号，防止去括号时符号出错；第三问新运算不一定满足交换律，千万不能主观以为 b 只能等于 2。"}]};
